-- LifeLine 1.2.0 - versione applicativa, regole del motore salvate per ogni turno (replay) + 65 modelli di chiamata (11 nuovi, SIC_056 disattivato in attesa di revisione)
UPDATE lifeline_settings SET value = '1.2.0' WHERE key_name = 'app_version';

-- Struttura: le regole (versione, meccaniche attive, linee, idle_scale) passate al motore all'avvio del turno.
-- I turni precedenti restano con rules_json NULL: si rigiocano con le regole di versione 1.
ALTER TABLE lifeline_shifts
    ADD COLUMN rules_json JSON NULL AFTER client_version;

-- Modelli: i nuovi vengono inseriti (SIC_056 con is_active = 0), gli esistenti aggiornati
-- (content_version sale solo se il contenuto cambia; is_active non viene toccato).

SET NAMES utf8mb4;

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_003', 'Farmacia di turno', 'impropria', 1, 1, 90, 1, 'sera,notte', 0, 0, '{"code":"IMP_003","title":"Farmacia di turno","category":"impropria","phase":1,"difficulty":1,"weight":90,"min_rank":1,"time_bands":["sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,3]},"req":{"choice":[{"text":"No no, nessuna emergenza, per carità. Mi serve solo un collirio.","display":"Nessuna emergenza: cerca un collirio","detail_text":"Nessun dolore, è solo per gli occhi un po'' irritati.","detail_display":"Nessun sintomo rilevante","me_text":"Io sto benissimo, grazie. Sono sola, ma è solo per il collirio.","me_display":"Sta bene, è sola in casa","adv":"La farmacia di turno è indicata sulla porta di ogni farmacia e sul sito del Comune. Questo numero serve per le emergenze.","adv_r":"Ah, giusto, sulla porta! Grazie, scusi ancora.","event":"impropria.informazioni","agencies":[]},{"text":"Beh… mia figlia ha la febbre a 39 da stasera, volevo prendere uno sciroppo.","display":"La figlia ha febbre a 39, cerca un antipiretico","detail_text":"È un po'' abbattuta ma gioca, beve, risponde normalmente.","detail_display":"Bambina vigile, beve e risponde","me_text":"Io bene, solo un po'' in pensiero. Mio marito è di turno, sono a casa con lei.","me_display":"Sta bene, è in casa con la bambina","adv":"Per la febbre può sentire la guardia medica. Se la bambina diventa molto sonnolenta, respira male o ha macchie sulla pelle, richiami subito il 112.","adv_r":"Va bene, chiamo la guardia medica. Grazie mille.","event":"impropria.informazioni","agencies":[]},{"text":"Ecco… è per mio marito. Ha un dolore al petto da un''ora, pensavo a un antiacido…","display":"Il marito ha dolore al petto da un''ora","detail_text":"Gli prende tutto il petto e va verso il braccio sinistro… ed è tutto sudato.","detail_display":"Dolore al petto irradiato al braccio sinistro, sudorazione","me_text":"Io… sono un po'' agitata. Siamo soli, lui è sul divano, è pallido, non l''ho mai visto così.","me_display":"Agitata; il marito è sul divano, pallido","adv":"Lo faccia stare seduto, fermo, e non gli dia niente da mangiare o da bere. Apra la porta di casa: le mando un''ambulanza.","adv_r":"Un''ambulanza? Oddio… va bene, apro la porta.","event":"sanitaria.dolore_toracico","agencies":["118"]}],"weights":[55,30,15]}},"caller":{"gender":"f","phone_type":"any","panic_start":5,"ring_patience_s":60,"hold_patience_s":90,"reliability":1,"callback_chance":0.3,"voice":{"age":"adult"}},"opening":{"calm":"Salve, scusi il disturbo… volevo sapere qual è la farmacia di turno stanotte.","panic":"Salve, scusi… mi serve una farmacia aperta, qual è quella di turno?"},"facts":{"richiesta":{"display":"{req.display}"},"stato":{"display":"{req.detail_display}"},"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"chiamante":{"label":"Come sta chi chiama","display":"{req.me_display}"}},"nodes":[{"id":"q_emergenza","label":"Per chi le serve? C''è qualcuno che sta male adesso?","cost_s":6,"reveals":["richiesta"],"reply":{"calm":"{req.text}","panic":"{req.text}"}},{"id":"q_dettagli","label":"Mi descriva i sintomi: da quanto tempo e come sta adesso?","cost_s":8,"requires":["q_emergenza"],"reveals":["stato"],"reply":{"calm":"{req.detail_text}","panic":"{req.detail_text}"}},{"id":"q_dove","label":"Da dove chiama? Mi dica l''indirizzo.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Da casa, in {location.street} {location.number}.","panic":"{location.street} {location.number}."}},{"id":"q_lei","label":"E lei come si sente adesso? È da sola in casa?","cost_s":5,"reveals":["chiamante"],"reply":{"calm":"{req.me_text}","panic":"{req.me_text}"}},{"id":"a_indica","type":"reassure","label":"{req.adv}","cost_s":7,"panic_delta":-10,"requires":["q_emergenza"],"reply":{"calm":"{req.adv_r}","panic":"Va bene… va bene, grazie."}}],"truth":{"event_type":"{req.event}","agencies_required":["{req.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1500},"critical_facts":["richiesta"],"hint_debrief":"Le chiamate per informazioni vanno chiuse in fretta, ma solo dopo aver escluso un''emergenza: a volte chi chiede una farmacia sta descrivendo un infarto."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_004', 'Scherzo telefonico', 'impropria', 1, 2, 80, 1, 'pomeriggio,sera', 0, 0, '{"code":"IMP_004","title":"Scherzo telefonico","category":"impropria","phase":1,"difficulty":2,"weight":80,"min_rank":1,"time_bands":["pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro"],"floor":[0,0]},"prank":{"choice":[{"opening":"(risatine in sottofondo) Pronto… c''è un incendio… sulla Luna!","where":"Sulla Luna, gliel''ho detto! (risate)","where_display":"Dice «sulla Luna», tra le risate"},{"opening":"C''è… c''è un incendio in {location.street}! (una risata soffocata)","where":"Ehm… in {location.street}… al… al numero mille! (risate)","where_display":"{location.street} «numero mille», tra le risate"},{"opening":"Pronto, polizia? Il mio amico è stato rapito dagli alieni!","where":"Nel campo dietro la scuola… anzi no, su Marte!","where_display":"Indicazioni contraddittorie, tra le risate"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":5,"ring_patience_s":20,"hold_patience_s":10,"reliability":0.3,"callback_chance":0.15,"voice":{"age":"child"}},"opening":{"calm":"{prank.opening}","panic":"{prank.opening}"},"facts":{"indirizzo":{"display":"{prank.where_display}"},"evento":{"display":"Racconto confuso, cambia versione"},"ambiente":{"label":"Rumori di fondo","display":"Risate di altri ragazzi, nessun rumore di emergenza"},"adulto":{"label":"Adulto al telefono","display":"La madre conferma: nessuna emergenza, i bambini giocavano col suo telefono"}},"nodes":[{"id":"q_dove","label":"Dove si trova esattamente?","cost_s":5,"reveals":["indirizzo"],"reply":{"calm":"{prank.where}","panic":"{prank.where}"}},{"id":"q_ripeti","label":"Mi ripeta con calma cosa sta succedendo.","cost_s":6,"reveals":["evento"],"reply":{"calm":"Eh… c''è… c''è un problema grosso! (fruscio, qualcuno gli suggerisce qualcosa)","panic":"C''è un problema grosso!"}},{"id":"q_ambiente","label":"Sento delle voci. Chi c''è lì con te?","cost_s":5,"reveals":["ambiente"],"reply":{"calm":"Nessuno! (risate in sottofondo: «dai, digli che…»)","panic":"Nessuno, nessuno!"}},{"id":"q_adulto","label":"Quanti anni hai? Passami un adulto, per favore.","cost_s":5,"ends_call":true,"reply":{"calm":"(risate, poi riattaccano)","panic":"(riattaccano)"}},{"id":"q_adulto_passa","label":"C''è la mamma o il papà? Vai a chiamarli e passameli, per favore.","cost_s":8,"sets_flag":"adulto","hidden_if_flag":"adulto","reply":{"calm":"Ehm… (risate, poi una voce lontana: «Chi è al telefono?!») Mamma…","panic":"(silenzio, poi una voce di donna che si avvicina)"},"switch_caller":{"name":"La madre","gender":"f","voice":{"age":"adult"},"panic_start":25,"reliability":1,"opening":{"calm":"Pronto? Sono la mamma… mi scusi tantissimo, ha preso il mio telefono. Qui non c''è nessuna emergenza.","panic":"Pronto?! Mi scusi, mi scusi… stavano giocando col mio telefono, non c''è niente!"}}},{"id":"q_conferma","label":"Signora, mi conferma che lì non ha bisogno di aiuto?","cost_s":5,"requires_flag":"adulto","reveals":["adulto"],"reply":{"calm":"No, no, stiamo tutti bene. Adesso gli faccio una bella ramanzina. Mi scusi ancora.","panic":"No, nessuna emergenza, davvero. Mi scusi."}},{"id":"a_spiega","type":"reassure","label":"Questo numero serve a chi sta male davvero: se chiamate per gioco, qualcun altro aspetta.","cost_s":6,"panic_delta":0,"reply":{"calm":"(silenzio… poi, a bassa voce) Scusi.","panic":"(silenzio) …scusi."}}],"truth":{"event_type":"impropria.scherzo","agencies_required":[],"severity":{"optimal_s":60,"acceptable_s":120,"limit_s":600},"critical_facts":["indirizzo"],"hint_debrief":"Uno scherzo si riconosce da incoerenze e rumori di fondo; va chiuso rapidamente per liberare la linea, ma solo dopo un paio di verifiche."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_046', 'Chiamata muta', 'impropria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"IMP_046","title":"Chiamata muta","category":"impropria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,3]},"sc":{"choice":[{"r":"(fruscio continuo, passi, una voce lontana che parla d''altro e ride)","rd":"Fruscio e voci lontane, nessuno risponde","k":"(nessuna reazione, il fruscio continua)","kd":"Nessun tasto premuto","l":"(sembra una tasca: passi, un''auto che passa, una radio)","ld":"Rumori di strada, come un telefono in tasca","dv":"(solo il fruscio, nessuno risponde)","dvd":"Nessuna risposta","event":"impropria.errore","ag":[],"acc":["impropria.chiamata_muta"],"sev":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"hint":"Una chiamata muta non si chiude subito: si ascolta e si chiede di premere un tasto. Qui era un telefono in tasca: dopo le verifiche, chiuderla era giusto.","ra":"(fruscio continuo, qualcuno ride lontano)"},{"r":"(un respiro affannoso… una voce impastata) «…aiu… non…»","rd":"Respiro affannoso, parole impastate","k":"(si sente un tasto premuto, poi un altro)","kd":"Ha premuto i tasti su richiesta","l":"(una televisione accesa, un gemito ogni tanto)","ld":"TV accesa, gemiti","dv":"(una voce faticosa) «…{location.street}… {location.number}…»","dvd":"{location.street} {location.number} (detto a fatica)","event":"sanitaria.ictus","ag":["118"],"acc":["sanitaria.malore","sanitaria.incosciente"],"sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"hint":"Respiro affannoso, parole impastate e tasti premuti su richiesta: dietro il silenzio c''era una persona che non riesce più a parlare, probabilmente un ictus. Ascoltare e insistere ha dato l''indirizzo.","ra":"(silenzio, un respiro più lento… poi un colpo sul telefono, come un sì)"},{"r":"(una vocina) «Ciao! Chi sei? Io sono Sofia!»","rd":"Voce di bambina che gioca","k":"(bip bip bip, risatine)","kd":"Tasti premuti a caso, risate","l":"(una mamma in lontananza: «Sofia, dov''è il mio telefono?»)","ld":"Voce di un adulto che cerca il telefono","dv":"(la bambina) «Io abito nella casa gialla!»","dvd":"«La casa gialla» (bambina)","event":"impropria.errore","ag":[],"acc":["impropria.scherzo"],"sev":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"hint":"Una bambina che gioca col telefono della mamma: si ascolta, si verifica che non ci sia un''emergenza e si chiude con gentilezza.","ra":"«Va bene! Ciao!» (risate)"}],"weights":[45,25,30]}},"caller":{"gender":"any","phone_type":"any","panic_start":20,"ring_patience_s":40,"hold_patience_s":30,"reliability":1,"callback_chance":0.2},"opening":{"calm":"(silenzio… un fruscio)","panic":"(silenzio… un fruscio)"},"facts":{"indirizzo":{"display":"{sc.dvd}"},"voce":{"label":"Cosa si sente","display":"{sc.rd}"},"segnale":{"label":"Risposta ai tasti","display":"{sc.kd}"},"ambiente":{"label":"Rumori di fondo","display":"{sc.ld}"}},"nodes":[{"id":"q_parla","label":"Pronto, 112. Mi sente? Mi dica dove si trova.","cost_s":6,"reveals":["voce"],"reply":{"calm":"{sc.r}","panic":"{sc.r}"}},{"id":"q_tasto","label":"Se ha bisogno di aiuto e non può parlare, prema un tasto del telefono.","cost_s":8,"reveals":["segnale"],"reply":{"calm":"{sc.k}","panic":"{sc.k}"}},{"id":"q_ascolta","label":"Resto in ascolto qualche secondo in silenzio.","cost_s":10,"reveals":["ambiente"],"reply":{"calm":"{sc.l}","panic":"{sc.l}"}},{"id":"q_dove","label":"Se mi sente, provi a dirmi l''indirizzo.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{sc.dv}","panic":"{sc.dv}"},"requires":["q_tasto"]},{"id":"a_resto","type":"reassure","label":"Resto in linea con lei. Se non può parlare, faccia un rumore qualsiasi: la sento.","cost_s":8,"panic_delta":-10,"reply":{"calm":"{sc.ra}","panic":"{sc.ra}"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":"{sc.ag}","severity":"{sc.sev}","critical_facts":["segnale","ambiente"],"hint_debrief":"{sc.hint}"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_047', 'Richiesta che non è un''emergenza', 'impropria', 1, 1, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"IMP_047","title":"Richiesta che non è un''emergenza","category":"impropria","phase":1,"difficulty":1,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"sc":{"choice":[{"r":"Un''auto è parcheggiata davanti al mio passo carrabile da due ore e devo uscire per andare al lavoro.","rd":"Auto davanti al passo carrabile","c":"Io sto bene, sono solo nervos{g.o}: devo essere al lavoro tra venti minuti!","cd":"Sta bene, solo innervosit{g.o}","i":"Per l''auto sul passo carrabile deve chiamare la Polizia locale: il numero è sul sito del Comune. Il 112 serve per le emergenze."},{"r":"Ieri mi hanno rubato la bicicletta in stazione, volevo fare la denuncia.","rd":"Furto di una bicicletta avvenuto ieri, vuole denunciare","c":"Bene, bene. Solo scocciat{g.o}, era una bici nuova.","cd":"Sta bene","i":"La denuncia si fa in caserma o in questura, anche su appuntamento: il 112 serve per le emergenze in corso."},{"r":"Ho mal di gola da tre giorni, volevo sapere a che ora apre la guardia medica.","rd":"Mal di gola da tre giorni, chiede gli orari della guardia medica","c":"Ho un po'' di febbre, trentasette e mezzo. Deglutisco a fatica, ma respiro bene.","cd":"Febbricola, deglutisce a fatica, respira bene","i":"Per il mal di gola può rivolgersi al suo medico o alla guardia medica: se respira male o la febbre sale molto, richiami."},{"r":"Sono in coda da mezz''ora sulla provinciale, volevo sapere se c''è un incidente.","rd":"Chiede informazioni sul traffico","cd":"Sta bene, è in coda in auto","i":"Per il traffico può ascoltare le notizie sulla viabilità. Se vede un incidente con feriti, richiami subito il 112.","c":"Io sto bene, sono in macchina, siamo tutti fermi in coda."}]}},"caller":{"gender":"any","phone_type":"any","panic_start":5,"ring_patience_s":60,"hold_patience_s":80,"reliability":1,"callback_chance":0.2},"opening":{"calm":"Buongiorno, chiamo perché ho un problema, forse non è il numero giusto…","panic":"Buongiorno, ho un problema e non so chi chiamare."},"facts":{"richiesta":{"display":"{sc.rd}"},"urgenza":{"label":"Pericolo","display":"Nessuna persona in pericolo"},"stato":{"label":"Come sta","display":"{sc.cd}"}},"nodes":[{"id":"q_cosa","label":"Mi dica pure: cosa succede?","cost_s":6,"reveals":["richiesta"],"reply":{"calm":"{sc.r}","panic":"{sc.r}"}},{"id":"q_urgenza","label":"C''è qualcuno in pericolo o che si è fatto male?","cost_s":5,"reveals":["urgenza"],"reply":{"calm":"No, no, nessuno sta male.","panic":"No, no, nessuno sta male."}},{"id":"q_come","label":"E lei come si sente adesso? Ha bisogno di qualcosa?","cost_s":5,"reveals":["stato"],"reply":{"calm":"{sc.c}","panic":"{sc.c}"}},{"id":"a_indirizza","type":"reassure","label":"{sc.i}","cost_s":7,"panic_delta":-5,"reply":{"calm":"Ah, ecco, non lo sapevo. Grazie, scusi il disturbo.","panic":"Va bene… grazie."}}],"truth":{"event_type":"impropria.informazioni","agencies_required":[],"severity":{"optimal_s":60,"acceptable_s":120,"limit_s":600},"critical_facts":["urgenza"],"hint_debrief":"Richieste come un passo carrabile bloccato o una denuncia vanno indirizzate al servizio giusto (polizia locale, caserma, guardia medica) e chiuse in fretta: la linea serve alle emergenze."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_048', 'Un anziano che vuole parlare', 'impropria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"IMP_048","title":"Un anziano che vuole parlare","category":"impropria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"r":"Sto bene, sto bene… è che da quando è morta mia moglie la sera è lunga, e nessuno mi chiama.","rd":"Solitudine: nessun problema di salute riferito","d":"No, niente, ho mangiato, ho preso le mie pastiglie.","dd":"Nessun sintomo","event":"impropria.informazioni","ag":[],"acc":[],"sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400},"hint":"Chi chiama «solo per sentire una voce» va ascoltato fino in fondo: qui era solitudine, e chiudere con gentilezza dopo aver escluso problemi di salute era la scelta giusta."},{"r":"Beh… ieri sono caduto in bagno e da allora sto sulla poltrona, non riesco più ad alzarmi. Ma non volevo disturbare.","rd":"Caduto ieri, da allora non riesce ad alzarsi dalla poltrona","d":"Mi fa male l''anca, e non ho mangiato da ieri.","dd":"Dolore all''anca, digiuno da ieri","event":"sanitaria.trauma_caduta","ag":["118","115"],"acc":["sanitaria.malore"],"sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400},"hint":"Dietro «non volevo disturbare» c''era una caduta di ieri: una persona sola a terra o in poltrona da ore, con la porta chiusa a chiave, ha bisogno del 118 e dei Vigili del fuoco per entrare."},{"r":"Mah… stasera mi sento strano, il braccio sinistro mi formicola e la bocca è un po'' addormentata.","rd":"Formicolio al braccio sinistro e alla bocca da stasera","d":"E faccio fatica a trovare le parole… mi scusi.","dd":"Fatica a trovare le parole","event":"sanitaria.ictus","ag":["118"],"acc":["sanitaria.malore"],"sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"hint":"Formicolio a un braccio, bocca «addormentata» e fatica a trovare le parole sono segni di ictus anche se chi chiama minimizza: ogni minuto conta."}],"weights":[45,30,25]}},"caller":{"gender":"m","phone_type":"landline","panic_start":5,"ring_patience_s":60,"hold_patience_s":60,"reliability":1,"callback_chance":0.7,"voice":{"age":"elderly"}},"opening":{"calm":"Buonasera… mi scusi l''ora, volevo solo sentire una voce.","panic":"Buonasera… mi scusi se disturbo."},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"richiesta":{"display":"{sc.rd}"},"stato":{"display":"{sc.dd}"},"accesso":{"display":"Vive solo; la porta è chiusa a chiave"}},"nodes":[{"id":"q_come","label":"Come sta, signor {caller_surname}? Ha bisogno di qualcosa?","cost_s":8,"reveals":["richiesta"],"reply":{"calm":"{sc.r}","panic":"{sc.r}"}},{"id":"q_salute","label":"Si sente bene? Ha dolori, ha mangiato, ha preso le medicine?","cost_s":7,"reveals":["stato"],"reply":{"calm":"{sc.d}","panic":"{sc.d}"},"requires":["q_come"]},{"id":"q_dove","label":"Mi dice dove abita, signor {caller_surname}? Via e numero.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street} {location.number}.","panic":"{location.street} {location.number}."}},{"id":"q_solo","label":"Vive da solo? Qualcuno può aprire la porta?","cost_s":5,"reveals":["accesso"],"reply":{"calm":"Sì, da solo. La porta è chiusa a chiave, le chiavi le ho io.","panic":"Sì, da solo. La porta è chiusa a chiave, le chiavi le ho io."}},{"id":"a_rassicura","type":"reassure","label":"Ha fatto bene a chiamare. Non si preoccupi di disturbare.","cost_s":6,"panic_delta":-5,"reply":{"calm":"Grazie… lei è gentile.","panic":"Grazie…"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":"{sc.ag}","severity":"{sc.sev}","critical_facts":["richiesta","stato"],"hint_debrief":"{sc.hint}"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_061', 'Chiamante abituale ubriaco', 'impropria', 1, 4, 60, 2, 'sera,notte', 0, 0, '{"code":"IMP_061","title":"Chiamante abituale ubriaco","category":"impropria","phase":1,"difficulty":4,"weight":60,"min_rank":2,"time_bands":["sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,3]},"sc":{"choice":[{"why":"Volevo parlare col maresciallo… quello simpatico, con i baffi. Il vicino tiene la musica alta, e io non dormo… (una risata)","why_d":"Vuole parlare «col maresciallo»; lamenta musica alta del vicino","male":"Male? No… sto benone, io. Benone! (una risata) Mi fa male solo la testa per il vino.","male_d":"Dice di non essersi fatto niente","chi":"Nessuno… la mia ex moglie se n''è andata nel ''98. Ci sono io e il gatto.","event":"impropria.informazioni","ag":[],"acc":[],"sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400},"hint":"Il chiamante abituale e ubriaco va comunque ascoltato quel tanto che basta: chiedere se si è fatto male esclude l''emergenza, e poi si può chiudere con fermezza ma senza aggressività."},{"why":"Niente… volevo fare due chiacchiere… stasera sono un po'' giù. (una risata) Sono anche caduto, ma niente.","why_d":"Vuole «fare due chiacchiere»; accenna a una caduta","male":"Ah… sì, sono caduto dalle scale del condominio… c''è un po'' di sangue sulla testa… ma niente, eh. Mi gira un po''.","male_d":"Caduto dalle scale, sangue dalla testa, capogiri","chi":"Nessuno… sono seduto per terra vicino al telefono. Non ho chiuso neanche la porta.","event":"sanitaria.trauma_caduta","ag":["118"],"acc":["sanitaria.malore","sanitaria.ferita"],"sev":{"optimal_s":300,"acceptable_s":900,"limit_s":1800},"hint":"Anche il chiamante abituale e ubriaco può farsi male davvero: una caduta dalle scale con sangue dalla testa e capogiri in una persona alcolizzata è un trauma cranico finché non si dimostra il contrario. Chiedere sempre se si è fatto male."}],"weights":[70,30]}},"caller":{"gender":"m","phone_type":"landline","panic_start":15,"ring_patience_s":60,"hold_patience_s":60,"reliability":0.6,"callback_chance":0.8,"voice":{"age":"adult","style":"slurred"}},"opening":{"calm":["Pronto?… (una risata) Sono io, {caller_first}… {caller_first} {caller_surname}, mi conoscete, no?","Pronto, carabinieri? Ah no… cioè, sì… Sono {caller_first}! Il solito {caller_first}… (una risata)"],"panic":"Pronto?! Sono {caller_first}… non riattaccate, eh, stavolta non riattaccate…"},"callback_opening":{"calm":"Pronto… sono di nuovo io, {caller_first}… è caduta la linea. O l''ha messa giù lei? (una risata)","panic":"Mi avete chiuso il telefono in faccia! Sono {caller_first}!"},"idle_lines":{"calm":["Pronto?… C''è? Mi sente? (una risata)","Ehi… si è addormentato anche lei?"],"panic":["Pronto?! Non mi lasci qui!"]},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text}"},"richiesta":{"label":"Perché chiama","display":"{sc.why_d}"},"ferite":{"label":"Ferite","display":"{sc.male_d}"},"alcol":{"label":"Alcol","display":"Ha bevuto molto, parla impastato"},"persone":{"display":"Solo in casa"}},"nodes":[{"id":"q_cosa","label":"Signor {caller_surname}, mi dica: perché ha chiamato il 112?","cost_s":7,"reveals":["richiesta"],"reply":{"calm":"{sc.why}","panic":"{sc.why}"}},{"id":"q_dove","label":"Da dove chiama? Mi dia l''indirizzo.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Sempre da casa… {location.street}, il {location.number}… lo sapete! (una risata)","panic":"{location.street} {location.number}… lo sapete…"},"error":{"threshold":101,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"calm":"{location.street}… il… {location.number_wrong}? Sì, {location.number_wrong}. Credo. (una risata)"}}},{"id":"q_male","label":"Si è fatto male? È caduto? Perde sangue?","cost_s":6,"reveals":["ferite"],"reply":{"calm":"{sc.male}","panic":"{sc.male}"}},{"id":"q_bevuto","label":"Ha bevuto stasera?","cost_s":4,"reveals":["alcol"],"reply":{"calm":"Un bicchiere… due… (una risata) Chi li conta, scusi!","panic":"Un po''… un po'', sì."}},{"id":"q_solo","label":"C''è qualcuno con lei?","cost_s":4,"reveals":["persone"],"reply":{"calm":"{sc.chi}","panic":"{sc.chi}"}},{"id":"a_calma","type":"reassure","label":"Signor {caller_surname}, la ascolto. Mi risponda con calma e restiamo sulle cose importanti.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Va bene, va bene… lei è gentile, mica come quello di ieri.","panic":"Ok… ok, calma."}},{"id":"a_chiudo","type":"reassure","label":"Signor {caller_surname}, questa linea serve per le emergenze: se continua così chiudo la chiamata.","cost_s":5,"panic_delta":10,"ends_call":true,"reply":{"calm":"Ah sì? E allora chiudo io! Tanto non vi frega niente… (riattacca)","panic":"Bravi, bravi, chiudete pure! (riattacca)"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":"{sc.ag}","severity":"{sc.sev}","critical_facts":["indirizzo","ferite"],"hint_debrief":"{sc.hint}"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_063', 'Scherzo, o forse no', 'impropria', 1, 5, 65, 2, 'mattina,pomeriggio,sera', 0, 0, '{"code":"IMP_063","title":"Scherzo, o forse no","category":"impropria","phase":1,"difficulty":5,"weight":65,"min_rank":2,"time_bands":["mattina","pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro"],"floor":[1,4]},"sc":{"choice":[{"sfondo":"Quale suono? (risate) Ah, è la play! Stiamo giocando alle macchine!","sfondo_d":"Rumore di videogioco e risate","addr":"(una risata) Te l''ho detto: numero mille! Anzi, un milione!","addr_d":"«{location.street} numero mille», tra le risate","grandi":"La mamma è di là che lavora al computer… (sussurrando) non dirglielo, eh!","grandi_d":"La madre è in casa","adv":"Questo numero serve a chi sta male davvero: mentre giochi tu, qualcun altro aspetta. Adesso vai a dirlo alla mamma, per favore.","adv_r":"(silenzio) …Va bene. Scusa.","event":"impropria.scherzo","ag":[],"sev":{"optimal_s":60,"acceptable_s":120,"limit_s":600},"hint":"Risate, indirizzi impossibili e una mamma in casa: era uno scherzo. Chiedere cosa si sente sullo sfondo è comunque il controllo giusto prima di chiudere."},{"sfondo":"Ah… quello? Suona da un po''… è quella cosa sul soffitto in cucina… (silenzio) c''è un po'' di fumo, ma è sempre così quando la mamma cucina…","sfondo_d":"Allarme antifumo che suona in cucina, c''è fumo","addr":"(sottovoce) {location.street} {location.number}… al {location.floor_text}. Non era vero l''incendio sulla Luna…","addr_d":"{location.street} {location.number}, {location.floor_text}","grandi":"No… la mamma è andata a fare la spesa, siamo io e mio fratello piccolo. Lei ha lasciato la pentola sul fuoco, ha detto di non toccare.","grandi_d":"Due bambini soli in casa; pentola lasciata sul fuoco","adv":"Ascoltami bene: prendi tuo fratello e uscite subito di casa, senza prendere niente. Chiudete la porta dietro di voi e andate dai vicini. Non tornate dentro.","adv_r":"Va bene… vieni, Tommi, vieni! (silenzio, poi passi di corsa e una porta che sbatte) Siamo fuori! Siamo sul pianerottolo!","event":"incendio_tecnico.incendio_abitazione","ag":["115"],"sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"hint":"Lo scherzo nascondeva un allarme vero: il bip sullo sfondo era il rilevatore di fumo, con due bambini soli e una pentola sul fuoco. Ascoltare lo sfondo prima di chiudere ha cambiato tutto: Vigili del fuoco e bambini fuori casa subito."}],"weights":[65,35]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":5,"ring_patience_s":20,"hold_patience_s":10,"reliability":1,"callback_chance":0.3,"voice":{"age":"child"}},"opening":{"calm":"(risate) Pronto, pompieri? C''è un incendio… sulla Luna! (risate soffocate, e sotto un bip insistente)","panic":"(risate) Pronto? C''è un incendio! Sulla Luna! (bip… bip…)"},"facts":{"indirizzo":{"display":"{sc.addr_d}"},"sfondo":{"label":"Rumori di fondo","display":"{sc.sfondo_d}"},"adulti":{"label":"Adulti in casa","display":"{sc.grandi_d}"},"evento":{"display":"Racconto inventato, tra le risate"}},"nodes":[{"id":"q_dove","label":"Dove abiti? Come si chiama la tua via?","cost_s":5,"reveals":["indirizzo"],"reply":{"calm":"{sc.addr}","panic":"{sc.addr}"},"error":{"unless_flag":"sfondo","threshold":0,"chance":1,"fact":"indirizzo","display":"«{location.street} numero mille», tra le risate","reply":{"calm":"In {location.street}… numero… mille! (risate)","panic":"{location.street}, numero mille! (risate)"}}},{"id":"q_cosa","label":"Raccontami bene: cosa sta bruciando?","cost_s":6,"reveals":["evento"],"reply":{"calm":"La Luna! Ci sono gli alieni che fanno il barbecue! (risate)","panic":"La Luna! (risate)"}},{"id":"q_sfondo","label":"Aspetta. Cos''è quel suono che sento dietro di te?","cost_s":6,"reveals":["sfondo"],"sets_flag":"sfondo","reply":{"calm":"{sc.sfondo}","panic":"{sc.sfondo}"}},{"id":"q_grandi","label":"C''è un grande in casa con te?","cost_s":5,"reveals":["adulti"],"reply":{"calm":"{sc.grandi}","panic":"{sc.grandi}"}},{"id":"a_esci","type":"reassure","label":"{sc.adv}","cost_s":7,"panic_delta":-10,"requires":["q_sfondo","q_grandi"],"reply":{"calm":"{sc.adv_r}","panic":"{sc.adv_r}"}},{"id":"q_scherzo","label":"È uno scherzo, vero? Questa linea serve per le emergenze vere.","cost_s":5,"ends_call":true,"reply":{"calm":"(risate) Ciao! (riattaccano)","panic":"(riattaccano)"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":[],"agencies_required":"{sc.ag}","agencies_acceptable":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","sfondo"],"hint_debrief":"{sc.hint}"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_002', 'Cassonetto in fiamme', 'incendio_tecnico', 1, 1, 110, 1, 'pomeriggio,sera,notte', 1, 0, '{"code":"INC_002","title":"Cassonetto in fiamme","category":"incendio_tecnico","phase":1,"difficulty":1,"weight":110,"min_rank":1,"time_bands":["pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"fire":{"choice":[{"text":"Un cassonetto della plastica, le fiamme saranno alte un metro.","display":"Un cassonetto, fiamme di circa un metro","danger_text":"No, è in mezzo al parcheggio, lontano da tutto.","danger_display":"Lontano da case e auto","text_p":"Un cassonetto! Le fiamme saranno un metro, fa un fumo nero!"},{"text":"Due cassonetti, e il fuoco sta arrivando a una macchina parcheggiata!","display":"Due cassonetti, fiamme vicine a un''auto","danger_text":"Sì! C''è una macchina attaccata, e sopra ci sono le finestre delle case!","danger_display":"Auto parcheggiata e finestre di abitazioni vicine","text_p":"Due cassonetti! Il fuoco sta per prendere la macchina!"}],"weights":[65,35]},"people":{"choice":[{"text":"No, qui non c''è nessuno, solo io che guardo.","display":"Nessun ferito","agencies":[]},{"text":"Un signore ha provato a spegnerlo con un secchio e si è bruciato la mano.","display":"Un uomo si è ustionato la mano","agencies":["118"]}],"weights":[80,20]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":15,"ring_patience_s":25,"hold_patience_s":35,"reliability":1,"callback_chance":0.2,"voice":{"age":"adult"}},"opening":{"calm":["Buonasera, sto passando in {location.street}: c''è un cassonetto che brucia.","Salve, guardi, qui in {location.street} sta andando a fuoco un cassonetto."],"panic":"Pronto! C''è un incendio qui in {location.street}, un cassonetto!","hyst":"Pronto! Brucia tutto! Il cassonetto in {location.street}, le fiamme sono altissime!"},"callback_opening":{"calm":"Sono di nuovo io, per il cassonetto in {location.street}… non è ancora arrivato nessuno.","panic":"Di nuovo io! Il cassonetto in {location.street} brucia sempre di più, dove siete?!"},"deterioration":[{"after_s":300,"sets_flag":"allarga","panic":15,"line":{"calm":"Adesso ha preso anche il cassonetto vicino, il fumo è nerissimo.","panic":"Brucia anche quello vicino! Il fumo è nero, non si respira!"}},{"after_s":600,"panic":15,"line":{"calm":"Si è sciolta la plastica… le fiamme stanno arrivando alla siepe.","panic":"Le fiamme toccano la siepe! Sta andando tutto a fuoco!"}}],"facts":{"indirizzo":{"display":"{location.street} altezza civico {location.number}, presso {location.landmark} ({location.zone_name})"},"incendio":{"display":"{fire.display}"},"pericoli":{"display":"{fire.danger_display}"},"persone":{"display":"{people.display}"}},"nodes":[{"id":"q_dove","label":"Dove si trova esattamente? Mi dia un civico o un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["In {location.street}, all''altezza del {location.number}, c''è {location.landmark} lì vicino.","Sempre {location.street}, davanti al numero {location.number}. C''è {location.landmark} lì vicino."],"panic":"In {location.street}, c''è {location.landmark} lì vicino!","hyst":"{location.street}! C''è {location.landmark} lì vicino! Presto!"}},{"id":"q_cosa","label":"Cosa sta bruciando? Quanto sono alte le fiamme?","cost_s":6,"reveals":["incendio"],"reply":{"calm":"{fire.text}","panic":"{fire.text_p}"},"repeat":{"calm":"Come le dicevo: {fire.text}","panic":"Gliel''ho detto! {fire.text_p}"}},{"id":"q_vicino","label":"Il fuoco è vicino a case, auto o alberi?","cost_s":5,"requires":["q_cosa"],"reveals":["pericoli"],"reply":{"calm":"{fire.danger_text}","panic":"{fire.danger_text}"},"reply_flag":{"flag":"allarga","calm":"Adesso brucia anche il cassonetto vicino, e il fumo va sulle case.","panic":"Brucia anche l''altro cassonetto! Il fumo va dritto sulle finestre!"}},{"id":"q_persone","label":"Ci sono persone ferite o in pericolo?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{people.text}","panic":"{people.text}"}},{"id":"a_sicurezza","type":"reassure","label":"Si tenga a distanza e non provi a spegnerlo: i soccorsi stanno arrivando.","cost_s":5,"panic_delta":-10,"reply":{"calm":"D''accordo, resto qui sul marciapiede.","panic":"Va bene, va bene, mi allontano."}}],"truth":{"event_type":"incendio_tecnico.incendio_rifiuti","agencies_required":["115","{people.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","persone"],"hint_debrief":"Chiedere sempre se ci sono feriti: anche un incendio banale può richiedere il 118."},"duplicates":{"chance":0.5,"max":2,"delay_s":[20,150],"near_twin_chance":0.2},"witness_opening":{"calm":"Buonasera, c''è un cassonetto in fiamme in {location.street}, c''è {location.landmark} lì vicino.","panic":"Pronto, un incendio! Un cassonetto in {location.street}!"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_009', 'Fumo da un appartamento', 'incendio_tecnico', 1, 4, 85, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"INC_009","title":"Fumo da un appartamento","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":85,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","duplicates":{"chance":0.6,"max":2,"delay_s":[30,150],"near_twin_chance":0},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[1,5]},"people":{"choice":[{"text":"Ci abita la signora Nadia, è anziana e vive da sola… ho suonato ma non risponde!","display":"Anziana sola in casa, non risponde al campanello","agencies":["115","118"]},{"text":"Credo sia al lavoro… ma sento il suo cane che abbaia come un matto.","display":"Probabilmente nessuno in casa, dentro c''è un cane","agencies":["115"]}],"weights":[60,40]}},"caller":{"gender":"f","phone_type":"any","panic_start":55,"ring_patience_s":30,"hold_patience_s":25,"reliability":0.95,"callback_chance":0.8},"opening":{"calm":"Pronto, esce del fumo da sotto la porta della mia vicina, sul pianerottolo.","panic":"Pronto! C''è fumo, esce fumo dall''appartamento della vicina!","hyst":"Pronto! Fumo! È pieno di fumo, la mia vicina è lì dentro! Aiuto!"},"witness_opening":{"calm":"Buonasera, in {location.street} esce del fumo da una finestra, al {location.floor_text}.","panic":"C''è fumo che esce da una finestra in {location.street}, al {location.floor_text}!"},"callback_opening":{"calm":"Pronto, sono di nuovo io, per il fumo dalla porta della vicina… è caduta la linea.","panic":"Sono io, di prima! Il fumo è sempre di più, non si vede più niente sulle scale!"},"deterioration":[{"after_s":180,"sets_flag":"finestre","panic":20,"line":{"calm":"Adesso il fumo esce anche dalla finestra della cucina… è nero.","panic":"Esce fumo nero dalle finestre! Si vede dalla strada!"}},{"after_s":420,"panic":15,"line":{"calm":"Ho sentito un vetro che si rompe, dentro scoppietta.","panic":"È scoppiato un vetro! Si vedono le fiamme dentro!"}}],"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}"},"persone":{"display":"{people.display}"},"incendio":{"display":"Fumo grigio sempre più denso, odore di bruciato, fiamme non visibili"},"pericoli":{"display":"Nessun odore di gas"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo, via e civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","Siamo in {location.street}, al numero {location.number}."],"panic":"{location.street}, il {location.number}!","hyst":"{location.street}! Il {location.number}! Presto, presto!"},"error":{"threshold":70,"chance":0.35,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}, il {location.number_wrong}! Presto!"}}},{"id":"q_piano","label":"A che piano è l''appartamento?","cost_s":4,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}.","panic":"{location.floor_text}!"}},{"id":"q_persone","label":"Sa se c''è qualcuno dentro?","cost_s":6,"reveals":["persone"],"reply":{"calm":"{people.text}","panic":"{people.text}"}},{"id":"q_fiamme","label":"Vede fiamme o solo fumo? Com''è il fumo?","cost_s":5,"reveals":["incendio"],"reply":{"calm":"Solo fumo grigio, ma sempre di più. Si sente puzza di bruciato.","panic":"Fumo, tanto fumo, puzza di bruciato!"},"reply_flag":{"flag":"finestre","calm":"Adesso il fumo è nero ed esce anche dalle finestre. Le fiamme ancora non le vedo.","panic":"Fumo nero dalle finestre! Brucia tutto!"}},{"id":"q_gas","label":"Sente odore di gas?","cost_s":4,"reveals":["pericoli"],"reply":{"calm":"No, gas no. Solo bruciato.","panic":"No… no, gas no."}},{"id":"a_esci","type":"reassure","label":"Non apra quella porta: esca dal palazzo con gli altri inquilini e aspetti i soccorsi fuori.","cost_s":6,"panic_delta":-18,"reply":{"calm":"D''accordo, avviso gli altri e scendo.","panic":"Sì… sì, scendo subito."}}],"truth":{"event_type":"incendio_tecnico.incendio_abitazione","agencies_required":["{people.agencies}"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","persone"],"hint_debrief":"In un incendio in casa la domanda chiave è chi c''è dentro: una persona che non risponde richiede anche il 118. Più vicini chiamano per lo stesso fumo: vanno accorpati."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_026', 'Persona caduta nel torrente', 'incendio_tecnico', 1, 6, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_026","title":"Persona caduta nel torrente","category":"incendio_tecnico","phase":1,"difficulty":6,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["colline","residenziale"],"floor":[0,0],"streets":["Strada Panoramica","Via San Floriano","Via dei Tigli","Via delle Acacie","Via Collalto"]},"sc":{"choice":[{"p":"Un bambino! Stava giocando sulla riva ed è scivolato, la corrente lo porta via!","pd":"Bambino trascinato dalla corrente","w":"Sì, lo vedo, si tiene a un ramo ogni tanto!","wd":"Visibile, si aggrappa a tratti"},{"p":"Un signore che pescava è scivolato, è in acqua fino al petto, aggrappato a un ramo.","pd":"Pescatore in acqua, aggrappato a un ramo","w":"Sì, è fermo lì, ma dice che non ha più forza nelle braccia.","wd":"Fermo, aggrappato, sta perdendo le forze"},{"p":"Il cane è caduto in acqua e il padrone si è buttato a prenderlo! Adesso non riescono a uscire!","pd":"Uomo entrato in acqua per il cane, non riesce a uscire","w":"Sono tutti e due contro un sasso in mezzo, l''acqua è fortissima.","wd":"Bloccati contro un masso a metà torrente"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":78,"ring_patience_s":25,"hold_patience_s":12,"reliability":0.95,"callback_chance":0.6,"voice":{"age":"adult","style":"breathless"}},"opening":{"calm":"Pronto! C''è una persona nel torrente, la corrente la porta via!","panic":"Pronto! Qualcuno è caduto nel torrente! Presto!","hyst":"Aiuto! È nel torrente! La corrente lo porta via! Correte!"},"deterioration":[{"after_s":150,"sets_flag":"trascinato","panic":20,"line":{"calm":"Non lo vedo più! …No, eccolo, l''acqua l''ha portato più giù!","panic":"Non lo vedo più! È andato sotto! …Eccolo, è più giù!"}},{"after_s":330,"panic":15,"line":{"calm":"La corrente lo sta portando verso il ponte, lo seguo dalla riva.","panic":"Lo porta verso il ponte! Non ce la fa più!"}}],"facts":{"indirizzo":{"display":"Torrente, altezza {location.street} (presso {location.landmark})"},"persone":{"display":"{sc.pd}"},"stato":{"label":"Dove si trova ora","display":"{sc.wd}"}},"nodes":[{"id":"q_dove","label":"Dove siete? Da che strada si arriva al punto del torrente?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Dalla {location.street}, sotto il ponte. Lì vicino c''è {location.landmark}.","panic":"{location.street}! C''è {location.landmark} lì vicino!","hyst":"{location.street}! Il ponte! Correte!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!","hyst":"{location.street_wrong}! Credo! Non lo so!"}}},{"id":"q_chi","label":"Chi è in acqua?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p} Venite, presto!"}},{"id":"q_vede","label":"Lo vede ancora? Dove si trova adesso?","cost_s":5,"reveals":["stato"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Venite, presto!"},"reply_flag":{"flag":"trascinato","calm":"La corrente l''ha portato più giù, verso il ponte. Lo vedo a tratti.","panic":"È più giù! Lo vedo e non lo vedo! Va verso il ponte!"}},{"id":"a_rassicura","type":"reassure","label":"Non entri in acqua: gli lanci qualcosa a cui aggrapparsi e lo segua dalla riva senza perderlo di vista.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Ok, cerco una corda.","panic":"Sì, sì, non entro!"}}],"truth":{"event_type":"incendio_tecnico.soccorso_persona","acceptable_event_types":["sanitaria.soccorso_impervio"],"agencies_required":["115","118"],"severity":{"optimal_s":180,"acceptable_s":360,"limit_s":900},"critical_facts":["indirizzo","persone"],"hint_debrief":"Il soccorso in acqua richiede Vigili del fuoco e 118 insieme. Mai incoraggiare chi chiama a entrare in acqua: si rischiano due vittime."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_027', 'Mia madre non risponde al telefono', 'incendio_tecnico', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_027","title":"Mia madre non risponde al telefono","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","aml":{"available":false},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"s":"Le persiane sono chiuse da ieri, la vicina dice che c''è ancora la posta nella cassetta.","sd":"Persiane chiuse da ieri, posta non ritirata"},{"s":"La vicina mi ha detto che stamattina ha sentito dei lamenti attraverso il muro.","sd":"La vicina ha sentito lamenti dall''interno"}]}},"caller":{"gender":"f","phone_type":"mobile","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.8},"opening":{"calm":"Buonasera, chiamo da Milano: mia madre abita a Valdemara e non risponde al telefono da ieri sera. Ha 84 anni e vive da sola.","panic":"Pronto, mia madre non risponde da ieri, è anziana e vive sola, sono preoccupatissima!"},"callback_opening":{"calm":"Buonasera, ho chiamato prima per mia madre in {location.street}… è caduta la linea.","panic":"Sono di nuovo io, per mia madre! È arrivato qualcuno? Non risponde ancora!"},"deterioration":[{"after_s":900,"sets_flag":"silenzio","panic":15,"line":{"calm":"Mi ha appena scritto la vicina: prima sentiva dei lamenti, adesso non sente più niente.","panic":"La vicina dice che adesso non si sente più niente! Neanche i lamenti!"}}],"facts":{"indirizzo":{"display":"Casa della madre: {location.street} {location.number}, {location.floor_text}"},"segni":{"label":"Segnali","display":"{sc.sd}"},"chiavi":{"label":"Chiavi","display":"Nessuno ha le chiavi a Valdemara"},"salute":{"label":"Salute","display":"Cardiopatica, cammina con il bastone"}},"nodes":[{"id":"q_dove","label":"Qual è l''indirizzo di sua madre, con il piano?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}, al {location.floor_text}.","panic":"{location.street} {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_segni","label":"Qualcuno ha notato qualcosa? Vicini, portinaio?","cost_s":6,"reveals":["segni"],"reply":{"calm":"{sc.s}","panic":"{sc.s} Fate presto!"},"reply_flag":{"flag":"silenzio","calm":"La vicina adesso non sente più niente, nessun rumore.","panic":"Non si sente più niente! Niente!"}},{"id":"q_chiavi","label":"Qualcuno lì vicino ha le chiavi di casa?","cost_s":5,"reveals":["chiavi"],"reply":{"calm":"No… le ho solo io, e sono a trecento chilometri.","panic":"No… le ho solo io, e sono a trecento chilometri. Venite, presto!"}},{"id":"q_salute","label":"Sua madre ha problemi di salute?","cost_s":5,"reveals":["salute"],"reply":{"calm":"È cardiopatica e cammina con il bastone.","panic":"È cardiopatica e cammina con il bastone. Fate presto!"}},{"id":"a_rassicura","type":"reassure","label":"Facciamo verificare subito. Tenga il telefono libero: la richiameranno i soccorritori.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"incendio_tecnico.apertura_porta","acceptable_event_types":["sanitaria.malore","sanitaria.incosciente","incendio_tecnico.soccorso_persona"],"agencies_required":["115","118"],"severity":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400},"critical_facts":["indirizzo","chiavi"],"hint_debrief":"Chi chiama da lontano non è sul posto: il cerchio AML non serve, conta l''indirizzo della persona. Senza chiavi servono i Vigili del fuoco per entrare, con il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_028', 'Auto in fiamme', 'incendio_tecnico', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"INC_028","title":"Auto in fiamme","category":"incendio_tecnico","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.45,"max":2,"delay_s":[20,140],"near_twin_chance":0.15},"witness_opening":{"calm":"Buonasera, in {location.street} c''è una macchina che brucia, si vede il fumo da lontano.","panic":"Pronto, c''è un''auto in fiamme in {location.street}!"},"variables":{"location":{"pool":"stradario","zones":["residenziale","industriale","colline"],"floor":[0,0]},"sc":{"choice":[{"w":"È parcheggiata sotto casa, escono fiamme dal cofano… ci sono altre macchine vicino!","wd":"Auto parcheggiata, fiamme dal cofano, altre auto vicine","p":"No, dentro non c''è nessuno.","pd":"Nessuno a bordo","ag":["115"],"event":"incendio_tecnico.incendio_veicolo"},{"w":"È andata a sbattere contro il guardrail e ha preso fuoco! Il conducente è uscito da solo.","wd":"Incidente contro il guardrail, auto in fiamme","p":"Il conducente è fuori, dice che sta bene, solo spaventato.","pd":"Conducente uscito, illeso","ag":["115","{location.police}"],"event":"incendio_tecnico.incendio_veicolo"},{"w":"C''è fumo dappertutto dentro la macchina, è ferma in mezzo alla strada!","wd":"Fumo nell''abitacolo, auto ferma in carreggiata","p":"C''è un uomo dentro! Non riesce ad aprire la portiera!","pd":"Uomo bloccato a bordo","ag":["115","118"],"event":"incendio_tecnico.incendio_veicolo"}],"weights":[45,30,25]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":55,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.3},"opening":{"calm":"Pronto, c''è una macchina che sta prendendo fuoco!","panic":"Pronto! Una macchina in fiamme, presto!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"incendio":{"display":"{sc.wd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova l''auto? Via e un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, c''è {location.landmark} lì vicino.","panic":"{location.street}! C''è {location.landmark} lì vicino!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicur{g.o}!"}}},{"id":"q_cosa","label":"Cosa vede esattamente? Dove sono le fiamme?","cost_s":6,"reveals":["incendio"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Sbrigatevi!"}},{"id":"q_persone","label":"C''è qualcuno dentro o vicino all''auto?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p} Sbrigatevi!"}},{"id":"a_rassicura","type":"reassure","label":"Si allontani di almeno cinquanta metri e tenga lontani i curiosi: il serbatoio può esplodere.","cost_s":6,"panic_delta":-12,"reply":{"calm":"D''accordo, mi allontano.","panic":"Ok! Ci allontaniamo!"}}],"truth":{"event_type":"{sc.event}","agencies_required":"{sc.ag}","agencies_acceptable":["PS","CC"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","persone"],"hint_debrief":"Un''auto in fiamme è un lavoro per i Vigili del fuoco; se c''è qualcuno bloccato a bordo serve anche il 118, se c''è stato un incidente le forze dell''ordine."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_029', 'Odore di gas', 'incendio_tecnico', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_029","title":"Odore di gas","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,4]},"sc":{"choice":[{"w":"Sul pianerottolo c''è un odore fortissimo, viene dalla porta del signor Bruno. Ho suonato ma non apre.","wd":"Forte odore dall''appartamento di un vicino anziano che non apre","p":"Lui dovrebbe essere in casa, esce sempre solo la mattina.","pd":"Anziano probabilmente in casa, non risponde","ag":["115","118"]},{"w":"In cucina, vicino al fornello. Ho già chiuso la manopola del gas centrale.","wd":"Odore in cucina, rubinetto generale già chiuso","p":"Siamo io e mia figlia, stiamo bene.","pd":"Due persone, nessun sintomo","ag":["115"]},{"w":"C''è un cantiere qui davanti, la ruspa ha rotto un tubo, sento il gas che fischia!","wd":"Tubo del gas tranciato da una ruspa, fuga udibile","p":"Gli operai si sono allontanati, ma ci sono le case e il traffico.","pd":"Nessun ferito, abitazioni e traffico vicini","ag":["115","{location.police}"]}]}},"caller":{"gender":"any","phone_type":"any","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, c''è un forte odore di gas, non so cosa fare.","panic":"Pronto, c''è puzza di gas dappertutto!"},"deterioration":[{"after_s":300,"panic":15,"line":{"calm":"L''odore è ancora più forte, adesso si sente fino alle scale.","panic":"Puzza sempre di più! Si sente fino in strada!"}},{"after_s":600,"sets_flag":"malesseri","panic":15,"line":{"calm":"Una signora del secondo piano dice che le gira la testa.","panic":"Una signora sta male, le gira la testa! Cosa facciamo?!"}}],"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"fonte":{"label":"Da dove viene","display":"{sc.wd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"In che via e a che numero sente l''odore?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","Sono in {location.street}, numero {location.number}."],"panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_dove_odore","label":"Dove sente l''odore esattamente?","cost_s":6,"reveals":["fonte"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Sbrigatevi!"}},{"id":"q_persone","label":"Ci sono persone coinvolte? Qualcuno si sente male?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p} Fate presto!"},"reply_flag":{"flag":"malesseri","calm":"{sc.p} E adesso una signora del secondo piano ha mal di testa e le gira tutto.","panic":"Una signora sta male, le gira la testa!"}},{"id":"a_istruzioni","type":"reassure","label":"Non accenda luci né interruttori, non usi il campanello, apra le finestre se può ed esca all''aperto.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene, non tocco niente ed esco.","panic":"Ok, esco subito!"}}],"truth":{"event_type":"incendio_tecnico.fuga_gas","agencies_required":"{sc.ag}","agencies_acceptable":["PS","CC"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","fonte"],"hint_debrief":"Nelle fughe di gas l''istruzione più importante è non azionare nulla di elettrico. Se qualcuno non risponde dentro casa serve anche il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_030', 'Incendio di sterpaglie o bosco', 'incendio_tecnico', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"INC_030","title":"Incendio di sterpaglie o bosco","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.4,"max":2,"delay_s":[40,200],"near_twin_chance":0.15},"witness_opening":{"calm":"Buonasera, si vede del fumo in collina, verso {location.landmark}.","panic":"Pronto, c''è un incendio in {location.street}, si vedono le fiamme!"},"variables":{"location":{"pool":"stradario","zones":["colline","montagna"],"floor":[0,0]},"sc":{"choice":[{"f":"Sterpaglie lungo la strada, un tratto di una ventina di metri.","fd":"Sterpaglie a bordo strada, circa 20 metri","v":"Poco vento, il fumo va verso il campo.","vd":"Poco vento, nessuna casa minacciata","p":"Nessuno, sono passato in macchina.","pd":"Nessuno coinvolto","ag":["115"]},{"f":"Il bosco sopra l''agriturismo! Si vedono le fiamme tra gli alberi.","fd":"Incendio nel bosco, fiamme visibili","v":"C''è vento forte e va verso le case!","vd":"Vento forte verso le abitazioni","p":"Nell''agriturismo ci sono i clienti, stanno uscendo.","pd":"Ospiti dell''agriturismo in evacuazione","ag":["115"]},{"f":"Stavo bruciando le potature nel mio campo e il fuoco mi è scappato verso la siepe.","fd":"Fuoco sfuggito da un abbruciamento di potature","v":"Un po'' di vento.","vd":"Vento moderato","p":"Ho provato a spegnerlo e mi sono bruciato le mani…","pd":"Il chiamante ha ustioni alle mani","ag":["115","118"]}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, c''è un incendio qui in collina, c''è tanto fumo.","panic":"Pronto! Sta bruciando tutto, c''è un incendio!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"incendio":{"display":"{sc.fd}"},"pericoli":{"display":"{sc.vd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova l''incendio? Strada, località, punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, c''è {location.landmark} lì vicino.","panic":"{location.street}! Verso {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_cosa","label":"Cosa sta bruciando e quanto è esteso?","cost_s":6,"reveals":["incendio"],"reply":{"calm":"{sc.f}","panic":"{sc.f} Sbrigatevi!"}},{"id":"q_vento","label":"C''è vento? Verso dove va il fuoco?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{sc.v}","panic":"{sc.v} Fate presto!"}},{"id":"q_persone","label":"Ci sono persone o case in pericolo? Qualcuno si è ferito?","cost_s":6,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p} Sbrigatevi!"}},{"id":"a_rassicura","type":"reassure","label":"Si allontani controvento e non provi a spegnerlo: aspetti i Vigili del fuoco in un punto sicuro.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"incendio_tecnico.incendio_vegetazione","agencies_required":"{sc.ag}","agencies_acceptable":["CC"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","pericoli"],"hint_debrief":"Per un incendio di vegetazione contano vento e direzione: dicono se le case sono a rischio. Chi si è ustionato cercando di spegnerlo ha bisogno del 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_031', 'Acqua in casa', 'incendio_tecnico', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_031","title":"Acqua in casa","category":"incendio_tecnico","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,3]},"sc":{"choice":[{"w":"La cantina è allagata, ci saranno venti centimetri d''acqua. È entrata col temporale.","wd":"Cantina allagata, circa 20 cm","e":"No, lì sotto non ci sono prese.","ed":"Nessun pericolo elettrico","p":"No, sto bene, sono di sopra.","pd":"Nessuno in pericolo","ag":["115"],"sev":{"optimal_s":1800,"acceptable_s":3600,"limit_s":7200}},{"w":"Si è rotto un tubo in casa, l''acqua è arrivata alle prese della cucina e ha fatto una scintilla!","wd":"Tubo rotto, acqua sulle prese elettriche","e":"Sì, una presa ha fatto una scintilla e ora puzza di bruciato.","ed":"Acqua sull''impianto elettrico, scintille","p":"Io e mia madre, che è in carrozzina.","pd":"Anziana in carrozzina in casa","ag":["115"],"sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400}},{"w":"Sono nel sottopasso con la macchina, l''acqua sale, sono salit{g.o} sul tettuccio!","wd":"Auto bloccata nel sottopasso allagato, acqua in salita","e":"Non lo so!","ed":"Sconosciuto","p":"Io da sol{g.o}… l''acqua è già ai finestrini!","pd":"Automobilista sul tetto dell''auto, acqua ai finestrini","ag":["115","118","{location.police}"],"sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900}}],"weights":[45,35,20]}},"caller":{"gender":"any","phone_type":"any","panic_start":35,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buongiorno, ho un problema con l''acqua, si è allagato tutto.","panic":"Pronto, c''è acqua dappertutto, aiuto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"acqua":{"label":"Allagamento","display":"{sc.wd}"},"pericoli":{"display":"{sc.ed}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova? Via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} {location.number}, {location.zone_name}","reply":{"panic":"In {location.street_wrong}… sì, {location.street_wrong}, il {location.number}!","hyst":"{location.street_wrong}! No… sì! Il {location.number}!"}}},{"id":"q_cosa","label":"Dove c''è l''acqua e quanta ce n''è?","cost_s":6,"reveals":["acqua"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_luce","label":"L''acqua arriva a prese, quadri elettrici o elettrodomestici?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{sc.e}","panic":"{sc.e}"}},{"id":"q_persone","label":"Ci sono persone in difficoltà?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p}"}},{"id":"a_rassicura","type":"reassure","label":"Stacchi la corrente dal contatore solo se ci arriva senza toccare l''acqua, e salga a un piano più alto.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"incendio_tecnico.allagamento","agencies_required":"{sc.ag}","severity":"{sc.sev}","critical_facts":["indirizzo","persone"],"hint_debrief":"Una cantina allagata può aspettare; acqua sull''impianto elettrico o una persona bloccata no. Le stesse parole, «è tutto allagato», nascondono urgenze molto diverse."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_032', 'Albero caduto', 'incendio_tecnico', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_032","title":"Albero caduto","category":"incendio_tecnico","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","colline","centro"],"floor":[0,0]},"sc":{"choice":[{"w":"È caduto un albero enorme in mezzo alla strada, non passa nessuno.","wd":"Albero di traverso sulla carreggiata, strada bloccata","p":"No, per fortuna nessuno.","pd":"Nessuno coinvolto","ag":["115","{location.police}"],"event":"incendio_tecnico.danni_maltempo"},{"w":"L''albero è caduto sopra una macchina! C''è una signora dentro!","wd":"Albero caduto su un''auto con una donna a bordo","p":"Si muove, ma non riesce a uscire, il tetto è schiacciato.","pd":"Donna bloccata nell''auto, cosciente","ag":["115","118","{location.police}"],"event":"incendio_tecnico.danni_maltempo"},{"w":"C''è un ramo grosso spezzato che pende sopra il parco giochi, col vento si muove.","wd":"Grosso ramo pericolante sopra un''area giochi","p":"Ho fatto allontanare i bambini.","pd":"Area sgomberata dal chiamante","ag":["115"],"event":"incendio_tecnico.danni_maltempo"}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":40,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, col temporale è caduto un albero.","panic":"Pronto! È caduto un albero, presto!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"danni":{"label":"Situazione","display":"{sc.wd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova? Via e un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, c''è {location.landmark} lì vicino.","panic":"{location.street}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicur{g.o}!"}}},{"id":"q_cosa","label":"Cosa è successo esattamente? Blocca la strada?","cost_s":6,"reveals":["danni"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Venite, presto!"}},{"id":"q_persone","label":"Ci sono persone coinvolte o ferite?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p} Venite, presto!"}},{"id":"a_rassicura","type":"reassure","label":"Si tenga a distanza, possono cadere altri rami, e segnali il pericolo a chi arriva.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["sicurezza.pericolo_viabilita"],"agencies_required":"{sc.ag}","agencies_acceptable":["PS","CC","118"],"severity":{"optimal_s":420,"acceptable_s":900,"limit_s":1800},"critical_facts":["indirizzo","persone"],"hint_debrief":"Un albero sulla strada chiede Vigili del fuoco e forze dell''ordine per la viabilità; una persona bloccata sotto aggiunge il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_033', 'Bloccati in ascensore', 'incendio_tecnico', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_033","title":"Bloccati in ascensore","category":"incendio_tecnico","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[1,5]},"sc":{"choice":[{"p":"Sono da sol{g.o}, ho settantadue anni… sto bene, ma sono qui da venti minuti e mi sta venendo l''ansia.","pd":"Persona anziana sola, sta bene, agitata","ag":["115"],"pp":"Sono da sol{g.o}… ho settantadue anni, e qui dentro manca l''aria, mi sento soffocare!"},{"p":"Siamo in due: c''è un signore diabetico che sta sudando freddo, dice che gli gira la testa.","pd":"Due persone; un uomo diabetico con sudore freddo e capogiri","ag":["115","118"],"pp":"Siamo in due! Il signore è diabetico, suda freddo, gli gira la testa… sta per svenire!"},{"p":"C''è anche un bambino con me, il figlio della vicina, ha otto anni… piange, ha paura.","pd":"Un adulto e un bambino di 8 anni, spaventato","ag":["115"],"pp":"C''è un bambino di otto anni con me, piange e non si calma, la mamma è di sopra!"}],"weights":[45,30,25]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":50,"ring_patience_s":35,"hold_patience_s":25,"reliability":0.95,"callback_chance":0.9},"opening":{"calm":["Pronto… sono bloccat{g.o} in ascensore, non si muove più.","Pronto, buongiorno… l''ascensore si è fermato tra due piani e io sono dentro."],"panic":"Pronto! Sono chius{g.o} in ascensore, non si apre!","hyst":"Aiuto! Sono chius{g.o} dentro, l''ascensore non si apre! Fatemi uscire!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, ascensore fermo tra i piani"},"persone":{"display":"{sc.pd}"},"allarme":{"label":"Allarme","display":"Pulsante d''allarme premuto, nessuna risposta"}},"nodes":[{"id":"q_dove","label":"In che palazzo si trova? Via e numero.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":["{location.street} {location.number}!","{location.street}, il {location.number}! Il palazzo col portone verde!"]}},{"id":"q_chi","label":"Chi c''è in ascensore con lei? State tutti bene?","cost_s":6,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.pp}"}},{"id":"q_allarme","label":"Ha premuto il pulsante d''allarme? Qualcuno ha risposto?","cost_s":5,"reveals":["allarme"],"reply":{"calm":"Sì, l''ho premuto tante volte, suona ma non risponde nessuno.","panic":"Sì! L''ho premuto mille volte, suona e basta, non risponde nessuno!"}},{"id":"a_rassicura","type":"reassure","label":"Resti tranquill{g.o} e non provi a forzare le porte: l''aria c''è, arriviamo ad aprire.","cost_s":6,"panic_delta":-25,"reply":{"calm":"Va bene… aspetto.","panic":"Ok… ok, aspetto."}}],"truth":{"event_type":"incendio_tecnico.soccorso_persona","agencies_required":"{sc.ag}","severity":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600},"critical_facts":["indirizzo","persone"],"hint_debrief":"Una persona in ascensore è quasi sempre un soccorso tranquillo: la domanda che cambia tutto è se qualcuno sta male."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_034', 'Un animale in difficoltà', 'incendio_tecnico', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_034","title":"Un animale in difficoltà","category":"incendio_tecnico","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","colline","industriale"],"floor":[0,0]},"sc":{"choice":[{"w":"Il gatto è salito sull''albero del giardino e non scende da ieri, miagola in continuazione.","wd":"Gatto su un albero da ieri","d":"No, nessun pericolo per le persone.","dd":"Nessun pericolo","event":"impropria.informazioni","ag":[],"sev":{"optimal_s":1800,"acceptable_s":3600,"limit_s":7200},"hint":"Un gatto sull''albero non è un''emergenza del 112: va indirizzato ai servizi comunali o alle associazioni, dopo aver escluso pericoli per le persone.","x":"No no, nessuno ci ha provato. Io la scala non ce l''ho, comunque.","xd":"Nessuno ha provato a salire","adv":"Non salga sull''albero e non usi scale improvvisate. Per il gatto può contattare il Comune o un''associazione per gli animali.","adv_r":"Ah, va bene… allora chiamo il Comune. Grazie."},{"w":"Il mio cane è caduto in un pozzo nel campo, lo sento guaire, è profondo!","wd":"Cane caduto in un pozzo profondo","d":"Il pozzo è aperto, ho paura che ci cada qualcun altro.","dd":"Pozzo aperto, pericolo di cadute","event":"incendio_tecnico.soccorso_animale","ag":["115"],"sev":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600},"hint":"Il cane nel pozzo è un soccorso tecnico per i Vigili del fuoco, e il pozzo aperto è un pericolo anche per le persone: bisogna dire a chi chiama di non calarsi.","x":"Mio fratello voleva calarsi con una corda… l''ho fermato io.","xd":"Un familiare voleva calarsi nel pozzo","adv":"Non si cali nel pozzo e non si sporga: tenga tutti lontani dal bordo, arrivano i Vigili del fuoco.","adv_r":"Va bene, nessuno si avvicina. Lo sento ancora guaire…"},{"w":"C''è un cinghiale enorme in mezzo alla provinciale, le macchine inchiodano!","wd":"Cinghiale sulla carreggiata, auto che frenano","d":"È buio, qualcuno lo prenderà in pieno!","dd":"Rischio di incidenti, strada buia","event":"sicurezza.pericolo_viabilita","ag":["{location.police}"],"sev":{"optimal_s":240,"acceptable_s":600,"limit_s":1200},"hint":"Un cinghiale sulla carreggiata, di notte, è un pericolo per la circolazione: è urgente e va alle forze dell''ordine competenti per zona.","x":"Un signore è sceso dalla macchina per cacciarlo via con le mani… è matto!","xd":"Un automobilista è sceso per scacciarlo","adv":"Resti in macchina o lontano dalla carreggiata, accenda le quattro frecce e non provi a scacciarlo.","adv_r":"Sì, ho le quattro frecce accese, resto in macchina."}],"weights":[35,35,30]}},"caller":{"gender":"any","phone_type":"any","panic_start":30,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.5},"opening":{"calm":"Buonasera, chiamo per un animale, non so a chi rivolgermi.","panic":"Pronto, c''è un animale, aiutatemi!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"situazione":{"label":"Situazione","display":"{sc.wd}"},"pericoli":{"display":"{sc.dd}"},"rischi":{"label":"Persone esposte","display":"{sc.xd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova? Via o strada, e un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, c''è {location.landmark} lì vicino.","panic":"{location.street}! C''è {location.landmark} lì vicino!"}},{"id":"q_cosa","label":"Cosa sta succedendo all''animale?","cost_s":6,"reveals":["situazione"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_pericolo","label":"Ci sono pericoli per le persone o per la circolazione?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{sc.d}","panic":"{sc.d}"}},{"id":"q_avvicina","label":"Qualcuno ha provato ad avvicinarsi o a intervenire da solo?","cost_s":5,"reveals":["rischi"],"reply":{"calm":"{sc.x}","panic":"{sc.x}"}},{"id":"a_consiglio","type":"reassure","label":"{sc.adv}","cost_s":6,"panic_delta":-10,"reply":{"calm":"{sc.adv_r}","panic":"Va bene… va bene."}}],"truth":{"event_type":"{sc.event}","agencies_required":"{sc.ag}","agencies_acceptable":["115"],"severity":"{sc.sev}","critical_facts":["situazione","pericoli"],"hint_debrief":"{sc.hint}"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_035', 'Emergenza in un capannone', 'incendio_tecnico', 1, 6, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"INC_035","title":"Emergenza in un capannone","category":"incendio_tecnico","phase":1,"difficulty":6,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.5,"max":2,"delay_s":[30,160],"near_twin_chance":0},"witness_opening":{"calm":"Buonasera, dalla zona artigianale si vede una colonna di fumo, verso {location.street}.","panic":"Pronto, c''è un fumo nero enorme in {location.street}!"},"variables":{"location":{"pool":"stradario","zones":["industriale"],"floor":[0,0]},"sc":{"choice":[{"w":"Esce un fumo nerissimo dal capannone della verniciatura!","wd":"Fumo nero dal reparto verniciatura","p":"Siamo usciti tutti, ma un collega tossisce tantissimo e non riesce a riprendersi.","pd":"Operaio con tosse persistente dopo il fumo","ag":["115","118"],"event":"incendio_tecnico.incendio_abitazione"},{"w":"Un camion nel piazzale ha perso un liquido, c''è una pozza enorme e un odore che brucia gli occhi.","wd":"Sversamento di liquido chimico da un camion, odore irritante","p":"Nessuno sta male, ci siamo allontanati.","pd":"Nessun ferito","ag":["115"],"event":"incendio_tecnico.sversamento"},{"w":"C''è stato uno scoppio in officina, adesso c''è fuoco vicino al compressore!","wd":"Esplosione in officina, fiamme vicino al compressore","p":"Un operaio è ustionato sulle braccia e sul viso!","pd":"Operaio ustionato a braccia e viso","ag":["115","118","CC"],"event":"incendio_tecnico.incendio_abitazione"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":70,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, chiamo dalla ditta, abbiamo un''emergenza nel capannone.","panic":"Pronto! Emergenza in ditta, presto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, zona artigianale"},"evento":{"display":"{sc.wd}"},"persone":{"display":"{sc.pd}"},"sostanze":{"label":"Sostanze presenti","display":"Vernici e solventi in magazzino"}},"nodes":[{"id":"q_dove","label":"Qual è l''indirizzo dell''azienda?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}, entrate dal cancello principale.","panic":"{location.street} {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_cosa","label":"Cosa sta succedendo esattamente?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Fate presto!"}},{"id":"q_persone","label":"Ci sono feriti o persone ancora dentro?","cost_s":6,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p} Venite, presto!"}},{"id":"q_sostanze","label":"Sa che sostanze ci sono in quel capannone?","cost_s":5,"reveals":["sostanze"],"reply":{"calm":"Vernici, solventi… ci sono i fusti in magazzino.","panic":"Vernici, solventi… ci sono i fusti in magazzino. Fate presto!"}},{"id":"a_rassicura","type":"reassure","label":"Fate uscire tutti, contateli al punto di raccolta e non avvicinatevi al fumo o al liquido.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["incendio_tecnico.sversamento","incendio_tecnico.incendio_abitazione","sanitaria.intossicazione"],"agencies_required":"{sc.ag}","agencies_acceptable":["CC","118"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","persone","sostanze"],"hint_debrief":"Negli incidenti industriali le sostanze presenti cambiano l''intervento dei Vigili del fuoco: vanno sempre chieste."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_036', 'Cavo elettrico a terra', 'incendio_tecnico', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_036","title":"Cavo elettrico a terra","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","industriale","colline"],"floor":[0,0]},"sc":{"choice":[{"w":"Un cavo della linea è caduto sul marciapiede e fa le scintille, vicino alla fermata del bus!","wd":"Cavo elettrico a terra con scintille vicino alla fermata","p":"Ho fermato le persone, nessuno l''ha toccato.","pd":"Nessuno coinvolto","ag":["115"]},{"w":"Un cavo è caduto col vento e un signore l''ha toccato… è a terra!","wd":"Cavo a terra, un uomo lo ha toccato","p":"È a terra e non si muove, non so se respira!","pd":"Uomo folgorato, a terra, non si muove","ag":["115","118"]},{"w":"Un camion ha preso un palo della luce, è piegato sopra la strada e i fili pendono!","wd":"Palo della luce piegato sulla strada dopo un urto","p":"L''autista è sceso, sta bene.","pd":"Autista illeso","ag":["115","{location.police}"]}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":50,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, c''è un cavo elettrico per terra, è pericoloso.","panic":"Pronto! C''è un cavo della corrente per terra!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"pericolo":{"label":"Situazione","display":"{sc.wd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova? Via e punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, c''è {location.landmark} lì vicino.","panic":"{location.street}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicur{g.o}!"}}},{"id":"q_cosa","label":"Cosa vede esattamente?","cost_s":6,"reveals":["pericolo"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Venite, presto!"}},{"id":"q_persone","label":"Qualcuno è stato colpito o è vicino al cavo?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p} Sbrigatevi!"}},{"id":"a_distanza","type":"reassure","label":"Non si avvicini e non tocchi la persona finché la corrente non è staccata: tenga tutti ad almeno dieci metri.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Va bene, stiamo lontani.","panic":"Ok! Nessuno si avvicina!"}}],"truth":{"event_type":"incendio_tecnico.danni_maltempo","acceptable_event_types":["sicurezza.pericolo_viabilita","incendio_tecnico.soccorso_persona"],"agencies_required":"{sc.ag}","agencies_acceptable":["PS","CC"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","persone"],"hint_debrief":"Con un cavo a terra la prima istruzione è la distanza: chi tocca una persona folgorata rischia di diventare la seconda vittima."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_052', 'Canna fumaria in fiamme', 'incendio_tecnico', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_052","title":"Canna fumaria in fiamme","category":"incendio_tecnico","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["colline","residenziale","centro"],"floor":[0,2]},"sc":{"choice":[{"w":"Dal comignolo escono scintille e fiamme, il camino fa un rumore come un treno!","wd":"Fiamme e scintille dal comignolo","p":"Siamo usciti tutti in giardino.","pd":"Tutti fuori casa","ag":["115"]},{"w":"Il muro della camera vicino al camino è caldissimo e c''è fumo che esce dalle crepe.","wd":"Muro surriscaldato vicino alla canna fumaria, fumo dalle crepe","p":"Mia suocera è a letto, non cammina.","pd":"Anziana allettata in casa","ag":["115","118"]}],"weights":[60,40]}},"caller":{"gender":"any","phone_type":"any","panic_start":50,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, credo che stia bruciando la canna fumaria del camino.","panic":"Pronto! Il camino sta prendendo fuoco!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"incendio":{"display":"{sc.wd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"L''indirizzo della casa con il camino: via e numero?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} {location.number}, {location.zone_name}","reply":{"panic":"In {location.street_wrong}… sì, {location.street_wrong}, il {location.number}!","hyst":"{location.street_wrong}! No… sì! Il {location.number}!"}}},{"id":"q_cosa","label":"Cosa vede esattamente?","cost_s":6,"reveals":["incendio"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Sbrigatevi!"}},{"id":"q_persone","label":"Siete tutti fuori? C''è qualcuno che non può muoversi?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p} Fate presto!"}},{"id":"a_rassicura","type":"reassure","label":"Non buttate acqua nel camino: chiudete la presa d''aria se ci arrivate e uscite di casa.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"incendio_tecnico.incendio_abitazione","agencies_required":"{sc.ag}","severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","persone"],"hint_debrief":"Un incendio di canna fumaria può propagarsi al tetto. Chi non può uscire da solo richiede anche il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_066', 'Monopattino in carica che fuma', 'incendio_tecnico', 1, 4, 75, 2, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_066","title":"Monopattino in carica che fuma","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":75,"min_rank":2,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,5]},"sc":{"choice":[{"obj":"il monopattino","obj_c":"Il monopattino","dal":"dal monopattino","dove":"in corridoio","cosa":"Il monopattino elettrico, era in carica in corridoio… la batteria sotto la pedana fa un fumo bianco e sfrigola.","cosa_d":"Batteria del monopattino in carica in corridoio: fumo bianco, sfrigolio"},{"obj":"la batteria della bici","obj_c":"La batteria della bici","dal":"dalla batteria della bici","dove":"in garage","cosa":"La batteria della bici elettrica, l''avevo messa in carica in garage… è gonfia e fa un fumo che puzza di plastica.","cosa_d":"Batteria di bici elettrica in carica in garage: gonfia, fumo acre"},{"obj":"l''hoverboard","obj_c":"L''hoverboard","dal":"dall''hoverboard","dove":"in cameretta","cosa":"L''hoverboard di mio figlio, in carica in cameretta… fa dei piccoli scoppi e un fumo grigio.","cosa_d":"Hoverboard in carica in cameretta: piccoli scoppi, fumo grigio"}]},"people":{"choice":[{"t":"Io e mia moglie… no, aspetti, ci sono anche i bambini di là, li chiamo!","d":"Una coppia e dei bambini in casa"},{"t":"Ci sono solo io. E il gatto, da qualche parte.","d":"Solo il chiamante (e un gatto)"},{"t":"Io e mia madre, che cammina male… è in camera sua, in fondo al corridoio.","d":"Il chiamante e la madre anziana con difficoltà a camminare"}],"weights":[40,35,25]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":55,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.7,"voice":{"age":"adult","style":"breathless"}},"opening":{"calm":["Pronto, {sc.obj} in carica sta fumando {sc.dove}! Ci butto un secchio d''acqua?","Buonasera… sta uscendo del fumo {sc.dal}, era in carica {sc.dove}. Che faccio, ci butto l''acqua?"],"panic":"Pronto! {sc.obj_c} in carica fuma, fa le scintille! Ci butto l''acqua?!","hyst":"Pronto! Fuoco! {sc.obj_c} prende fuoco! Cosa faccio?!"},"callback_opening":{"calm":"Pronto, sono di nuovo io, per {sc.obj} che fumava… è caduta la linea. Siamo usciti.","panic":"Sono io! Adesso brucia! Escono le fiamme da sotto la porta!"},"timeline":[{"id":"secchio","at_s":[25,40],"unless_asked":["a_esci"],"say":{"calm":"Ho riempito un secchio… adesso ci butto l''acqua sopra, così si spegne.","panic":"Ho il secchio! Ci butto l''acqua, la butto adesso!"},"panic_delta":10,"sets_flag":"secchio","interrupt":true}],"deterioration":[{"after_s":60,"sets_flag":"fiamme","panic":20,"line":{"calm":"Ha fatto un botto! Escono delle fiammate, sembrano fuochi d''artificio!","panic":"Un botto! Fiamme! Sputa fiamme come un fuoco d''artificio!"}}],"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text}"},"oggetto":{"label":"Cosa brucia","display":"{sc.cosa_d}"},"persone":{"display":"{people.d}"},"stato":{"label":"Fumo e fiamme","display":"Fumo denso che fa tossire"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via, numero e piano.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}, al {location.floor_text}.","In {location.street}, numero {location.number}. {location.floor_text}."],"panic":"{location.street} {location.number}! {location.floor_text}!"},"error":{"threshold":70,"chance":0.35,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}! Fate presto!"}}},{"id":"q_cosa","label":"Cosa sta fumando esattamente? Dove si trova?","cost_s":6,"reveals":["oggetto"],"reply":{"calm":"{sc.cosa}","panic":"{sc.cosa} Fa sempre più fumo!"}},{"id":"q_persone","label":"Chi c''è in casa con lei?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{people.t}","panic":"{people.t} Usciamo?!"}},{"id":"q_fumo","label":"Vede fiamme o solo fumo? Il fumo è tanto?","cost_s":5,"reveals":["stato"],"reply":{"calm":"Solo fumo per adesso, ma è denso, fa tossire. Fiamme no.","panic":"Tanto fumo! Fiamme ancora no, ma fa tossire!"},"reply_flag":{"flag":"fiamme","calm":"Adesso ci sono le fiamme! Fiammate, e un fumo nero che riempie la stanza!","panic":"Fiamme! Fiammate! È tutto nero!"}},{"id":"a_esci","type":"reassure","label":"Non ci butti acqua e non lo tocchi. Esca dalla stanza, chiuda la porta dietro di sé e uscite tutti di casa. Non rientrate per nessun motivo.","cost_s":8,"panic_delta":-15,"reply":{"calm":"Va bene… niente acqua. Chiudo la porta… usciamo tutti.","panic":"Ok! Chiudo e usciamo! Usciamo!"},"reply_flag":{"flag":"secchio","calm":"Ah… va bene, metto giù il secchio! Chiudo la porta e usciamo.","panic":"Mollo il secchio! Chiudo la porta! Usciamo!"}}],"truth":{"event_type":"incendio_tecnico.incendio_abitazione","agencies_required":["115"],"agencies_acceptable":["118"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","oggetto","persone"],"hint_debrief":"Una batteria al litio che fuma può prendere fuoco all''improvviso con fiammate violente, e l''acqua da un secchio non la spegne. L''istruzione giusta è non toccarla, uscire dalla stanza chiudendo la porta e far uscire tutti di casa."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_001', 'Anziana caduta in casa', 'sanitaria', 1, 1, 120, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_001","title":"Anziana caduta in casa","category":"sanitaria","phase":1,"difficulty":1,"weight":120,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,4]},"injury":{"choice":[{"text":"Mi fa tanto male l''anca destra… la testa no, quella non l''ho battuta.","display":"Forte dolore all''anca destra, non ha battuto la testa"},{"text":"Ho battuto la testa sullo spigolo del tavolo… mi gira un po'' tutto.","display":"Ha battuto la testa, ha dei capogiri"},{"text":"Il polso… credo di essermelo rotto. La testa no.","display":"Dolore al polso, non ha battuto la testa"}]},"access":{"choice":[{"text":"No, sono sola. La porta è chiusa a chiave e le chiavi sono sul mobile dell''ingresso… non ci arrivo.","display":"Sola in casa, porta chiusa a chiave: non può aprire","agencies":["118","115"]},{"text":"Sono sola, ma la signora del piano di sopra ha le chiavi, può aprire lei.","display":"Sola; la vicina del piano di sopra ha le chiavi","agencies":["118"]},{"text":"C''è mio nipote, l''ho mandato giù ad aprire il portone.","display":"C''è il nipote, che aprirà ai soccorsi","agencies":["118"]}],"weights":[40,35,25]}},"caller":{"gender":"f","phone_type":"any","panic_start":30,"ring_patience_s":45,"hold_patience_s":70,"reliability":0.9,"callback_chance":0.7,"voice":{"age":"elderly"}},"opening":{"calm":["Pronto? Scusi… sono caduta in cucina e non riesco più ad alzarmi.","Pronto… buongiorno, mi scusi… sono per terra in cucina e da sola non mi tiro su."],"panic":"Pronto?! Aiuto… sono caduta, non riesco ad alzarmi, mi fa male!","hyst":"Aiuto! Aiutatemi! Sono per terra, mi fa male, non riesco… aiuto!"},"callback_opening":{"calm":"Pronto? Sono di nuovo io, la signora caduta in cucina… è caduta la linea, scusi.","panic":"Pronto?! Sono io, quella caduta in cucina! Non è venuto ancora nessuno!"},"deterioration":[{"after_s":600,"panic":10,"line":{"calm":"Scusi… comincio ad avere freddo, qui sulle piastrelle.","panic":"Ho freddo… sono qui per terra da tanto, quando arrivate?"}},{"after_s":1200,"sets_flag":"debole","panic":15,"line":{"calm":"Mi gira un po'' la testa… e la gamba non la sento più tanto bene.","panic":"Mi gira tutto… la gamba non la sento più! Ho paura!"}}],"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"evento":{"display":"Scivolata in cucina, non riesce ad alzarsi"},"ferite":{"display":"{injury.display}"},"accesso":{"label":"Accesso all''abitazione","display":"{access.display}"}},"nodes":[{"id":"q_dove","label":"Mi dice dove abita? Via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["Abito in {location.street} {location.number}.","In {location.street}, al {location.number}. Da quarant''anni, sa."],"panic":"In {location.street}… il {location.number}, sì, il {location.number}.","hyst":"In… in {location.street}! Il {location.number}! Venite!"},"error":{"threshold":101,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"calm":"In {location.street} {location.number_wrong}… sì, mi pare."}}},{"id":"q_piano","label":"A che piano abita? Che nome c''è sul campanello?","cost_s":5,"requires":["q_dove"],"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}. Sul campanello c''è scritto {caller_surname}.","panic":"{location.floor_text}… {caller_surname}, c''è scritto {caller_surname}!"}},{"id":"q_cosa","label":"Mi racconti cosa è successo.","cost_s":7,"reveals":["evento"],"reply":{"calm":"Stavo prendendo un piatto, sono scivolata e sono finita per terra. Adesso non riesco a tirarmi su.","panic":"Sono scivolata! Sono per terra e non riesco ad alzarmi!"}},{"id":"q_dolore","label":"Ha male da qualche parte? Ha sbattuto la testa?","cost_s":7,"requires":["q_cosa"],"reveals":["ferite"],"reply":{"calm":"{injury.text}","panic":"{injury.text} Mi fa tanto male!"},"reply_flag":{"flag":"debole","calm":"{injury.text} E adesso mi gira la testa, la gamba la sento poco.","panic":"{injury.text} E adesso mi gira tutto!"}},{"id":"q_accesso","label":"C''è qualcuno con lei? Chi può aprire la porta ai soccorsi?","cost_s":7,"reveals":["accesso"],"reply":{"calm":"{access.text}","panic":"{access.text}"}},{"id":"a_rassicura","type":"reassure","label":"Signora, non si muova e stia tranquilla: le mando subito aiuto.","cost_s":6,"panic_delta":-20,"reply":{"calm":"Va bene… grazie, grazie tante.","panic":"Sì… sì, va bene. Faccia presto però."}}],"truth":{"event_type":"sanitaria.trauma_caduta","agencies_required":["{access.agencies}"],"severity":{"optimal_s":300,"acceptable_s":900,"limit_s":2400},"critical_facts":["indirizzo","accesso"],"hint_debrief":"Una persona sola che non può aprire la porta richiede anche i Vigili del fuoco per l''accesso: senza, l''ambulanza resta fuori."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_007', 'Non si sveglia (arresto cardiaco mascherato)', 'sanitaria', 1, 3, 90, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_007","title":"Non si sveglia (arresto cardiaco mascherato)","category":"sanitaria","phase":1,"difficulty":3,"weight":90,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,5]},"patient":{"choice":[{"rel":"marito","my":"Mio marito","him":"lo"},{"rel":"compagno","my":"Il mio compagno","him":"lo"},{"rel":"papà","my":"Mio papà","him":"lo"}]},"patient_age":{"range":[58,79]}},"caller":{"gender":"f","phone_type":"any","panic_start":65,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.9,"voice":{"age":"adult","style":"breathless"}},"opening":{"calm":"Pronto? {patient.my} non si sveglia… sembra che dorma ma non mi risponde.","panic":"Pronto?! {patient.my} non si sveglia, non mi risponde! Faccia presto!"},"callback_opening":{"calm":"Pronto? Ho chiamato prima, è caduta la linea… {patient.my} non si sveglia ancora.","panic":"Sono io, di nuovo! {patient.my} non si sveglia, non fa più neanche quel rumore! Dove siete?!"},"timeline":[{"id":"smette","at_s":[60,90],"unless_flag":"rcp","say":{"calm":"Aspetti… ha smesso anche di fare quel rumore. Non respira più!","panic":"Non respira più! Ha smesso, non fa più niente! Cosa faccio?!"},"panic_delta":20,"reveals":["respiro_dopo"],"sets_flag":"arresto","interrupt":true}],"deterioration":[{"after_s":150,"sets_flag":"arresto","panic":15,"line":{"calm":"È diventato grigio… le labbra sono viola.","panic":"È tutto grigio! Le labbra sono viola! Fate presto!"}},{"after_s":300,"panic":15,"line":{"calm":"Non si muove più per niente… è freddo, le mani sono fredde.","panic":"Ha le mani fredde! Non si muove più! Oddio!"}}],"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, citofono {caller_surname}"},"coscienza":{"display":"Non risponde e non reagisce quando lo scuote"},"respiro":{"display":"Fa dei rantoli ogni tanto, «come se russasse»"},"eta":{"display":"{patient_age} anni"},"pericoli":{"display":"Nessun odore di gas o fumo"},"respiro_dopo":{"label":"Poco dopo","display":"Ha smesso anche di rantolare: «non respira più»"},"rcp":{"label":"Rianimazione","display":"La chiamante esegue le compressioni toraciche, guidata dall''operatore"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo esatto.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","Allora… {location.street}, numero {location.number}."],"panic":"{location.street}… il {location.number}! Venite!"},"error":{"threshold":60,"chance":0.5,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}! Faccia presto!"}}},{"id":"q_piano","label":"Che piano? Che nome c''è sul citofono?","cost_s":5,"requires":["q_dove"],"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, citofono {caller_surname}.","panic":"{location.floor_text}! {caller_surname}!"}},{"id":"q_coscienza","label":"Lo chiami forte e lo scuota per le spalle. Risponde?","cost_s":10,"panic_delta":5,"reveals":["coscienza"],"reply":{"calm":"No… non risponde, niente.","panic":"No! Non fa niente! Oddio!"}},{"id":"q_respiro","label":"Guardi il petto: respira normalmente?","cost_s":10,"requires":["q_coscienza"],"reveals":["respiro"],"reply":{"calm":"Fa… tipo dei rantoli, ogni tanto. Come se russasse.","panic":"Fa un rumore strano… tipo russare…"},"reply_flag":{"flag":"arresto","calm":"No… il petto è fermo. Non fa più niente.","panic":"No! Il petto non si muove! Non respira!"},"error":{"unless_flag":"arresto","threshold":70,"chance":0.6,"fact":"respiro","display":"Dice che respira normalmente","reply":{"panic":"Sì, sì, respira! Cioè… credo di sì!"}}},{"id":"q_eta","label":"Quanti anni ha?","cost_s":4,"reveals":["eta"],"reply":{"calm":"{patient_age}.","panic":"{patient_age}, credo… sì, {patient_age}!"}},{"id":"q_pericoli","label":"Sente odore di gas o fumo in casa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"No, niente.","panic":"No! Ma cosa c''entra?!"}},{"id":"a_rassicura","type":"reassure","label":"Signora, la sto aiutando. Respiri con me e mi segua.","cost_s":8,"panic_delta":-25,"reply":{"calm":"Sì… sì, va bene.","panic":"Va bene… va bene, ci provo."}},{"id":"i_posizione","type":"reassure","label":"Lo metta a terra, sulla schiena, e si inginocchi al suo fianco. Metta il telefono in vivavoce.","cost_s":12,"panic_delta":-5,"requires":["q_respiro"],"hidden_if_flag":"rcp","reply":{"calm":"Ok… è pesante… ecco, l''ho tirato giù. È per terra. Ho messo il vivavoce.","panic":"È pesantissimo! …Ecco, è per terra! La sento, la sento!"}},{"id":"i_mani","type":"reassure","label":"Gli scopra il petto. Il palmo di una mano al centro del petto, l''altra mano sopra, braccia tese.","cost_s":8,"panic_delta":-5,"requires":["i_posizione"],"hidden_if_flag":"rcp","reply":{"calm":"Al centro del petto… una mano sopra l''altra. Così?","panic":"Una sopra l''altra… così? È giusto così?"}},{"id":"i_spingi","type":"reassure","label":"Spinga forte, giù di cinque o sei centimetri, e lasci risalire il petto. Veloce: conti con me, uno, due, tre, quattro…","cost_s":20,"panic_delta":-10,"requires":["i_mani"],"hidden_if_flag":"rcp","sets_flag":"rcp","reveals":["rcp"],"reply":{"calm":"Uno… due… tre… quattro… è durissimo… cinque… sei… sette…","panic":"Uno, due, tre… ho paura di fargli male… quattro, cinque…"}},{"id":"i_continua","type":"reassure","label":"Sta andando benissimo. Non si fermi: forte e veloce, cento, centoventi spinte al minuto, fino a quando arrivano.","cost_s":15,"panic_delta":-8,"requires_flag":"rcp","reply":{"calm":"Venti… ventuno… ventidue… non mi fermo.","panic":"Venti… ventuno… non so quanto ce la faccio!"},"repeat":{"calm":["Continuo… mi fanno male le braccia… trenta… trentuno…","Sento la sirena! Continuo finché non entrano!"],"panic":["Continuo! Continuo! Non sento più le braccia!","C''è la sirena! Continuo, continuo!"]}}],"truth":{"event_type":"sanitaria.arresto_cardiaco","agencies_required":["118"],"agencies_acceptable":[],"severity":{"optimal_s":60,"acceptable_s":150,"limit_s":300},"critical_facts":["indirizzo","coscienza","respiro"],"hint_debrief":"«Dorme ma non risponde» + «fa un rumore strano» indica un respiro agonico: va trasferito come arresto cardiaco appena confermati coscienza e respiro assenti. Subito dopo si guida la chiamante nelle compressioni: a terra sulla schiena, mani al centro del petto, forte e veloce, senza fermarsi."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_008', 'Dolore al petto minimizzato', 'sanitaria', 1, 4, 90, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_008","title":"Dolore al petto minimizzato","category":"sanitaria","phase":1,"difficulty":4,"weight":90,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"rad":{"choice":[{"text":"Beh… sì, un po'' anche sul braccio sinistro. E sudo freddo, ma sarà il caldo.","display":"Dolore che va al braccio sinistro, sudore freddo"},{"text":"No, sta qui in mezzo… però mi manca un po'' il fiato quando parlo.","display":"Dolore al centro del petto, affanno quando parla"}]},"patient_age":{"range":[56,74]}},"caller":{"gender":"m","phone_type":"any","panic_start":12,"ring_patience_s":50,"hold_patience_s":60,"reliability":0.85,"callback_chance":0.4,"voice":{"age":"adult"}},"opening":{"calm":["Buonasera, scusate il disturbo, niente di grave… ho un peso sullo stomaco da un paio d''ore, volevo sapere se posso prendere qualcosa.","Buonasera… guardi, sarà una sciocchezza: ho come un peso qui sullo stomaco da due ore. Cosa posso prendere?"],"panic":"Buonasera… scusate, ho un peso qui sul petto che non passa, volevo sapere cosa prendere."},"callback_opening":{"calm":"Buonasera, ho chiamato prima per quel peso sul petto… è caduta la linea. Non è passato, anzi.","panic":"Sono io, di prima… il dolore è più forte adesso. Mandate qualcuno, per favore."},"deterioration":[{"after_s":420,"sets_flag":"peggiora","panic":25,"line":{"calm":"Scusi… adesso il dolore è più forte. E sudo tantissimo.","panic":"Adesso fa male davvero… sudo, mi manca il fiato…"}},{"after_s":900,"panic":20,"line":{"calm":"Mi gira la testa… mi siedo per terra un attimo.","panic":"Mi gira tutto… mi devo sedere per terra… aiuto…"}}],"facts":{"dolore":{"label":"Sintomo","display":"Peso al centro del petto da circa due ore, «ma passa»"},"irradiazione":{"label":"Irradiazione","display":"{rad.display}"},"anamnesi":{"label":"Precedenti","display":"Due anni fa gli hanno messo uno stent"},"eta":{"display":"{patient_age} anni"},"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"accesso":{"display":"Solo in casa, dice di poter aprire"}},"nodes":[{"id":"q_sintomi","label":"Mi descriva il fastidio: dove lo sente e da quanto tempo?","cost_s":8,"reveals":["dolore"],"reply":{"calm":"Qui in mezzo al petto, tipo un peso. Da un paio d''ore… ma va e viene, eh.","panic":"In mezzo al petto, un peso… da due ore."},"repeat":{"calm":"Gliel''ho detto, qui in mezzo… un peso. Non passa.","panic":"In mezzo al petto! Adesso è più forte!"},"reply_flag":{"flag":"peggiora","calm":"In mezzo al petto… e adesso è più forte, mi prende anche la schiena.","panic":"Mi schiaccia il petto… adesso è fortissimo…"}},{"id":"q_irradia","label":"Il dolore va verso il braccio, il collo o la mandibola? Suda?","cost_s":7,"requires":["q_sintomi"],"reveals":["irradiazione"],"reply":{"calm":"{rad.text}","panic":"{rad.text}"},"error":{"threshold":101,"fact":"irradiazione","display":"Dice che il dolore resta fermo, nessun altro sintomo","reply":{"calm":"No no, niente, sta fermo lì. Sto bene, davvero."}}},{"id":"q_storia","label":"Ha mai avuto problemi di cuore?","cost_s":5,"reveals":["anamnesi"],"reply":{"calm":"Mah, due anni fa mi hanno messo uno stent… ma da allora niente.","panic":"Uno stent, due anni fa…"}},{"id":"q_eta","label":"Quanti anni ha?","cost_s":3,"reveals":["eta"],"reply":{"calm":"{patient_age}.","panic":"{patient_age}."}},{"id":"q_dove","label":"Mi dica l''indirizzo da cui chiama.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["Sono a casa, in {location.street} {location.number}. Ma non serve che mandiate qualcuno, eh.","{location.street} {location.number}. Ma davvero, non voglio farvi correre per niente."],"panic":"{location.street} {location.number}… venite, va bene."}},{"id":"q_accesso","label":"È solo? Riesce ad aprire la porta?","cost_s":5,"reveals":["accesso"],"reply":{"calm":"Sì, mia moglie è dalla sorella. Apro io, figurarsi.","panic":"Sono solo… apro io."}},{"id":"a_riposo","type":"reassure","label":"Si sieda, non faccia sforzi e apra la porta di casa: le mando un''ambulanza per sicurezza.","cost_s":7,"panic_delta":-5,"reply":{"calm":"Addirittura l''ambulanza? Va bene… se dice lei.","panic":"Va bene… grazie."}}],"truth":{"event_type":"sanitaria.dolore_toracico","acceptable_event_types":["sanitaria.malore"],"agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["dolore","indirizzo"],"hint_debrief":"Chi minimizza va preso sul serio: un peso al petto da ore, oltre i 50 anni e con uno stent alle spalle, è un''emergenza fino a prova contraria."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_010', 'Turista straniera, marito colto da malore', 'sanitaria', 1, 5, 70, 2, 'mattina,pomeriggio,sera', 0, 0, '{"code":"SAN_010","title":"Turista straniera, marito colto da malore","category":"sanitaria","phase":1,"difficulty":5,"weight":70,"min_rank":2,"time_bands":["mattina","pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro"],"floor":[1,3]},"patient_age":{"range":[64,79]}},"caller":{"gender":"f","first_pool":"names_de_f","surname_pool":"surnames_de","phone_type":"mobile","panic_start":72,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.9,"callback_chance":0.7,"voice":{"age":"elderly","accent":"de"}},"opening":{"calm":"Hello? Hallo? Please… my husband… he fall, now he speak not good!","panic":"Hallo?! Hilfe! Please, my husband, he fall, he speak strange!"},"facts":{"indirizzo":{"display":"Albergo in {location.street} {location.number}, {location.floor_text}"},"evento":{"display":"Il marito è caduto in bagno, parla male, un lato della bocca è storto"},"coscienza":{"display":"Sveglio, apre gli occhi, ma non riesce a parlare bene"},"eta":{"display":"{patient_age} anni"}},"nodes":[{"id":"a_interprete","label":"Attivare il servizio di interpretariato (tedesco).","cost_s":20,"panic_delta":-15,"sets_flag":"interprete","hidden_if_flag":"interprete","reply":{"calm":"Ja… ja, bitte! Danke!","panic":"Ja! Ja, bitte… schnell, schnell!"},"switch_caller":{"name":"Interprete","gender":"m","voice":{"age":"adult"},"panic_start":30,"reliability":1,"opening":{"calm":"Salve, sono l''interprete di tedesco in linea. La signora si chiama {caller_first}, è in vacanza qui con il marito. Traduco io: mi dica.","panic":"Interprete di tedesco in linea. La signora {caller_first} è molto agitata, ma la seguo io: mi dica."}}},{"id":"q_dove","label":"Where are you? Dove vi trovate?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Hotel… near {location.landmark}! I don''t know the street!","panic":"Hotel! Near… {location.landmark}! Please!"},"reply_flag":{"flag":"interprete","calm":"Dice che sono in albergo, in {location.street} {location.number}, camera al {location.floor_text}.","panic":"Albergo in {location.street} {location.number}, al {location.floor_text}: lo legge sulla chiave della camera."},"error":{"unless_flag":"interprete","threshold":0,"chance":1,"fact":"indirizzo","display":"Un albergo «near…», riferimento: {location.landmark}, via sconosciuta","reply":{"calm":"Hotel… near {location.landmark}! I don''t know the street!","panic":"Hotel! Near… {location.landmark}! Please!"}}},{"id":"q_cosa","label":"What happened? Cosa è successo?","cost_s":7,"reveals":["evento"],"reply":{"calm":"He fall in bathroom… now his words are wrong, his face… strange!","panic":"He fall! His face, his words… falsch, alles falsch!"},"reply_flag":{"flag":"interprete","calm":"Dice che il marito è caduto in bagno. Adesso parla in modo confuso e ha la bocca storta da un lato.","panic":"È caduto in bagno, parla male, ha la bocca storta da una parte. Lei è molto spaventata."},"error":{"unless_flag":"interprete","threshold":0,"chance":1,"fact":"evento","display":"Caduto in bagno, «parole sbagliate, faccia strana» (inglese stentato)","reply":{"calm":"He fall in bathroom… now his words are wrong, his face… strange!","panic":"He fall! His face, his words… falsch, alles falsch!"}}},{"id":"q_coscienza","label":"Is he awake? È sveglio, le risponde?","cost_s":6,"reveals":["coscienza"],"reply":{"calm":"Yes, eyes open… but he cannot say words.","panic":"Yes… yes, but no words!"},"reply_flag":{"flag":"interprete","calm":"Sì, è sveglio e la guarda, ma non riesce a parlare bene.","panic":"È sveglio, dice, ma non riesce a parlare."}},{"id":"q_eta","label":"How old is he? Quanti anni ha?","cost_s":4,"reveals":["eta"],"reply":{"calm":"{patient_age}.","panic":"{patient_age}!"},"reply_flag":{"flag":"interprete","calm":"Ha {patient_age} anni.","panic":"{patient_age} anni, dice."}},{"id":"a_calma","type":"reassure","label":"Help is coming. Stay with him. / Arrivano i soccorsi, resti con lui.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Okay… okay, danke.","panic":"Okay… please hurry!"}}],"truth":{"event_type":"sanitaria.ictus","acceptable_event_types":["sanitaria.malore","sanitaria.trauma_caduta"],"agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","evento"],"hint_debrief":"Parola alterata e bocca storta sono segni di ictus: conta ogni minuto. L''interprete costa 20 secondi, ma senza di lui l''indirizzo resta «un albergo vicino a…»."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_012', 'Escursionista ferito, batteria scarica', 'sanitaria', 1, 6, 70, 2, 'mattina,pomeriggio,sera', 0, 0, '{"code":"SAN_012","title":"Escursionista ferito, batteria scarica","category":"sanitaria","phase":1,"difficulty":6,"weight":70,"min_rank":2,"time_bands":["mattina","pomeriggio","sera"],"lang":"it","drop_after_s":[50,80],"variables":{"location":{"pool":"stradario","zones":["montagna"],"floor":[0,0]},"weather":{"choice":[{"text":"Sta calando il sole e tira un vento gelido.","display":"Sta facendo buio, vento freddo"},{"text":"C''è ancora luce, ma da ovest arriva un temporale.","display":"Luce per ora, temporale in arrivo"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":45,"ring_patience_s":40,"hold_patience_s":15,"reliability":0.95,"callback_chance":0.3,"voice":{"age":"adult","style":"breathless"}},"opening":{"calm":"Pronto? Sono in montagna, mi sono fatto male a una caviglia e non riesco a camminare… ho il telefono al 3 per cento.","panic":"Pronto?! Sono bloccato in montagna, la caviglia… non cammino, e il telefono si sta spegnendo!"},"timeline":[{"id":"bip","at_s":40,"say":{"calm":"(bip) Scusi, il telefono mi avvisa… è all''uno per cento.","panic":"(bip) Si sta spegnendo! È all''uno per cento! Mi avete capito dove sono?"},"panic_delta":10,"interrupt":false}],"facts":{"indirizzo":{"display":"{location.street}, dopo {location.landmark}"},"ferite":{"display":"Caviglia gonfia e deformata, non riesce ad appoggiare il piede"},"pericoli":{"display":"{weather.display}"},"persone":{"display":"Da solo"}},"nodes":[{"id":"q_dove","label":"Dove si trova? Che sentiero, cosa ha passato per ultimo?","cost_s":8,"reveals":["indirizzo"],"reply":{"calm":"Sono sul {location.street}, ho passato {location.landmark} una mezz''ora fa.","panic":"{location.street}… dopo {location.landmark}!"}},{"id":"q_ferite","label":"Com''è la caviglia? Riesce ad appoggiare il piede?","cost_s":6,"reveals":["ferite"],"reply":{"calm":"È gonfia e storta, non riesco proprio ad appoggiarla.","panic":"No! È storta, non la appoggio!"}},{"id":"q_meteo","label":"Com''è il tempo lì? Sta facendo buio?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{weather.text}","panic":"{weather.text}"}},{"id":"q_solo","label":"È da solo?","cost_s":3,"reveals":["persone"],"reply":{"calm":"Sì, da solo.","panic":"Sì!"}},{"id":"a_batteria","type":"reassure","label":"Resti fermo dov''è, si copra e spenga tutto sul telefono tranne le chiamate: la troviamo noi.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Ok. Resto qui.","panic":"Ok… ok, faccio così."}}],"truth":{"event_type":"sanitaria.soccorso_impervio","acceptable_event_types":["sanitaria.trauma_caduta","incendio_tecnico.soccorso_persona"],"agencies_required":["118"],"agencies_acceptable":["CC","115"],"severity":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600},"critical_facts":["indirizzo","ferite"],"hint_debrief":"Con la batteria agli ultimi minuti la priorità è il luogo: poche domande mirate e trasferimento prima che la linea cada. Il cerchio AML in montagna è ampio: il punto di riferimento conta."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_014', 'Bambino: la mamma non si sveglia', 'sanitaria', 1, 7, 65, 2, 'mattina,pomeriggio,sera', 0, 0, '{"code":"SAN_014","title":"Bambino: la mamma non si sveglia","category":"sanitaria","phase":1,"difficulty":7,"weight":65,"min_rank":2,"time_bands":["mattina","pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro","colline"],"floor":[0,4]},"kid_age":{"range":[6,9]},"mom":{"choice":[{"text":"Ha aperto un po'' gli occhi… ma non mi risponde bene.","display":"Apre appena gli occhi, non risponde bene"},{"text":"No… non si muove…","display":"Non si muove"}]}},"caller":{"gender":"any","phone_type":"landline","panic_start":55,"ring_patience_s":25,"hold_patience_s":8,"reliability":0.7,"callback_chance":0.5,"voice":{"age":"child","style":"crying"}},"opening":{"calm":"Pronto?… La mamma è caduta per terra e non si sveglia…","panic":"Pronto?! La mamma… la mamma non si sveglia! (piange)"},"callback_opening":{"calm":"Pronto? Sono di nuovo io… la mamma non si sveglia ancora.","panic":"(piange) Pronto?! Sono io! La mamma non si sveglia!"},"facts":{"chiamante":{"label":"Chi chiama","display":"{caller_first}, {kid_age} anni"},"coscienza":{"display":"{mom.display}"},"respiro":{"display":"«La pancia si alza e si abbassa»"},"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text}"},"persone":{"display":"Solo in casa con la mamma; la vicina del piano di sopra è in casa"},"farmaci":{"label":"Terapie","display":"La mamma fa «le punture per lo zucchero»"},"kit":{"label":"Farmaci in casa","display":"In frigo c''è il kit del glucagone; la vicina non sa usarlo"}},"nodes":[{"id":"q_nome","label":"Come ti chiami? Quanti anni hai?","cost_s":5,"panic_delta":-10,"reveals":["chiamante"],"reply":{"calm":"{caller_first}… ho {kid_age} anni.","panic":"{caller_first}… (singhiozza) {kid_age}…"}},{"id":"q_mamma","label":"Chiama forte la mamma e toccale la spalla. Si muove?","cost_s":9,"reveals":["coscienza"],"reply":{"calm":"{mom.text}","panic":"{mom.text} (piange)"}},{"id":"q_respiro","label":"Guarda la pancia della mamma: si alza e si abbassa?","cost_s":8,"requires":["q_mamma"],"reveals":["respiro"],"reply":{"calm":"Sì… si muove su e giù.","panic":"Sì… sì, si muove."}},{"id":"q_dove","label":"Sai dirmi dove abiti? Come si chiama la tua via?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}, al {location.floor_text}.","panic":"{location.street} {location.number}… al {location.floor_text}!"},"reply_flag":{"flag":"vicina","calm":"È in {location.street} {location.number}, al {location.floor_text}. Il portone è aperto.","panic":"{location.street} {location.number}, {location.floor_text}! Lascio aperto il portone!"},"error":{"unless_flag":"vicina","threshold":0,"chance":1,"fact":"indirizzo","display":"Non ricorda la via: «dove c''è {location.landmark}»","reply":{"calm":"Abito dove c''è {location.landmark}… la via non me la ricordo.","panic":"Non lo so! C''è {location.landmark}…"}}},{"id":"q_adulti","label":"C''è un altro grande in casa? Un vicino che conosci?","cost_s":6,"reveals":["persone"],"reply":{"calm":"Papà è al lavoro. La signora di sopra c''è, ha il cane.","panic":"No… la signora di sopra forse."}},{"id":"q_vicina","label":"Vai a chiamare la signora di sopra, porta su il telefono e passamela. Io resto qui.","cost_s":25,"requires":["q_adulti"],"sets_flag":"vicina","hidden_if_flag":"vicina","reply":{"calm":"Va bene… (silenzio, poi passi di corsa e voci concitate)","panic":"Va bene… (silenzio, poi colpi forti a una porta) Signora! Signora!"},"switch_caller":{"name":"La vicina","gender":"f","voice":{"age":"elderly"},"panic_start":40,"reliability":0.95,"opening":{"calm":"Pronto? Sono la vicina di sopra, mi ha chiamato {caller_first}. Sono qui con la mamma, mi dica cosa devo fare.","panic":"Pronto?! Sono la vicina! La signora è per terra, cosa faccio?"}}},{"id":"q_kit","label":"Signora, la mamma è diabetica: vede un misuratore o un kit per lo zucchero basso in casa?","cost_s":8,"requires_flag":"vicina","reveals":["kit"],"reply":{"calm":"C''è il misuratore sul tavolo… e in frigo una scatola arancione, il glucagone. Ma io non lo so fare.","panic":"In frigo c''è una scatola arancione… ma io non so come si fa!"}},{"id":"a_fianco","type":"reassure","label":"Non le dia niente da bere né da mangiare finché non è sveglia. Se respira, la giri su un fianco, e apra la porta ai soccorsi.","cost_s":8,"panic_delta":-15,"requires_flag":"vicina","reply":{"calm":"Va bene: niente in bocca, la giro sul fianco… ecco. E vado ad aprire.","panic":"Sul fianco… ecco, così. Respira! Vado ad aprire!"}},{"id":"q_farmaci","label":"La mamma prende delle medicine? Fa delle punture?","cost_s":6,"reveals":["farmaci"],"reply":{"calm":"Sì, fa le punture per lo zucchero. Sulla pancia.","panic":"Le punture… per lo zucchero…"}},{"id":"a_bravo","type":"reassure","label":"Sei bravissim{g.o}. Resta vicino alla mamma: sto mandando qualcuno ad aiutarvi.","cost_s":6,"panic_delta":-22,"reply":{"calm":"Va bene… resto qui con lei.","panic":"Va bene… (tira su col naso)"}}],"truth":{"event_type":"sanitaria.incosciente","acceptable_event_types":["sanitaria.malore"],"agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","coscienza"],"hint_debrief":"Un bambino non sa dare l''indirizzo: con la linea fissa l''indirizzo di intestazione è decisivo. Non metterlo in attesa: riattacca dopo pochi secondi. Le «punture per lo zucchero» fanno pensare a un''ipoglicemia."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_016', 'Difficoltà respiratoria', 'sanitaria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_016","title":"Difficoltà respiratoria","category":"sanitaria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"open":"Pronto, mio figlio ha l''asma, ha usato lo spray due volte ma respira sempre peggio, fischia tutto.","cosa":"Figlio asmatico: peggiora nonostante due dosi di spray","resp_t":"Parla a fatica, una parola per volta… e le labbra sono un po'' scure.","resp":"Parla a monosillabi, labbra scure","event":"sanitaria.difficolta_respiratoria","acc":["sanitaria.reazione_allergica"],"sev":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"cosa_t":"Ha avuto una crisi d''asma un''ora fa, gli ho dato lo spray due volte ma niente, fischia sempre di più.","adv":"Lo tenga seduto, un po'' in avanti, e gli faccia fare lo spray come le ha detto il medico. Resti con lui e apra la porta di casa.","adv_r":"Va bene, lo tengo seduto… dai amore, respira piano.","det_c":"Adesso non riesce quasi più a parlare… è stanchissimo, chiude gli occhi."},{"open":"Pronto! Mia madre ha mangiato dei gamberetti… adesso ha la faccia gonfia e respira male!","cosa":"Dopo aver mangiato crostacei: viso gonfio, respira male","resp_t":"Dice che le si chiude la gola… ha delle chiazze rosse su tutto il collo.","resp":"Sensazione di gola che si chiude, chiazze rosse","event":"sanitaria.reazione_allergica","acc":["sanitaria.difficolta_respiratoria"],"sev":{"optimal_s":180,"acceptable_s":360,"limit_s":900},"cosa_t":"Abbiamo cenato coi gamberetti, mezz''ora fa. Prima le prudeva la bocca, adesso ha la faccia tutta gonfia.","adv":"La faccia sedere se respira male, sdraiata con le gambe in alto se le gira la testa. Se ha l''adrenalina, gliela faccia subito nella coscia.","adv_r":"La tengo seduta… l''adrenalina no, non ce l''ha!","det_c":"La gola le si chiude sempre di più… adesso fa un fischio quando respira!"},{"open":"Aiuto! Mio papà stava mangiando e si è bloccato, non respira, sta diventando viola!","cosa":"Si è bloccato mangiando: probabile ostruzione da cibo","resp_t":"Non esce aria! Si tiene la gola con le mani e non riesce a tossire!","resp":"Non passa aria, non riesce a tossire","event":"sanitaria.difficolta_respiratoria","acc":["sanitaria.arresto_cardiaco"],"sev":{"optimal_s":60,"acceptable_s":150,"limit_s":360},"cosa_t":"Stava mangiando la carne, ha fatto un colpo di tosse e poi più niente, si tiene la gola!","adv":"Se tossisce lo lasci tossire. Se non tossisce più: lo pieghi in avanti e gli dia cinque colpi forti tra le scapole col palmo della mano, poi cinque spinte decise sopra l''ombelico, da dietro. E ricominci.","adv_r":"Lo piego in avanti… uno, due, tre… dai, papà, sputa!","det_c":"È diventato tutto viola… si sta accasciando, non sta più in piedi!"},{"open":"Buonasera, mio nonno ha l''enfisema… stanotte respira peggio del solito, è molto affannato.","cosa":"Malato cronico ai polmoni, affanno peggiorato stanotte","resp_t":"Parla, ma deve fermarsi ogni poco per prendere fiato. Ha l''ossigeno ma non basta.","resp":"Parla a frasi brevi, l''ossigeno di casa non basta","event":"sanitaria.difficolta_respiratoria","acc":[],"sev":{"optimal_s":420,"acceptable_s":900,"limit_s":1800},"cosa_t":"Sta male da stasera, è sempre più affannato. Ha l''enfisema da anni, ma così non l''ho mai visto.","adv":"Lo tenga seduto con le gambe giù, lasci l''ossigeno come gliel''ha prescritto il medico e apra la porta di casa.","adv_r":"Va bene, lo tengo seduto sulla poltrona.","det_c":"Adesso è tutto sudato e mi sembra confuso, non mi riconosce bene."}]}},"caller":{"gender":"any","phone_type":"any","panic_start":60,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.6,"voice":{"age":"adult","style":"breathless"}},"opening":{"calm":"{sc.open}","panic":"{sc.open}","hyst":"{sc.open} Aiuto!"},"callback_opening":{"calm":"Sono io di nuovo, ho chiamato prima per la difficoltà a respirare… è caduta la linea.","panic":"Sono di nuovo io! Respira sempre peggio, dove siete?!"},"deterioration":[{"after_s":150,"sets_flag":"peggiora","panic":20,"line":{"calm":"{sc.det_c}","panic":"{sc.det_c} Fate presto!"}}],"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"evento":{"display":"{sc.cosa}"},"respiro":{"display":"{sc.resp}"}},"nodes":[{"id":"q_dove","label":"L''indirizzo dove siete adesso, con il numero civico?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","Siamo in {location.street}, al numero {location.number}."],"panic":"{location.street}… il {location.number}!","hyst":"{location.street}! Il… il {location.number}! Correte!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!","hyst":"{location.street}! Il {location.number_wrong}! Correte!"}}},{"id":"q_piano","label":"A che piano? Che nome c''è sul campanello?","cost_s":5,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, {caller_surname}.","panic":"{location.floor_text}! Sul campanello c''è {caller_surname}!"},"requires":["q_dove"]},{"id":"q_cosa","label":"Mi racconti cosa è successo e da quando.","cost_s":7,"reveals":["evento"],"reply":{"calm":"{sc.cosa_t}","panic":"{sc.open}"}},{"id":"q_parla","label":"Riesce a parlare? Di che colore sono le labbra?","cost_s":7,"reveals":["respiro"],"reply":{"calm":"{sc.resp_t}","panic":"{sc.resp_t} Fate presto!"},"reply_flag":{"flag":"peggiora","calm":"{sc.det_c}","panic":"{sc.det_c} Non ce la fa!"}},{"id":"a_rassicura","type":"reassure","label":"{sc.adv}","cost_s":6,"panic_delta":-15,"reply":{"calm":"{sc.adv_r}","panic":"Sì… sì, faccio così, ma fate presto!"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","respiro"],"hint_debrief":"Nelle difficoltà respiratorie la domanda chiave è se la persona riesce a parlare: chi non riesce a dire una frase intera è grave."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_017', 'Parto in casa', 'sanitaria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_017","title":"Parto in casa","category":"sanitaria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"c":"Ogni otto, dieci minuti. Le acque non si sono rotte.","cd":"Contrazioni ogni 8-10 minuti, acque integre","f":"È il primo.","fd":"Primo figlio","s":"No, dice di no.","sd":"Nessuna spinta","sev":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600}},{"c":"Ogni due minuti! E si sono rotte le acque mezz''ora fa!","cd":"Contrazioni ogni 2 minuti, acque rotte","f":"È il terzo… gli altri due sono nati velocissimi!","fd":"Terzo figlio, parti precedenti rapidi","s":"Sì, dice che deve spingere!","sd":"Sente il bisogno di spingere","sev":{"optimal_s":240,"acceptable_s":480,"limit_s":900}},{"c":"Di continuo, una dietro l''altra!","cd":"Contrazioni continue","f":"Il secondo.","fd":"Secondo figlio","s":"Si vede la testa! Si vede la testa del bambino!","sd":"Parto in corso: si vede la testa","sev":{"optimal_s":120,"acceptable_s":300,"limit_s":600}}]}},"caller":{"gender":"m","phone_type":"any","panic_start":70,"ring_patience_s":35,"hold_patience_s":15,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, mia moglie è incinta e le sono iniziate le contrazioni, credo che stia per partorire!","panic":"Pronto! Mia moglie sta partorendo! Cosa faccio?!","hyst":"Sta nascendo! Sta nascendo adesso! Cosa faccio?!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"contrazioni":{"label":"Contrazioni","display":"{sc.cd}"},"figli":{"label":"Gravidanze precedenti","display":"{sc.fd}"},"spinta":{"label":"Fase del parto","display":"{sc.sd}"}},"nodes":[{"id":"q_dove","label":"Dove abitate? Mi dica via e civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!","hyst":"{location.street}! Il {location.number}! Sbrigatevi!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_piano","label":"A che piano? Citofono?","cost_s":4,"reveals":["piano"],"reply":{"calm":"{location.floor_text}, {caller_surname}.","panic":"{location.floor_text}, {caller_surname}. Fate presto, per favore!"},"requires":["q_dove"]},{"id":"q_contr","label":"Ogni quanto arrivano le contrazioni? Si sono rotte le acque?","cost_s":7,"reveals":["contrazioni"],"reply":{"calm":"{sc.c}","panic":"{sc.c} Correte!"}},{"id":"q_figli","label":"È il primo figlio?","cost_s":4,"reveals":["figli"],"reply":{"calm":"{sc.f}","panic":"{sc.f} Fate presto, per favore!"}},{"id":"q_spinta","label":"Sente il bisogno di spingere? Si vede già qualcosa?","cost_s":7,"reveals":["spinta"],"reply":{"calm":"{sc.s}","panic":"{sc.s} Vi prego, presto!"},"requires":["q_contr"]},{"id":"a_rassicura","type":"reassure","label":"La faccia sdraiare sul fianco sinistro, prepari degli asciugamani puliti e apra la porta di casa.","cost_s":6,"panic_delta":-20,"reply":{"calm":"Ok… ok, asciugamani, porta aperta.","panic":"Sì! Asciugamani… va bene!"}}],"truth":{"event_type":"sanitaria.parto","agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","contrazioni","spinta"],"hint_debrief":"Nel parto contano frequenza delle contrazioni, numero di gravidanze e bisogno di spingere: dicono quanto tempo resta."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_018', 'Convulsioni', 'sanitaria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_018","title":"Convulsioni","category":"sanitaria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"open":"Pronto! Mia figlia di due anni ha avuto le convulsioni, tremava tutta! Ha la febbre alta.","d":"È durata un minuto, adesso ha smesso ma è molto addormentata.","dd":"Crisi di circa un minuto, finita; bambina assopita","t":"Ha la febbre a 39 e mezzo. Non ha battuto la testa.","td":"Febbre a 39,5, nessun trauma","sev":{"optimal_s":420,"acceptable_s":900,"limit_s":1800}},{"open":"Pronto, mio fratello è epilettico, ha una crisi e non smette!","d":"Sta andando avanti da sei, sette minuti… non si ferma!","dd":"Crisi in corso da oltre 6 minuti","t":"Niente febbre, è epilettico da anni, ma di solito dura poco.","td":"Epilessia nota, nessuna febbre","sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900}},{"open":"Pronto, un ragazzo è caduto dalla bici qui davanti, ha sbattuto la testa e adesso sta tremando tutto!","d":"Ha tremato un minuto… adesso è fermo ma non risponde bene.","dd":"Convulsioni dopo trauma cranico, ora confuso","t":"Ha battuto la testa sull''asfalto, niente casco.","td":"Trauma cranico senza casco","sev":{"optimal_s":240,"acceptable_s":480,"limit_s":1200}}]}},"caller":{"gender":"any","phone_type":"any","panic_start":70,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.6,"voice":{"age":"adult","style":"breathless"}},"opening":{"calm":"{sc.open}","panic":"{sc.open}","hyst":"{sc.open} Aiuto! Aiuto!"},"callback_opening":{"calm":"Sono di nuovo io, per le convulsioni… è caduta la linea.","panic":"Sono io! Ha ricominciato a tremare! Dove siete?!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"durata":{"label":"Crisi","display":"{sc.dd}"},"trauma":{"label":"Febbre o traumi","display":"{sc.td}"},"respiro":{"display":"Respira"}},"nodes":[{"id":"q_dove","label":"Dove vi trovate? Via e numero, per mandare l''ambulanza.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","Siamo in {location.street}, il civico è {location.number}."],"panic":"{location.street}… il {location.number}!","hyst":"{location.street}! Il… non lo so! Il {location.number}!"},"error":{"threshold":65,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} {location.number}, {location.zone_name}","reply":{"panic":"In {location.street_wrong}… sì, {location.street_wrong}, il {location.number}!","hyst":"{location.street_wrong}! No… sì! Il {location.number}!"}}},{"id":"q_durata","label":"Da quanto dura la crisi? Si è fermata?","cost_s":6,"reveals":["durata"],"reply":{"calm":"{sc.d}","panic":"{sc.d} Fate presto!"}},{"id":"q_trauma","label":"Ha febbre? Ha battuto la testa?","cost_s":6,"reveals":["trauma"],"reply":{"calm":"{sc.t}","panic":"{sc.t} Vi prego, presto!"}},{"id":"q_respiro","label":"Adesso respira?","cost_s":5,"reveals":["respiro"],"reply":{"calm":"Sì, respira… un po'' rumoroso, ma respira.","panic":"Sì! Sì, respira!"},"requires":["q_durata"]},{"id":"a_rassicura","type":"reassure","label":"Non mettete niente in bocca, spostate gli oggetti intorno e quando smette mettetelo su un fianco.","cost_s":6,"panic_delta":-18,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sanitaria.convulsioni","acceptable_event_types":["sanitaria.malore","sanitaria.incosciente"],"agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","durata"],"hint_debrief":"Una crisi che dura più di cinque minuti, o che segue un trauma alla testa, è un''emergenza grave: la durata va sempre chiesta."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_019', 'Persona a terra in strada', 'sanitaria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"SAN_019","title":"Persona a terra in strada","category":"sanitaria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.3,"max":1,"delay_s":[30,150],"near_twin_chance":0.12},"witness_opening":{"calm":"Buonasera, c''è una persona a terra in {location.street}, c''è {location.landmark} lì vicino.","panic":"C''è una persona a terra in {location.street}!"},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"sc":{"choice":[{"r":"No… non risponde. È un signore anziano.","rd":"Uomo anziano, non risponde","b":"Non vedo il petto muoversi… no, non respira!","bd":"Non respira","i":"Niente, ha la borsa della spesa rovesciata.","event":"sanitaria.arresto_cardiaco","acc":["sanitaria.incosciente"],"sev":{"optimal_s":60,"acceptable_s":150,"limit_s":300},"idd":"Nessun indizio particolare","det":"Adesso ha la faccia grigia… le labbra sono viola!","rp":"No! Non risponde! È un signore anziano, non si muove!","bp":"Il petto non si muove… non respira! Non respira!","pos":"Ok, l''ho girato sulla schiena… è per terra sul marciapiede.","mani":"Ok… al centro del petto, una mano sopra l''altra.","spingi":"Uno… due… tre… quattro… è durissimo… cinque… sei…","cont":"Venti… ventuno… ventidue… non mi fermo.","cont_r":["Sto continuando… ho le braccia che bruciano… trenta…","Continuo… sento una sirena, forse sono loro!"],"rcpd":"Il chiamante esegue le compressioni toraciche, guidato dall''operatore"},{"r":"Borbotta qualcosa… puzza di alcol. È un ragazzo.","rd":"Ragazzo, risponde a monosillabi, odore di alcol","b":"Sì, respira, russa quasi.","bd":"Respira","i":"Ci sono delle bottiglie vuote vicino alla panchina.","event":"sanitaria.intossicazione","acc":["sanitaria.malore","sanitaria.incosciente"],"sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400},"idd":"Bottiglie vuote vicino","det":"Ha vomitato… adesso russa fortissimo e non lo sveglio più.","rp":"Borbotta… puzza di alcol, è un ragazzo, non sta in piedi!","bp":"Sì, respira, russa forte!","pos":"Ma… respira, russa! Devo girarlo lo stesso?","mani":"Guardi che respira… io le mani gliele metto, ma non mi sembra il caso.","spingi":"No, scusi, non me la sento: respira, si lamenta… se lo schiaccio gli faccio male!","cont":"Ma io non sto facendo niente, respira da solo!","cont_r":"Glielo ripeto: non sto facendo niente, respira da solo.","rcpd":"Istruzioni di rianimazione date per una persona che respira: il chiamante si rifiuta"},{"r":"È una signora, risponde ma è confusa, tutta sudata.","rd":"Donna confusa e sudata","b":"Sì, respira normalmente.","bd":"Respira normalmente","i":"Ha un braccialetto… c''è scritto «diabetica».","event":"sanitaria.malore","acc":["sanitaria.incosciente"],"sev":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"idd":"Braccialetto: diabetica","det":"Prima parlava, adesso non risponde più! Ha chiuso gli occhi!","rp":"È una signora, è tutta sudata, dice cose senza senso!","bp":"Sì, respira… respira veloce!","pos":"Ma lei respira, e mi guarda! Devo proprio sdraiarla?","mani":"Ma… si sta muovendo, mi spinge via la mano!","spingi":"Non posso, mi parla! Mi dice di lasciarla stare!","cont":"Non sto facendo niente, è sveglia!","cont_r":"Ma è sveglia, gliel''ho detto! Mi parla!","rcpd":"Istruzioni di rianimazione date per una persona sveglia: il chiamante si rifiuta"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.4},"opening":{"calm":"Pronto, c''è una persona a terra sul marciapiede, non so cosa abbia.","panic":"Pronto! C''è uno a terra per strada, non si muove!"},"callback_opening":{"calm":"Pronto, ho chiamato prima per la persona a terra in {location.street}… è caduta la linea.","panic":"Sono io, quello della persona a terra in {location.street}! Non arriva nessuno!"},"deterioration":[{"after_s":150,"sets_flag":"peggiora","panic":20,"line":{"calm":"{sc.det}","panic":"{sc.det} Fate presto!"}}],"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"coscienza":{"display":"{sc.rd}"},"respiro":{"display":"{sc.bd}"},"indizi":{"label":"Indizi","display":"{sc.idd}"},"rcp":{"label":"Rianimazione","display":"{sc.rcpd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova esattamente? Strada e un punto di riferimento, un negozio, un civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["In {location.street}, c''è {location.landmark} lì vicino.","Sono in {location.street}… c''è {location.landmark} proprio qui davanti."],"panic":"{location.street}! C''è {location.landmark} davanti!","hyst":"{location.street}! {location.landmark}! Venite, presto!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_risponde","label":"Si avvicini e gli parli forte, gli tocchi la spalla: risponde?","cost_s":9,"reveals":["coscienza"],"reply":{"calm":"{sc.r}","panic":"{sc.rp}"}},{"id":"q_respiro","label":"Guardi il petto per qualche secondo: respira normalmente?","cost_s":9,"reveals":["respiro"],"reply":{"calm":"{sc.b}","panic":"{sc.bp}"},"requires":["q_risponde"],"reply_flag":{"flag":"peggiora","calm":"{sc.det}","panic":"{sc.det} Faccia presto!"}},{"id":"q_indizi","label":"Vede qualcosa intorno o addosso a lui: bottiglie, sangue, un bracciale medico?","cost_s":6,"reveals":["indizi"],"reply":{"calm":"{sc.i}","panic":"{sc.i} Vi prego, presto!"}},{"id":"i_posizione","type":"reassure","label":"Se non respira normalmente: lo metta a terra sulla schiena e si inginocchi al suo fianco.","cost_s":8,"panic_delta":-5,"requires":["q_respiro"],"hidden_if_flag":"rcp","reply":{"calm":"{sc.pos}","panic":"{sc.pos}"}},{"id":"i_mani","type":"reassure","label":"Metta il palmo di una mano al centro del petto, l''altra mano sopra, braccia tese.","cost_s":8,"panic_delta":-5,"requires":["i_posizione"],"hidden_if_flag":"rcp","reply":{"calm":"{sc.mani}","panic":"{sc.mani}"}},{"id":"i_spingi","type":"reassure","label":"Spinga forte, giù di cinque o sei centimetri, e lasci risalire. Veloce: conti con me, uno, due, tre, quattro…","cost_s":20,"panic_delta":-10,"requires":["i_mani"],"sets_flag":"rcp","hidden_if_flag":"rcp","reveals":["rcp"],"reply":{"calm":"{sc.spingi}","panic":"{sc.spingi}"}},{"id":"i_continua","type":"reassure","label":"Bravo, va benissimo. Non si fermi: forte e veloce, cento, centoventi al minuto, fino a quando arrivano.","cost_s":15,"panic_delta":-8,"requires_flag":"rcp","reply":{"calm":"{sc.cont}","panic":"{sc.cont}"},"repeat":{"calm":"{sc.cont_r}","panic":"{sc.cont_r}"}},{"id":"a_rassicura","type":"reassure","label":"Resti con la persona e chieda aiuto a chi passa: l''ambulanza è in arrivo.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","coscienza","respiro"],"hint_debrief":"Davanti a una persona a terra servono tre cose: dove, se risponde, se respira. Se non respira, si guida subito chi chiama nelle compressioni: mani al centro del petto, forte e veloce, senza fermarsi fino all''arrivo dei soccorsi."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_020', 'Tutta la famiglia ha mal di testa', 'sanitaria', 1, 5, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_020","title":"Tutta la famiglia ha mal di testa","category":"sanitaria","phase":1,"difficulty":5,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,3]},"sc":{"choice":[{"f":"Abbiamo la stufa a pellet accesa in soggiorno da stamattina, con le finestre chiuse per il freddo.","fd":"Stufa a pellet accesa, finestre chiuse"},{"f":"C''è la caldaia vecchia in bagno… ieri l''ho sentita fare un rumore strano.","fd":"Vecchia caldaia in bagno, rumori anomali"},{"f":"Ho acceso un braciere in camera per scaldare… fa così freddo.","fd":"Braciere acceso in camera da letto"}]}},"caller":{"gender":"f","phone_type":"any","panic_start":30,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.9,"callback_chance":0.4},"opening":{"calm":"Buonasera, scusi… a casa abbiamo tutti mal di testa e nausea, anche i bambini. Sarà un virus? Il piccolo non si sveglia bene.","panic":"Pronto… stiamo tutti male, mal di testa, nausea… il piccolo non si sveglia bene!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"sintomi":{"label":"Sintomi","display":"Tutta la famiglia: mal di testa e nausea; il bambino più piccolo fatica a svegliarsi"},"fonte":{"label":"Possibile fonte","display":"{sc.fd}"},"persone":{"display":"Quattro persone in casa, due bambini"}},"nodes":[{"id":"q_dove","label":"Mi dà l''indirizzo di casa vostra?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_piano","label":"A che piano abitate?","cost_s":4,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, {caller_surname}.","panic":"Al {location.floor_text}, {caller_surname}."},"requires":["q_dove"]},{"id":"q_sintomi","label":"Da quando state male? Chi è più grave?","cost_s":7,"reveals":["sintomi"],"reply":{"calm":"Da un paio d''ore. Il più piccolo dorme e se lo chiamo apre appena gli occhi.","panic":"Da un paio d''ore. Il più piccolo dorme e se lo chiamo apre appena gli occhi."}},{"id":"q_fonte","label":"Avete stufe, caldaie o bracieri accesi in casa?","cost_s":6,"reveals":["fonte"],"reply":{"calm":"{sc.f}","panic":"{sc.f}"}},{"id":"q_persone","label":"Quante persone ci sono in casa?","cost_s":4,"reveals":["persone"],"reply":{"calm":"Siamo in quattro, io, mio marito e i due bambini.","panic":"Siamo in quattro, io, mio marito e i due bambini."}},{"id":"a_esci","type":"reassure","label":"Aprite subito tutte le finestre, spegnete la stufa se potete e uscite tutti all''aria aperta, portando fuori il piccolo.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Oddio… sì, usciamo subito.","panic":"Usciamo! Usciamo subito!"}}],"truth":{"event_type":"sanitaria.intossicazione","agencies_required":["118","115"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","fonte"],"hint_debrief":"Tutti in casa con mal di testa e nausea, e una fonte di combustione accesa: è monossido di carbonio, non un virus. Servono 118 e Vigili del fuoco, e bisogna far uscire tutti."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_021', 'Ha preso qualcosa che non doveva', 'sanitaria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_021","title":"Ha preso qualcosa che non doveva","category":"sanitaria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"open":"Pronto! Mio figlio di tre anni ha bevuto il detersivo della lavastoviglie!","c":"Ne ha bevuto un sorso, forse due… cinque minuti fa.","cd":"Detersivo per lavastoviglie, un sorso o due, 5 minuti fa","k":"Piange, sta bene, ma ha la bocca arrossata.","kd":"Sveglio, piange, bocca arrossata","n":"Sì, ce l''ho qui: detersivo gel per lavastoviglie.","nd":"Detersivo gel per lavastoviglie"},{"open":"Pronto, mia madre ha preso le pastiglie due volte stamattina, credo… non si ricorda.","c":"Le pastiglie della pressione e quelle per il sangue, due volte.","cd":"Doppia dose di antipertensivi e anticoagulante","k":"È un po'' confusa e dice che le gira la testa.","kd":"Confusa, capogiri","n":"Sì, ecco… sono il Coumadin e un''altra che non so leggere.","nd":"Anticoagulante e un antipertensivo"},{"open":"Pronto, siamo a una festa… un mio amico ha bevuto e preso delle pastiglie, adesso non sta in piedi.","c":"Non lo so quante… un paio, un''ora fa, con la vodka.","cd":"Pastiglie sconosciute con alcol, un''ora fa","k":"Dorme, se lo scuoti apre gli occhi e poi li richiude.","kd":"Soporoso, risponde appena","n":"No… non c''è nessuna scatola.","nd":"Sostanza sconosciuta"}]}},"caller":{"gender":"any","phone_type":"any","panic_start":60,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"{sc.open}","panic":"{sc.open}"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"cosa":{"label":"Cosa e quando","display":"{sc.cd}"},"coscienza":{"display":"{sc.kd}"},"sostanza":{"label":"Confezione","display":"{sc.nd}"}},"nodes":[{"id":"q_dove","label":"Da che indirizzo chiama? Via e numero.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} {location.number}, {location.zone_name}","reply":{"panic":"In {location.street_wrong}… sì, {location.street_wrong}, il {location.number}!","hyst":"{location.street_wrong}! No… sì! Il {location.number}!"}}},{"id":"q_cosa","label":"Cosa ha preso, quanto e quando?","cost_s":7,"reveals":["cosa"],"reply":{"calm":"{sc.c}","panic":"{sc.c} Vi prego, presto!"}},{"id":"q_coscienza","label":"Come sta adesso? È sveglio, risponde?","cost_s":6,"reveals":["coscienza"],"reply":{"calm":"{sc.k}","panic":"{sc.k} Correte!"}},{"id":"q_confezione","label":"Ha la confezione? Mi legge il nome?","cost_s":7,"reveals":["sostanza"],"reply":{"calm":"{sc.n}","panic":"{sc.n} Vi prego, presto!"}},{"id":"a_rassicura","type":"reassure","label":"Non lo faccia vomitare, non gli dia da bere, e tenga la confezione per i soccorritori.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sanitaria.intossicazione","agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","cosa"],"hint_debrief":"Nelle intossicazioni servono cosa, quanto e quando: la confezione vale più di mille descrizioni. Non va mai indotto il vomito."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_022', 'Infortunio in azienda', 'sanitaria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_022","title":"Infortunio in azienda","category":"sanitaria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["industriale"],"floor":[0,0]},"sc":{"choice":[{"h":"È caduto da una scala, saranno tre metri.","hd":"Caduta da circa 3 metri","k":"È sveglio, si lamenta per la gamba, dice che non la sente bene.","kd":"Cosciente, dolore alla gamba","x":"No, è a terra libero.","xd":"Nessuna parte incastrata","ag":["118"],"event":"sanitaria.trauma_caduta"},{"h":"È caduto dal tetto del capannone… sei metri almeno!","hd":"Caduta da almeno 6 metri","k":"Non risponde! Respira ma non risponde!","kd":"Non risponde, respira","x":"No, è sul piazzale.","xd":"Nessuna parte incastrata","ag":["118"],"event":"sanitaria.trauma_caduta"},{"h":"Nessuna caduta: gli è rimasta la mano nella pressa!","hd":"Mano schiacciata in una pressa","k":"È sveglio, urla dal dolore, è bianchissimo.","kd":"Cosciente, pallido, dolore forte","x":"Sì! La mano è ancora dentro, la macchina è ferma ma non riusciamo a tirarla fuori!","xd":"Mano incastrata nella macchina","ag":["118","115"],"event":"sanitaria.ferita"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":60,"ring_patience_s":30,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, qui in ditta un operaio si è fatto male, serve un''ambulanza!","panic":"Pronto! Un incidente in ditta, un operaio si è fatto male, presto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, zona artigianale"},"dinamica":{"label":"Dinamica","display":"{sc.hd}"},"coscienza":{"display":"{sc.kd}"},"incastro":{"label":"Incastrato","display":"{sc.xd}"}},"nodes":[{"id":"q_dove","label":"In che via è l''azienda? Numero civico e da che ingresso si entra?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}, entrate dal cancello grande.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_come","label":"Cosa è successo esattamente?","cost_s":6,"reveals":["dinamica"],"reply":{"calm":"{sc.h}","panic":"{sc.h} Fate presto!"}},{"id":"q_coscienza","label":"È sveglio? Le risponde?","cost_s":5,"reveals":["coscienza"],"reply":{"calm":"{sc.k}","panic":"{sc.k} Vi prego, presto!"}},{"id":"q_incastro","label":"È rimasto incastrato da qualche parte?","cost_s":5,"reveals":["incastro"],"reply":{"calm":"{sc.x}","panic":"{sc.x} Vi prego, presto!"}},{"id":"a_rassicura","type":"reassure","label":"Non spostatelo, spegnete i macchinari e mandate qualcuno al cancello ad aspettare i soccorsi.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["sanitaria.trauma_caduta","sanitaria.ferita"],"agencies_required":"{sc.ag}","agencies_acceptable":["CC"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","coscienza","incastro"],"hint_debrief":"Negli infortuni sul lavoro va chiesto se la persona è incastrata: in quel caso servono anche i Vigili del fuoco."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
