    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_023', 'Ferita che sanguina', 'sanitaria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_023","title":"Ferita che sanguina","category":"sanitaria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"open":"Pronto, mi sono tagliato con il coltello mentre cucinavo, non smette di sanguinare!","f":"Sul palmo della mano, è profondo.","fd":"Taglio profondo al palmo della mano","s":"Cola tanto, ho già inzuppato due strofinacci.","sd":"Sanguinamento continuo","c":"Stavo tagliando il pane, mi è scivolato.","cd":"Incidente domestico in cucina","event":"sanitaria.ferita","ag":["118"],"acc":[]},{"open":"Pronto! Mio figlio è caduto contro la portafinestra, il vetro si è rotto, ha un taglio alla gamba!","f":"Sulla coscia, lungo così.","fd":"Taglio lungo sulla coscia","s":"Esce a fiotti! A fiotti!","sd":"Sangue a fiotti","c":"Correva in casa ed è finito contro il vetro.","cd":"Caduta contro un vetro","event":"sanitaria.ferita","ag":["118"],"acc":[]},{"open":"Pronto, mio fratello è ferito, gli hanno dato una coltellata!","f":"Al fianco, qui sotto le costole.","fd":"Ferita al fianco","s":"Esce tanto sangue, sta diventando bianco.","sd":"Sanguinamento abbondante, pallore","c":"Un tizio lo ha aggredito sotto casa ed è scappato verso la piazza.","cd":"Aggressione con coltello, l''aggressore è fuggito","event":"sicurezza.aggressione","ag":["118","{location.police}"],"acc":["sanitaria.ferita"]}],"weights":[40,35,25]}},"caller":{"gender":"any","phone_type":"any","panic_start":65,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"{sc.open}","panic":"{sc.open}","hyst":"{sc.open} C''è sangue dappertutto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"ferita":{"label":"Ferita","display":"{sc.fd}"},"sangue":{"label":"Sanguinamento","display":"{sc.sd}"},"dinamica":{"label":"Dinamica","display":"{sc.cd}"}},"nodes":[{"id":"q_dove","label":"Dove siete? Mi serve via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","{location.street}, numero {location.number}."],"panic":"{location.street}… il {location.number}!","hyst":"{location.street}! Il {location.number}! C''è sangue dappertutto!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!","hyst":"{location.street}! Il {location.number_wrong}! C''è sangue dappertutto!"}}},{"id":"q_ferita","label":"Dov''è la ferita? Quanto è grande?","cost_s":5,"reveals":["ferita"],"reply":{"calm":"{sc.f}","panic":"{sc.f} Fate presto!"}},{"id":"q_sangue","label":"Il sangue esce a fiotti o cola? Riuscite a premere?","cost_s":6,"reveals":["sangue"],"reply":{"calm":"{sc.s}","panic":"{sc.s} Fate presto!"}},{"id":"q_come","label":"Com''è successo?","cost_s":6,"reveals":["dinamica"],"reply":{"calm":"{sc.c}","panic":"{sc.c} Vi prego, presto!"}},{"id":"a_premi","type":"reassure","label":"Prema forte sulla ferita con un panno pulito e non lo tolga, anche se si inzuppa: ne aggiunga un altro sopra.","cost_s":6,"panic_delta":-18,"reply":{"calm":"Ok, premo forte.","panic":"Premo! Sto premendo!","hyst":"Premo! Premo! Non si ferma!"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":"{sc.ag}","severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","sangue","dinamica"],"hint_debrief":"Chiedere come è successo non è curiosità: una ferita da aggressione richiede anche le forze dell''ordine."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_024', 'Punto da un insetto, o da una vipera', 'sanitaria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_024","title":"Punto da un insetto, o da una vipera","category":"sanitaria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["colline","montagna"],"floor":[0,0]},"sc":{"choice":[{"open":"Buongiorno, mi ha punto un calabrone sul braccio, è gonfio, volevo sapere cosa fare.","s":"Solo il braccio gonfio e rosso, per il resto sto bene.","sd":"Gonfiore locale al braccio, nessun altro sintomo","a":"Non che io sappia.","ad":"Nessuna allergia nota","event":"sanitaria.reazione_allergica","sev":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600},"adv":"Tolga anelli e orologi da quel braccio e metta del freddo sulla puntura. Se si gonfia il viso o respira male, mi richiami subito.","adv_r":"Va bene, tolgo l''orologio e metto il ghiaccio."},{"open":"Pronto! Mio padre è allergico alle api, l''hanno punto e adesso fa fatica a respirare!","s":"Ha la faccia gonfia, gli si chiude la gola, è pieno di bolle!","sd":"Viso gonfio, gola che si chiude, orticaria","a":"Sì, è allergico, ha la siringa di adrenalina ma l''ha lasciata a casa!","ad":"Allergia nota, adrenalina non disponibile","event":"sanitaria.reazione_allergica","sev":{"optimal_s":120,"acceptable_s":300,"limit_s":600},"adv":"Lo faccia sedere se respira male, sdraiato con le gambe in alto se gli gira la testa. Se qualcuno può portare la sua adrenalina, gliela faccia subito nella coscia.","adv_r":"Sì, lo tengo seduto… mando il vicino a casa a prendere la siringa!"},{"open":"Pronto, sono sul sentiero, mi ha morso un serpente alla caviglia, credo una vipera!","s":"La caviglia si sta gonfiando e diventa scura, mi gira un po'' la testa.","sd":"Caviglia gonfia e scura, capogiri","a":"No, niente allergie.","ad":"Nessuna allergia","event":"sanitaria.soccorso_impervio","sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400},"adv":"Resti ferm{g.o} e sdraiat{g.o}, muova la gamba il meno possibile e tolga scarpe e calze strette. Non incida e non succhi il morso.","adv_r":"Va bene, non mi muovo."}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"{sc.open}","panic":"{sc.open}"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"sintomi":{"label":"Sintomi","display":"{sc.sd}"},"allergie":{"label":"Allergie","display":"{sc.ad}"}},"nodes":[{"id":"q_dove","label":"Dove vi trovate? Via, località o un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, c''è {location.landmark} lì vicino.","panic":"{location.street}! C''è {location.landmark} lì vicino!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicur{g.o}!"}}},{"id":"q_sintomi","label":"Che sintomi ci sono oltre al gonfiore? Respira bene?","cost_s":7,"reveals":["sintomi"],"reply":{"calm":"{sc.s}","panic":"{sc.s} Vi prego, presto!"}},{"id":"q_allergie","label":"Ci sono allergie note? Avete farmaci a portata di mano?","cost_s":5,"reveals":["allergie"],"reply":{"calm":"{sc.a}","panic":"{sc.a} Fate presto, per favore!"}},{"id":"a_rassicura","type":"reassure","label":"{sc.adv}","cost_s":6,"panic_delta":-15,"reply":{"calm":"{sc.adv_r}","panic":"Sì… sì, faccio così."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["sanitaria.reazione_allergica","sanitaria.difficolta_respiratoria","sanitaria.soccorso_impervio"],"agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","sintomi"],"hint_debrief":"Una puntura diventa urgente quando compaiono sintomi lontani dal punto colpito: gonfiore del viso, respiro difficile, capogiri."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_025', 'Mi sento morire', 'sanitaria', 1, 5, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_025","title":"Mi sento morire","category":"sanitaria","phase":1,"difficulty":5,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"s":"Mi formicolano le mani, il cuore batte fortissimo, ho paura di morire… mi è già successo l''anno scorso.","sd":"Formicolio alle mani, batticuore, paura di morire; episodio simile l''anno scorso","r":"Prendo solo la pillola… e sono molto stressata con il lavoro.","rd":"Nessuna malattia nota, forte stress","event":"sanitaria.malore","acc":["sanitaria.difficolta_respiratoria"]},{"s":"Ho un dolore al petto quando respiro e mi manca il fiato… sono appena tornata da un volo di dodici ore.","sd":"Dolore toracico quando respira, fiato corto, dopo un volo di 12 ore","r":"Prendo la pillola… e ho un polpaccio gonfio da ieri, pensavo fosse il viaggio.","rd":"Pillola anticoncezionale, polpaccio gonfio","event":"sanitaria.dolore_toracico","acc":["sanitaria.difficolta_respiratoria"]}],"weights":[60,40]}},"caller":{"gender":"f","phone_type":"any","panic_start":88,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.7,"callback_chance":0.6,"voice":{"age":"adult","style":"breathless"}},"opening":{"calm":"Pronto… non respiro bene, mi sento morire…","panic":"Pronto?! Aiutatemi, non respiro, mi sento morire!","hyst":"Aiuto… non respiro… sto morendo… aiuto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"sintomi":{"label":"Sintomi","display":"{sc.sd}"},"rischi":{"label":"Terapie e precedenti","display":"{sc.rd}"}},"nodes":[{"id":"q_dove","label":"Mi dice dove si trova adesso? Via e numero.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":60,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} {location.number}, {location.zone_name}","reply":{"panic":"In {location.street_wrong}… sì, {location.street_wrong}, il {location.number}!","hyst":"{location.street_wrong}! No… sì! Il {location.number}!"}}},{"id":"q_piano","label":"Che piano? Può aprire la porta?","cost_s":4,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}… sì, apro.","panic":"Al {location.floor_text}… sì, apro. Correte!"},"requires":["q_dove"]},{"id":"q_sintomi","label":"Mi descriva cosa sente, con calma.","cost_s":8,"reveals":["sintomi"],"reply":{"calm":"{sc.s}","panic":"Non lo so! Il petto… le mani… non respiro!"},"error":{"threshold":75,"chance":0.8,"fact":"sintomi","display":"Racconto confuso: «il petto, le mani, non respiro»","reply":{"panic":"Non lo so! Il petto… le mani… non respiro!"}}},{"id":"q_rischi","label":"Prende farmaci? Le è già successo? Ha fatto viaggi di recente?","cost_s":7,"reveals":["rischi"],"reply":{"calm":"{sc.r}","panic":"{sc.r} Fate presto, per favore!"}},{"id":"a_rassicura","type":"reassure","label":"Sono qui con lei. Respiri piano insieme a me: dentro dal naso… fuori dalla bocca.","cost_s":10,"panic_delta":-30,"reply":{"calm":"Ok… dentro… fuori… va un po'' meglio.","panic":"Ok… ci provo… dentro… fuori…"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","sintomi"],"hint_debrief":"Chi è nel panico racconta male: prima si calma, poi si chiede. Un «attacco di panico» dopo un lungo volo, con un polpaccio gonfio, può essere un''embolia."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_054', 'Anziana con febbre e confusa', 'sanitaria', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_054","title":"Anziana con febbre e confusa","category":"sanitaria","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"s":"Ha la febbre a 38 da due giorni, oggi è un po'' più stanca ma mangia e parla normalmente.","sd":"Febbre da due giorni, stanca ma lucida","event":"sanitaria.malore","sev":{"optimal_s":1200,"acceptable_s":2400,"limit_s":4800}},{"s":"Ha 39 e mezzo, stamattina non mi riconosceva e respira veloce, non ha fatto pipì da ieri.","sd":"Febbre alta, confusa, respiro rapido, non urina da ieri","event":"sanitaria.malore","sev":{"optimal_s":420,"acceptable_s":900,"limit_s":1800}}],"weights":[50,50]}},"caller":{"gender":"f","phone_type":"any","panic_start":35,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, mia madre ha la febbre alta e non so se portarla in ospedale.","panic":"Pronto, mia madre sta male, ha la febbre altissima!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"sintomi":{"label":"Sintomi","display":"{sc.sd}"}},"nodes":[{"id":"q_dove","label":"Qual è l''indirizzo della signora? Via e civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_piano","label":"A che piano?","cost_s":4,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, {caller_surname}.","panic":"Al {location.floor_text}, {caller_surname}."},"requires":["q_dove"]},{"id":"q_sintomi","label":"Da quanto ha la febbre? È lucida, respira bene?","cost_s":8,"reveals":["sintomi"],"reply":{"calm":"{sc.s}","panic":"{sc.s}"}},{"id":"a_rassicura","type":"reassure","label":"La tenga al fresco e le dia da bere a piccoli sorsi, se riesce.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["sanitaria.difficolta_respiratoria"],"agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","sintomi"],"hint_debrief":"La febbre da sola raramente è urgente; confusione, respiro rapido e niente urina in un anziano indicano un''infezione grave."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_055', 'Neonato che non respira', 'sanitaria', 1, 7, 70, 3, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_055","title":"Neonato che non respira","category":"sanitaria","phase":1,"difficulty":7,"weight":70,"min_rank":3,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"baby":{"choice":[{"my":"La bambina","o":"a","lo":"la","n":"la piccola","del":"della piccola"},{"my":"Il bambino","o":"o","lo":"lo","n":"il piccolo","del":"del piccolo"}]},"mesi":{"range":[2,9]},"sc":{"choice":[{"open":"Pronto… {baby.my} non respira… l''ho trovat{baby.o} nella culla, non si muove…","open_p":"Pronto! {baby.my} non respira! Non respira! È tutt{baby.o} molle!","open_h":"Aiuto! {baby.my}! Non respira! Aiutatemi, vi prego!","cosa":"Dormiva nella culla dopo la poppata. Sono andat{g.o} a vedere e… era così, non si muoveva.","cosa_d":"Trovat{baby.o} immobile nella culla dopo il sonnellino","risp":"Niente… non si muove, non apre gli occhi.","risp_d":"Non reagisce alla stimolazione","resp":"No… la pancia è ferma… le labbra sono blu…","resp_d":"Non respira, labbra blu","ia":"Metta {baby.n} sulla schiena su un piano rigido, un tavolo o per terra, con la testa dritta, appena un po'' indietro. Ora copra con la sua bocca il naso e la bocca {baby.del} e soffi piano cinque volte, guardando se il petto si alza.","ia_r":"L''ho mess{baby.o} sul tavolo… ho soffiato… uno, due, tre, quattro, cinque… il petto si alza appena…","ib":"Due dita al centro del petto, appena sotto la linea dei capezzoli. Spinga giù di circa quattro centimetri, veloce: trenta volte, contando ad alta voce.","ib_r":"Uno, due, tre… quattro… è così piccol{baby.o}… dieci… undici…","ic":"Ora copra con la sua bocca il naso e la bocca {baby.del} e soffi piano, due volte, guardando se il petto si alza. Poi di nuovo trenta spinte. Non si fermi.","ic_r":"Ho soffiato… il petto si è alzato… riprendo: uno, due, tre…","ic_rr":["Ventotto, ventinove, trenta… soffio… due volte… e ancora…","Continuo! Sento la sirena… continuo!"],"rcp_d":"Il genitore esegue 5 soffi iniziali, poi compressioni con due dita e ventilazioni (30:2), guidato","flag_r":"Non lo so… non vedo niente… continuo a spingere!","event":"sanitaria.arresto_cardiaco","acc":["sanitaria.incosciente","sanitaria.difficolta_respiratoria"],"sev":{"optimal_s":60,"acceptable_s":150,"limit_s":300},"hint":"Un lattante che non respira è un arresto, quasi sempre di origine respiratoria: indirizzo, età e respiro, poi subito le istruzioni. Prima 5 soffi iniziali coprendo naso e bocca, poi 30 compressioni con due dita al centro del petto (circa quattro centimetri) e 2 soffi, senza fermarsi fino all''arrivo dei soccorsi."},{"open":"Pronto… {baby.my} stava prendendo il latte e si è soffocat{baby.o}… non piange, sta diventando viola!","open_p":"Pronto! {baby.my} si è soffocat{baby.o} col latte! È viola! Non respira!","open_h":"Aiuto! È viola! {baby.my} non respira! Fate qualcosa!","cosa":"Stavo dando il biberon, ha tossito una volta… e poi più niente, fa come dei singhiozzi senza aria!","cosa_d":"Soffocamento con il latte durante la poppata","risp":"Ha gli occhi aperti… si agita, ma non piange, non esce la voce!","risp_d":"Occhi aperti, agitat{baby.o}, non riesce a piangere","resp":"Fa dei versi… cerca di respirare ma non entra aria! È viola!","resp_d":"Tentativi di respiro inefficaci, cianotico","ia":"Metta {baby.n} a pancia in giù lungo il suo avambraccio, con la testa più in basso del corpo, sostenendo la mandibola con la mano.","ia_r":"A pancia in giù sul braccio… la testa in basso… sì, così.","ib":"Con il palmo dell''altra mano dia cinque colpi decisi tra le scapole. Conti con me: uno, due, tre, quattro, cinque.","ib_r":"Uno… due… tre… quattro… cinque… (tossisce, poi un pianto fortissimo) Piange! Piange!","ic":"Bene. Giri {baby.n} e {baby.lo} tenga in braccio, un po'' sollevat{baby.o}. Controlli che respiri e pianga bene, e per ora niente da bere.","ic_r":"Piange… respira! È ancora tutt{baby.o} ross{baby.o}, ma respira.","ic_rr":"Respira bene, piange forte. Mi tremano le mani…","rcp_d":"Cinque colpi tra le scapole: ha ripreso a piangere","flag_r":"Sì! Piange, respira! È ancora ross{baby.o}, ma respira!","event":"sanitaria.difficolta_respiratoria","acc":["sanitaria.arresto_cardiaco","sanitaria.incosciente"],"sev":{"optimal_s":60,"acceptable_s":150,"limit_s":360},"hint":"Un lattante soffocato che non riesce a piangere né a tossire va aiutato subito: a pancia in giù sull''avambraccio, testa in basso, cinque colpi tra le scapole e, se non basta, cinque compressioni sul petto con due dita. Mai le spinte sulla pancia nei lattanti."}],"weights":[55,45]}},"caller":{"gender":"any","phone_type":"any","panic_start":85,"ring_patience_s":25,"hold_patience_s":10,"reliability":0.9,"callback_chance":0.9,"voice":{"age":"adult","style":"crying"}},"opening":{"calm":"{sc.open}","panic":"{sc.open_p}","hyst":"{sc.open_h}"},"callback_opening":{"calm":"Pronto, ho chiamato prima per {baby.n}… è caduta la linea!","panic":"Sono io! {baby.my}! È caduta la linea, non lasciatemi da sol{g.o}!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, citofono {caller_surname}"},"eta":{"display":"Lattante di {mesi} mesi"},"evento":{"display":"{sc.cosa_d}"},"coscienza":{"display":"{sc.risp_d}"},"respiro":{"display":"{sc.resp_d}"},"rcp":{"label":"Manovre","display":"{sc.rcp_d}"}},"nodes":[{"id":"q_dove","label":"Mi dica subito l''indirizzo: via e numero.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","Siamo in {location.street}, numero {location.number}."],"panic":"{location.street}… il {location.number}! Presto!","hyst":"{location.street}! Il {location.number}! Correte!"},"error":{"threshold":80,"chance":0.5,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}! Presto!","hyst":"{location.street}! Il {location.number_wrong}! Correte!"}}},{"id":"q_piano","label":"Che piano? Che nome c''è sul citofono?","cost_s":4,"requires":["q_dove"],"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, {caller_surname}.","panic":"{location.floor_text}! {caller_surname}! Lascio aperto!"}},{"id":"q_eta","label":"Quanti mesi ha?","cost_s":3,"reveals":["eta"],"reply":{"calm":"{mesi} mesi.","panic":"{mesi} mesi! Ha {mesi} mesi!"}},{"id":"q_cosa","label":"Cosa è successo? Stava mangiando, dormiva?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.cosa}","panic":"{sc.cosa} Fate presto!"}},{"id":"q_risponde","label":"Tocchi la pianta dei piedi e chiami forte per nome: reagisce?","cost_s":7,"reveals":["coscienza"],"reply":{"calm":"{sc.risp}","panic":"{sc.risp} Oddio!"}},{"id":"q_respiro","label":"Guardi il petto e la pancia per qualche secondo: si alzano e si abbassano?","cost_s":8,"reveals":["respiro"],"reply":{"calm":"{sc.resp}","panic":"{sc.resp} Aiuto!"},"reply_flag":{"flag":"manovre","calm":"{sc.flag_r}","panic":"{sc.flag_r}"}},{"id":"a_calma","type":"reassure","label":"Mi ascolti: la aiuto io, passo per passo. Metta il vivavoce e faccia esattamente quello che le dico.","cost_s":6,"panic_delta":-25,"reply":{"calm":"Sì… sì. Vivavoce. Mi dica.","panic":"Va bene… va bene, la ascolto!","hyst":"Sì… (singhiozza) sì, ci provo…"}},{"id":"i_posizione","type":"reassure","label":"{sc.ia}","cost_s":8,"panic_delta":-5,"requires":["q_respiro","q_cosa"],"hidden_if_flag":"manovre","reply":{"calm":"{sc.ia_r}","panic":"{sc.ia_r} Così va bene?"}},{"id":"i_spingi","type":"reassure","label":"{sc.ib}","cost_s":15,"panic_delta":-10,"requires":["i_posizione"],"hidden_if_flag":"manovre","sets_flag":"manovre","reveals":["rcp"],"reply":{"calm":"{sc.ib_r}","panic":"{sc.ib_r}"}},{"id":"i_continua","type":"reassure","label":"{sc.ic}","cost_s":12,"panic_delta":-8,"requires_flag":"manovre","reply":{"calm":"{sc.ic_r}","panic":"{sc.ic_r}"},"repeat":{"calm":"{sc.ic_rr}","panic":"{sc.ic_rr}"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","respiro","eta"],"hint_debrief":"{sc.hint}"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_060', 'La badante', 'sanitaria', 1, 5, 70, 2, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_060","title":"La badante","category":"sanitaria","phase":1,"difficulty":5,"weight":70,"min_rank":2,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"nonna":{"pool":"surnames"},"eta_p":{"range":[81,94]},"sc":{"choice":[{"open":"Pronto? Pronto… signora sta male! Signora {nonna} non sta bene, è tutta bagnata, sudata… io non so cosa fare!","open_p":"Pronto! Aiuto! Signora sta male, sta male, io non capisco cosa ha!","vago":"Non sta bene… è strana, trema… io non so dire, è strana!","chiaro":"La signora {nonna} è tutta sudata, trema, è confusa e non riesce a stare seduta. È diabetica, dice {caller_first}.","chiaro_p":"Sudata, trema, confusa, non sta seduta. È diabetica, e la signora è molto spaventata.","sint_d":"Sudorazione, tremori, confusione; diabetica","farm":"Sì, sì, insulina! Stamattina fatta insulina… ma lei non ha mangiato colazione, non voleva.","farm_d":"Insulina al mattino, colazione saltata","adv":"Se la signora è sveglia e riesce a deglutire, le dia un bicchiere d''acqua con tre cucchiaini di zucchero, a piccoli sorsi. Se non risponde, non le dia niente.","adv_r":"Gliel''ho tradotto: prepara subito l''acqua con lo zucchero e gliela dà a piccoli sorsi. Dice che la signora riesce a bere.","event":"sanitaria.malore","acc":["sanitaria.incosciente"],"sev":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"hint":"Sudore, tremori e confusione in una persona diabetica che ha fatto l''insulina senza mangiare fanno pensare a un''ipoglicemia. Con chi parla poco l''italiano: calma, frasi brevi, una domanda alla volta, e l''interprete per i dettagli."},{"open":"Pronto? Signora {nonna}… la bocca è storta, non parla bene! Io prima ho visto, adesso è peggio!","open_p":"Pronto! Signora ha la faccia storta! Non parla! Aiuto, presto!","vago":"La faccia… così, storta… e la mano… non so dire! Non va bene!","chiaro":"Da mezz''ora la signora {nonna} ha la bocca storta da un lato, non muove il braccio destro e parla in modo confuso.","chiaro_p":"Bocca storta, braccio destro fermo, parla confusa. Da circa mezz''ora, dice.","sint_d":"Bocca storta, braccio destro immobile, parola confusa da circa 30 minuti","farm":"Pastiglie per pressione… e per sangue, per il cuore. Tutte le mattine io do.","farm_d":"Antipertensivi e anticoagulanti","adv":"Non le dia niente da mangiare né da bere. La tenga semiseduta, non la lasci sola e mi dica subito se cambia qualcosa.","adv_r":"Ha capito: niente cibo né acqua, la tiene semiseduta e resta con lei. Dice che il braccio è sempre fermo.","event":"sanitaria.ictus","acc":["sanitaria.malore"],"sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"hint":"Bocca storta, braccio che non si muove e parole confuse sono segni di ictus: ogni minuto conta. Con chi parla poco l''italiano: calma, frasi brevi, una domanda alla volta, e l''interprete per i dettagli."}],"weights":[50,50]}},"caller":{"gender":"f","first_pool":"names_ro_f","surname_pool":"surnames_ro","phone_type":"any","panic_start":70,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.85,"callback_chance":0.8,"voice":{"age":"adult","accent":"ro"}},"opening":{"calm":"{sc.open}","panic":"{sc.open_p}"},"callback_opening":{"calm":"Pronto? Sono io, {caller_first}… la badante della signora {nonna}. Prima è caduta la linea.","panic":"Pronto! Sono io, badante! Signora sta peggio! Quando venite?"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text}"},"chiamante":{"label":"Chi chiama","display":"{caller_first}, badante della signora {nonna}"},"eta":{"display":"{eta_p} anni"},"sintomi":{"label":"Sintomi","display":"{sc.sint_d}"},"farmaci":{"label":"Terapie","display":"{sc.farm_d}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo della signora: via e numero.","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":"Allora… {location.street}, numero {location.number}. Al {location.floor_text}.","panic":"{location.street}… numero {location.number}! Al {location.floor_text}!"},"reply_flag":{"flag":"interprete","calm":"Dice: {location.street} {location.number}, al {location.floor_text}. Il cognome sul campanello è {nonna}.","panic":"{location.street} {location.number}, {location.floor_text}, campanello {nonna}."},"error":{"unless_flag":"piano","threshold":50,"chance":0.85,"fact":"indirizzo","display":"«{location.street_wrong}»… detto di fretta, incerto","reply":{"calm":"Signora abita… in {location.street_wrong}? No… sì… io agitata, scusi!","panic":"{location.street_wrong}! No… aspetti… io non ricordo, sono agitata!"}}},{"id":"q_chi","label":"Lei chi è? Come si chiama la signora e quanti anni ha?","cost_s":6,"reveals":["chiamante","eta"],"reply":{"calm":"Io sono {caller_first}, badante. Lei è signora {nonna}, ha {eta_p} anni.","panic":"{caller_first}! Io badante! Signora {nonna}, {eta_p} anni!"}},{"id":"q_cosa","label":"Mi descriva cosa vede: come sta la signora adesso?","cost_s":8,"reveals":["sintomi"],"reply":{"calm":"{sc.chiaro}","panic":"{sc.chiaro_p}"},"reply_flag":{"flag":"interprete","calm":"{sc.chiaro}","panic":"{sc.chiaro_p}"},"error":{"unless_flag":"interprete","threshold":0,"chance":1,"fact":"sintomi","display":"«Non sta bene, è strana» (descrizione vaga)","reply":{"calm":"{sc.vago}","panic":"{sc.vago} Aiuto!"}}},{"id":"q_farmaci","label":"Prende medicine? Ha qualche malattia?","cost_s":6,"reveals":["farmaci"],"reply":{"calm":"{sc.farm}","panic":"{sc.farm} Sempre giuste, io controllo!"}},{"id":"a_piano","type":"reassure","label":"{caller_first}, parli piano, una cosa alla volta. La capisco benissimo.","cost_s":6,"panic_delta":-20,"sets_flag":"piano","hidden_if_flag":"piano","reply":{"calm":"Sì… sì. Scusi. Io calma adesso. Piano.","panic":"Sì… piano. Scusi. Io molto paura."}},{"id":"a_interprete","label":"Attivare il servizio di interpretariato (romeno).","cost_s":20,"panic_delta":-10,"sets_flag":"interprete","hidden_if_flag":"interprete","reply":{"calm":"Da… da, mulțumesc!","panic":"Da! Da, vă rog… repede!"},"switch_caller":{"name":"Interprete","gender":"f","voice":{"age":"adult"},"panic_start":25,"reliability":1,"opening":{"calm":"Salve, sono l''interprete di romeno in linea. La signora si chiama {caller_first}, assiste un''anziana. Traduco io: mi dica.","panic":"Interprete di romeno in linea. {caller_first} è molto spaventata, ma la seguo io: mi dica pure."}}},{"id":"a_consiglio","type":"reassure","label":"{sc.adv}","cost_s":8,"panic_delta":-10,"requires":["q_cosa"],"requires_flag":"interprete","reply":{"calm":"{sc.adv_r}","panic":"Glielo traduco subito… ha capito, lo sta facendo."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","sintomi"],"hint_debrief":"{sc.hint}"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_062', 'Bambino chiuso in auto', 'sanitaria', 1, 5, 70, 2, 'mattina,pomeriggio', 0, 0, '{"code":"SAN_062","title":"Bambino chiuso in auto","category":"sanitaria","phase":1,"difficulty":5,"weight":70,"min_rank":2,"time_bands":["mattina","pomeriggio"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"car":{"choice":[{"t":"Una Golf grigia, targata… aspetti… EF 482 TL.","d":"VW Golf grigia, targa EF 482 TL"},{"t":"Una Yaris rossa. La targa è… GB 917 KR.","d":"Toyota Yaris rossa, targa GB 917 KR"},{"t":"Un monovolume bianco, un Touran, targa FT 205 ZN.","d":"VW Touran bianca, targa FT 205 ZN"}]},"kid":{"choice":[{"t":"Un bambino piccolo, avrà due anni. È nel seggiolino dietro, è rosso in faccia e piange forte.","d":"Bambino di circa 2 anni nel seggiolino, rosso in viso","n":"il bambino","o":"o","lo":"lo","gli":"gli","lui":"lui"},{"t":"Una bambina, sarà di un anno e mezzo. Piange, ha i capelli bagnati di sudore.","d":"Bambina di circa 18 mesi, sudata","n":"la bambina","o":"a","lo":"la","gli":"le","lui":"lei"}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":55,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.7,"voice":{"age":"adult"}},"opening":{"calm":["Pronto, c''è un bambino chiuso in una macchina al sole, nel parcheggio. Non c''è nessuno!","Buongiorno, scusi… qui al parcheggio c''è un bimbo piccolo chiuso in auto, da solo, e fa un caldo tremendo."],"panic":"Pronto! C''è un bambino chiuso in macchina! Al sole! Non c''è nessuno!","hyst":"Aiuto! Un bambino chiuso in macchina! Sta male! Venite!"},"callback_opening":{"calm":"Pronto, ho chiamato prima per {kid.n} chius{kid.o} in auto in {location.street}… è caduta la linea.","panic":"Sono io, per {kid.n} chius{kid.o} in macchina! Non arriva nessuno e non piange più!"},"timeline":[{"id":"silenzio","at_s":[90,120],"unless_flag":"fuori","say":{"calm":"Aspetti… ha smesso di piangere. È tutt{kid.o} ross{kid.o}… ha gli occhi chiusi.","panic":"Ha smesso di piangere! Non si muove più! Ha gli occhi chiusi!","hyst":"Non piange più! Non si muove! Faccio qualcosa, ditemi cosa!"},"panic_delta":25,"reveals":["peggioramento"],"sets_flag":"silenzio","interrupt":true}],"facts":{"indirizzo":{"display":"Parcheggio in {location.street}, presso {location.landmark} ({location.zone_name})"},"stato":{"label":"Bambino","display":"{kid.d}"},"auto":{"label":"Veicolo","display":"{car.d}"},"sole":{"label":"Esposizione","display":"Auto al sole da almeno mezz''ora, finestrini chiusi"},"genitori":{"label":"Genitori","display":"Cercati con l''altoparlante del supermercato, nessuna risposta"},"peggioramento":{"label":"Poco dopo","display":"Ha smesso di piangere, occhi chiusi, non si muove"},"estratto":{"label":"Esito","display":"Finestrino rotto: {kid.n} è fuori dall''auto, all''ombra"}},"nodes":[{"id":"q_dove","label":"Dove si trova l''auto? Via, parcheggio, un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["Nel parcheggio in {location.street}, c''è {location.landmark} lì vicino.","In {location.street}, nel parcheggio. Davanti c''è {location.landmark}."],"panic":"{location.street}! Il parcheggio! C''è {location.landmark} lì vicino!"},"error":{"threshold":70,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… cioè, il parcheggio grande, non so il nome della via!"}}},{"id":"q_bambino","label":"Com''è il bambino? Quanti anni ha, piange, si muove, è sudato?","cost_s":7,"reveals":["stato"],"reply":{"calm":"{kid.t}","panic":"{kid.t} Poverin{kid.o}!"},"reply_flag":{"flag":"silenzio","calm":"Non piange più… è tutt{kid.o} ross{kid.o}, ha gli occhi chiusi, non reagisce quando batto sul vetro.","panic":"Non reagisce! Batto sul vetro e non si muove!"}},{"id":"q_sole","label":"L''auto è al sole? Da quanto è lì? I finestrini sono chiusi?","cost_s":5,"reveals":["sole"],"reply":{"calm":"Pieno sole, sì. Era già qui quando sono arrivat{g.o}, almeno mezz''ora fa. Tutto chiuso.","panic":"Pieno sole! Da mezz''ora almeno! Tutto chiuso!"}},{"id":"q_auto","label":"Che auto è? Colore, modello, targa.","cost_s":5,"reveals":["auto"],"reply":{"calm":"{car.t}","panic":"{car.t} Ma che importa, tiratelo fuori!"}},{"id":"q_genitori","label":"Qualcuno sta cercando i genitori? C''è un negozio vicino?","cost_s":6,"reveals":["genitori"],"reply":{"calm":"Sì, la cassiera del supermercato li sta chiamando con l''altoparlante… ancora niente.","panic":"Li stanno chiamando con l''altoparlante! Non viene nessuno!"}},{"id":"a_resta","type":"reassure","label":"Resti accanto all''auto e continui a parlare con {kid.lui} dal finestrino. Arrivano i soccorsi e i Vigili del fuoco per aprire.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene. Faccio le facce dal vetro… si è un po'' calmat{kid.o}.","panic":"Va bene… sono qui, piccol{kid.o}, sono qui!"}},{"id":"i_vetro","type":"reassure","label":"Non aspetti: rompa il finestrino più lontano da {kid.lui} con un oggetto duro, {kid.lo} tiri fuori e {kid.lo} porti all''ombra.","cost_s":12,"panic_delta":-10,"requires_flag":"silenzio","sets_flag":"fuori","hidden_if_flag":"fuori","reveals":["estratto"],"reply":{"calm":"Ok… un signore ha un martello… (silenzio, poi colpi e un vetro che si rompe) L''abbiamo pres{kid.o}! È caldissim{kid.o}, ma respira!","panic":"(silenzio, poi colpi e un vetro che va in pezzi) Fuori! L''ho tirat{kid.o} fuori! Respira, piange piano!"}},{"id":"a_ombra","type":"reassure","label":"Tenga {kid.n} all''ombra, {kid.gli} tolga i vestiti pesanti e {kid.lo} bagni con acqua fresca, non gelata. Se è svegli{kid.o}, {kid.gli} dia da bere a piccoli sorsi.","cost_s":8,"panic_delta":-10,"requires_flag":"fuori","reply":{"calm":"Va bene… acqua fresca… dai, piccol{kid.o}, apri gli occhi… ecco, ha bevuto un po''.","panic":"Acqua fresca… {kid.lo} bagno… {kid.lo} bagno… ha aperto gli occhi! Ha aperto gli occhi!"}}],"truth":{"event_type":"sanitaria.malore","acceptable_event_types":["incendio_tecnico.apertura_porta","incendio_tecnico.soccorso_persona"],"agencies_required":["118","115"],"agencies_acceptable":["PS","CC"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","stato"],"hint_debrief":"Un bambino chiuso in auto al sole peggiora in pochi minuti: servono 118 e Vigili del fuoco insieme. Se smette di piangere e non reagisce, non si aspetta: si rompe il finestrino più lontano da lui e lo si porta all''ombra, a rinfrescarsi."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_065', 'Mal di testa in tutta la famiglia', 'sanitaria', 1, 6, 70, 3, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_065","title":"Mal di testa in tutta la famiglia","category":"sanitaria","phase":1,"difficulty":6,"weight":70,"min_rank":3,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,3]},"sc":{"choice":[{"open":"Pronto… mia sorella è svenuta in bagno, sotto la doccia. E anche a me fa malissimo la testa… sarà la stanchezza.","open_p":"Pronto! Mia sorella è svenuta in bagno! E anche io non sto bene, mi gira la testa!","cosa":"Si stava facendo la doccia, ho sentito un tonfo… l''ho trovata per terra nella doccia. Il bagno è piccolo, senza finestra.","cosa_d":"Trovata a terra nella doccia; bagno piccolo, senza finestra","risp":"Apre gli occhi se la chiamo, ma non dice niente di sensato… respira, sì.","risp_d":"Respira; apre gli occhi alla chiamata, confusa","fonte":"C''è lo scaldabagno a gas lì, sopra la lavatrice. Il tecnico doveva venire a controllarlo da mesi…","fonte_d":"Scaldabagno a gas nel bagno cieco, mai controllato","pers":"Siamo in tre: io, mia sorella e la mamma, che dice che ha la nausea da stamattina. Pensavamo all''influenza…","pers_d":"Tre persone; anche la madre ha nausea da stamattina","out_c":"L''abbiamo portata fuori in due, la mamma e io… adesso è su un fianco, respira.","out_p":"L''abbiamo tirata fuori! Respira! L''ho girata sul fianco!"},{"open":"Pronto, scusi… mio padre è in garage e non mi risponde bene, è strano. E a me gira la testa. È saltata la corrente, abbiamo acceso il generatore.","open_p":"Pronto! Mio padre in garage non sta bene, non risponde! E mi gira la testa!","cosa":"Con il temporale è andata via la luce, lui ha acceso il generatore in garage e ha chiuso la basculante per il rumore. Adesso è seduto per terra.","cosa_d":"Generatore acceso in garage chiuso durante un blackout; padre seduto a terra","risp":"Mi guarda ma è come ubriaco, biascica… respira, sì, ma ha vomitato.","risp_d":"Respira; confuso, biascica, ha vomitato","fonte":"Il generatore a benzina, è ancora acceso, lì in garage. Fa un fumo…","fonte_d":"Generatore a benzina acceso nel garage chiuso","pers":"Io, mio padre e mio figlio di otto anni, che è in camera e dorme. Il garage è sotto casa, comunica con la cucina.","pers_d":"Tre persone; un bambino di 8 anni dorme in casa, garage comunicante con la cucina","out_c":"Ho spento il generatore e l''ho trascinato fuori dalla basculante… è su un fianco, respira.","out_p":"L''ho tirato fuori! È sul fianco, respira! Mio figlio è con me!"},{"open":"Pronto… siamo in taverna, un amico è svenuto e a tutti gira la testa. Forse abbiamo bevuto troppo…","open_p":"Pronto! Un amico è svenuto, e stiamo male tutti, ci gira la testa!","cosa":"Stavamo facendo la grigliata giù in taverna, col braciere, perché fuori piove. Prima uno ha vomitato, adesso un altro è svenuto.","cosa_d":"Braciere acceso in taverna per una grigliata; uno ha vomitato, un altro è svenuto","risp":"Respira… se lo scuoti apre gli occhi, ma si riaddormenta subito.","risp_d":"Respira; apre gli occhi se scosso, poi si riaddormenta","fonte":"Il braciere con la carbonella… è lì in mezzo, acceso. La finestrella è chiusa per il freddo.","fonte_d":"Braciere a carbonella acceso nella taverna chiusa","pers":"Siamo in sei. Due stanno peggio: quello svenuto e una ragazza che ha vomitato. Gli altri hanno mal di testa.","pers_d":"Sei persone; due più gravi, gli altri con mal di testa","out_c":"L''abbiamo portato su in giardino in tre… è su un fianco, respira. Siamo usciti tutti.","out_p":"È fuori! L''abbiamo portato fuori! Respira!"}],"weights":[45,30,25]}},"caller":{"gender":"any","phone_type":"any","panic_start":50,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.85,"callback_chance":0.7,"voice":{"age":"adult"}},"opening":{"calm":"{sc.open}","panic":"{sc.open_p}","hyst":"{sc.open_p} Aiutateci!"},"callback_opening":{"calm":"Pronto, ho chiamato prima… è caduta la linea. Siamo ancora qui, mi gira sempre la testa.","panic":"Pronto! Di nuovo io! Adesso sto male anch''io, non ci vedo bene!"},"timeline":[{"id":"gira","at_s":[70,100],"unless_asked":["a_aria"],"say":{"calm":"Scusi… mi devo sedere, mi gira tutto. Mi viene da vomitare.","panic":"Mi gira tutto… mi siedo… non ce la faccio a stare in piedi!"},"panic_delta":15,"reveals":["chiamante"],"sets_flag":"gira","interrupt":false}],"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"evento":{"display":"{sc.cosa_d}"},"coscienza":{"display":"{sc.risp_d}"},"fonte":{"label":"Possibile fonte","display":"{sc.fonte_d}"},"persone":{"display":"{sc.pers_d}"},"chiamante":{"label":"Chi chiama","display":"Anche chi chiama ha capogiri e nausea"}},"nodes":[{"id":"q_dove","label":"Mi dia l''indirizzo: via, numero e piano.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","Siamo in {location.street}, al {location.number}."],"panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}… mi gira la testa!"}}},{"id":"q_piano","label":"A che piano? Che nome c''è sul campanello?","cost_s":4,"requires":["q_dove"],"reveals":["piano"],"reply":{"calm":"{location.floor_text}, {caller_surname}.","panic":"{location.floor_text}! {caller_surname}!"}},{"id":"q_cosa","label":"Mi racconti cosa è successo e dove vi trovate in casa.","cost_s":8,"reveals":["evento"],"reply":{"calm":"{sc.cosa}","panic":"{sc.cosa} Aiuto!"}},{"id":"q_risponde","label":"La persona svenuta risponde se la chiama? Respira?","cost_s":8,"reveals":["coscienza"],"reply":{"calm":"{sc.risp}","panic":"{sc.risp} Fate presto!"}},{"id":"q_fonte","label":"In quella stanza c''è uno scaldabagno, una stufa, un braciere o un motore acceso?","cost_s":6,"reveals":["fonte"],"reply":{"calm":"{sc.fonte}","panic":"{sc.fonte} Mi gira tutto!"}},{"id":"q_persone","label":"Quante persone ci sono? Qualcun altro ha mal di testa o nausea?","cost_s":6,"reveals":["persone"],"reply":{"calm":"{sc.pers}","panic":"{sc.pers} Stiamo male tutti!"}},{"id":"a_aria","type":"reassure","label":"Aprite subito porte e finestre e uscite tutti all''aria aperta. Spegnete la fonte solo se è a portata di mano, senza fermarvi a cercare la causa.","cost_s":8,"panic_delta":-15,"requires":["q_fonte"],"sets_flag":"fuori","reply":{"calm":"Apro tutto… usciamo. Adesso siamo fuori, in cortile.","panic":"Apro! Usciamo! …Siamo fuori!"}},{"id":"a_svenuto","type":"reassure","label":"Se riuscite a portare fuori la persona svenuta in pochi secondi, fatelo. Altrimenti lasciatela ai soccorritori e non rientrate. Se è fuori e respira, mettetela su un fianco.","cost_s":8,"panic_delta":-10,"requires":["q_risponde","q_fonte"],"reply":{"calm":"{sc.out_c}","panic":"{sc.out_p}"}}],"truth":{"event_type":"sanitaria.intossicazione","acceptable_event_types":["sanitaria.malore","sanitaria.incosciente"],"agencies_required":["118","115"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","fonte"],"hint_debrief":"Uno svenuto e altre persone con mal di testa e nausea nello stesso ambiente chiuso, con una combustione accesa: è monossido di carbonio, che non ha odore. Servono 118 e Vigili del fuoco, e la prima istruzione è aprire tutto e uscire all''aria aperta, senza che i soccorritori improvvisati restino dentro."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_006', 'Ladri in casa', 'sicurezza', 1, 3, 90, 1, 'mattina,sera,notte', 0, 0, '{"code":"SIC_006","title":"Ladri in casa","category":"sicurezza","phase":1,"difficulty":3,"weight":90,"min_rank":1,"time_bands":["mattina","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","colline"],"floor":[0,2]},"intruders":{"choice":[{"text":"(sussurra) Almeno due… li sento parlare. Non so se sono armati.","display":"Almeno due persone, armi non viste"},{"text":"(sussurra) Uno solo, credo… ha rotto il vetro della portafinestra.","display":"Una persona, entrata rompendo la portafinestra"}]},"car":{"choice":[{"text":"(sussurra, agitata) C''è una macchina scura col motore acceso davanti al cancello… non vedo la targa.","display":"Auto scura col motore acceso davanti al cancello"},{"text":"(sussurra) Non vedo niente… è tutto buio fuori.","display":"Nessun veicolo visibile"}]}},"caller":{"gender":"f","phone_type":"mobile","panic_start":60,"ring_patience_s":30,"hold_patience_s":15,"reliability":0.9,"callback_chance":0.9,"voice":{"age":"adult","style":"whisper"}},"opening":{"calm":"(sussurra) Pronto… ci sono dei ladri in casa. Li sento al piano di sotto.","panic":"(sussurra, con il fiato corto) Pronto… sono in casa… sono in casa, li sento!","hyst":"(sussurra, piange) Sono qui… sono qui sotto… mi trovano… aiuto…"},"callback_opening":{"calm":"(sussurra) Sono io… ho chiamato prima, è caduta la linea. Sono ancora in camera.","panic":"(sussurra) Sono io… vi prego… sono ancora qui, li sento!"},"timeline":[{"id":"scale","at_s":[45,75],"say":{"calm":"(sussurra) Aspetti… stanno salendo le scale. Li sento sui gradini.","panic":"(sussurra) Stanno salendo… stanno salendo le scale…","hyst":"(sussurra, piange) Sono sulle scale… vengono su… vengono qui…"},"panic_delta":20,"reveals":["movimenti"],"sets_flag":"salgono","interrupt":true}],"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"posizione":{"label":"Dove si trova la chiamante","display":"Chiusa a chiave in camera da letto, al piano di sopra"},"sospetti":{"display":"{intruders.display}"},"veicoli":{"display":"{car.display}"},"movimenti":{"label":"Movimenti","display":"Sente qualcuno salire le scale verso il piano di sopra"}},"nodes":[{"id":"q_dove","label":"Mi sussurri l''indirizzo: via e numero.","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":["(sussurra) {location.street} {location.number}.","(sussurra) {location.street}… numero {location.number}."],"panic":"(sussurra) {location.street}… {location.number}…"},"error":{"threshold":70,"chance":0.45,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"(sussurra) {location.street}… {location.number_wrong}…"}}},{"id":"q_posizione","label":"Lei dove si trova adesso? È al sicuro?","cost_s":6,"reveals":["posizione"],"reply":{"calm":"(sussurra) In camera, al piano di sopra. Ho chiuso la porta a chiave.","panic":"(sussurra) In camera… ho chiuso a chiave… ho paura."},"reply_flag":{"flag":"salgono","calm":"(sussurra) In camera, chiusa a chiave… ma loro sono qui fuori, sul pianerottolo.","panic":"(sussurra) In camera… sono qui fuori… sono qui fuori dalla porta…"}},{"id":"q_quanti","label":"Quante persone sente? Ha visto armi?","cost_s":6,"reveals":["sospetti"],"reply":{"calm":"{intruders.text}","panic":"{intruders.text}"}},{"id":"q_auto","label":"Riesce a guardare dalla finestra senza farsi vedere? C''è un''auto fuori?","cost_s":12,"panic_delta":15,"reveals":["veicoli"],"reply":{"calm":"{car.text}","panic":"{car.text}"}},{"id":"a_silenzio","type":"reassure","label":"Resti dov''è, in silenzio, e non apra a nessuno. Io resto in linea con lei.","cost_s":6,"panic_delta":-18,"reply":{"calm":"(sussurra) Va bene… resto qui.","panic":"(sussurra) Sì… sì… non se ne vada, la prego."}}],"truth":{"event_type":"sicurezza.furto_in_corso","agencies_required":["{location.police}"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","sospetti"],"hint_debrief":"Chi sussurra non può reggere lunghe attese: metterla in attesa o chiederle di muoversi aumenta il rischio. Competenza PS o CC secondo la zona."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_011', 'Lite violenta sentita dal vicino', 'sicurezza', 1, 5, 80, 1, 'sera,notte,pomeriggio', 0, 0, '{"code":"SIC_011","title":"Lite violenta sentita dal vicino","category":"sicurezza","phase":1,"difficulty":5,"weight":80,"min_rank":1,"time_bands":["sera","notte","pomeriggio"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[1,4]},"fight":{"choice":[{"text":"Un uomo che grida, una donna che piange… e prima dei colpi, come mobili che cadono.","display":"Uomo che urla, donna che piange, rumori di colpi","agencies":["{location.police}"],"event":"sicurezza.violenza_domestica"},{"text":"Adesso ho sentito lei gridare «basta, mi fai male»… e poi più niente. Silenzio.","display":"Una donna ha gridato «mi fai male», poi silenzio","agencies":["{location.police}","118"],"event":"sicurezza.violenza_domestica"}]},"weapons":{"choice":[{"text":"Non lo so… lui va a caccia, ha dei fucili, me l''aveva detto.","display":"Possibili fucili da caccia in casa"},{"text":"No, non credo.","display":"Nessuna arma nota"}],"weights":[35,65]}},"caller":{"gender":"m","phone_type":"any","panic_start":35,"ring_patience_s":45,"hold_patience_s":45,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, non so se faccio bene a chiamare… dall''appartamento accanto sento urlare da mezz''ora.","panic":"Pronto, scusate… qui di fianco stanno urlando, sento dei colpi, non so cosa fare."},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text}: appartamento accanto al chiamante"},"evento":{"display":"{fight.display}"},"persone":{"display":"Coppia con una bambina piccola, probabilmente in casa"},"pericoli":{"display":"{weapons.display}"},"reazione":{"label":"Tentativo del chiamante","display":"Il chiamante ha bussato: l''uomo ha reagito con rabbia"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo e il piano.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}, al {location.floor_text}. È l''appartamento di fianco al mio.","panic":"{location.street} {location.number}, {location.floor_text}."}},{"id":"q_cosa","label":"Cosa sente esattamente?","cost_s":7,"reveals":["evento"],"reply":{"calm":"{fight.text}","panic":"{fight.text}"}},{"id":"q_bambini","label":"Sa chi vive in quell''appartamento? Ci sono bambini?","cost_s":6,"reveals":["persone"],"reply":{"calm":"Una coppia, hanno una bambina piccola. Credo sia in casa.","panic":"Una coppia… con una bambina!"}},{"id":"q_armi","label":"Sa se in casa ci sono armi?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{weapons.text}","panic":"{weapons.text}"}},{"id":"q_bussa","label":"Provi a bussare e a chiedere se va tutto bene.","cost_s":20,"panic_delta":25,"reveals":["reazione"],"reply":{"calm":"Ho bussato… hanno smesso, poi lui ha urlato di farmi gli affari miei. Ho paura adesso.","panic":"Ho bussato… lui mi ha urlato contro! Ho paura!"}},{"id":"a_resta","type":"reassure","label":"Resti in casa sua, chiuda la porta e non intervenga. Arrivano le forze dell''ordine.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene, resto qui.","panic":"Va bene… va bene."}}],"truth":{"event_type":"{fight.event}","acceptable_event_types":["sicurezza.lite_violenza","sicurezza.aggressione"],"agencies_required":["{fight.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","evento"],"hint_debrief":"Mai mandare il chiamante a verificare di persona: si mette in pericolo e si perde tempo. Un grido di dolore seguito dal silenzio richiede anche il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_015', '«Vorrei ordinare una pizza»', 'sicurezza', 1, 8, 55, 3, 'sera,notte', 0, 0, '{"code":"SIC_015","title":"«Vorrei ordinare una pizza»","category":"sicurezza","phase":1,"difficulty":8,"weight":55,"min_rank":3,"time_bands":["sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro","colline"],"floor":[0,3]},"injury":{"choice":[{"text":"Sì… un po''. E anche due bibite, grazie.","display":"Conferma di essere ferita","agencies":["{location.police}","118"]},{"text":"No, per ora no.","display":"Dice di non essere ferita","agencies":["{location.police}"]}]},"weapon":{"choice":[{"text":"Sì… con le olive, grazie.","display":"Presenza di un''arma («con le olive»)"},{"text":"No, senza olive.","display":"Nessuna arma («senza olive»)"}],"weights":[40,60]}},"caller":{"gender":"f","phone_type":"mobile","panic_start":75,"ring_patience_s":30,"hold_patience_s":8,"reliability":1,"callback_chance":0.2,"voice":{"age":"adult","style":"whisper"}},"opening":{"calm":"Buonasera… vorrei ordinare una pizza. Una margherita, grande.","panic":"Buonasera… vorrei… ordinare una pizza. Margherita. Grande."},"facts":{"evento":{"display":"Conferma di essere in pericolo, parla come se ordinasse una pizza"},"sospetti":{"display":"Qualcuno con lei le sta facendo del male"},"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text} (dato «per la consegna»)"},"ferite":{"display":"{injury.display}"},"pericoli":{"display":"{weapon.display}"}},"nodes":[{"id":"q_errore","label":"Signora, ha chiamato il 112, il numero di emergenza. Ha sbagliato numero?","cost_s":6,"ends_call":true,"reply":{"calm":"(una lunga pausa) …sì. Scusi. (riattacca)","panic":"(silenzio) …sì, scusi. (riattacca)"}},{"id":"q_pericolo","label":"Ho capito. È in pericolo? Può rispondermi solo sì o no.","cost_s":6,"panic_delta":-10,"reveals":["evento"],"reply":{"calm":"Sì. Esatto, grande.","panic":"Sì… esatto. Grande."}},{"id":"q_presente","label":"C''è qualcuno lì con lei che le sta facendo del male?","cost_s":5,"requires":["q_pericolo"],"reveals":["sospetti"],"reply":{"calm":"Sì, esatto.","panic":"Sì."}},{"id":"q_indirizzo","label":"Mi dica l''indirizzo come se fosse per la consegna.","cost_s":6,"requires":["q_pericolo"],"reveals":["indirizzo"],"reply":{"calm":"Per la consegna… {location.street} {location.number}, {location.floor_text}.","panic":"{location.street}… {location.number}… {location.floor_text}."}},{"id":"q_ferita","label":"È ferita? Risponda sì o no.","cost_s":5,"requires":["q_pericolo"],"reveals":["ferite"],"reply":{"calm":"{injury.text}","panic":"{injury.text}"}},{"id":"q_armi","label":"Lui ha un''arma? Se sì, mi dica «con le olive».","cost_s":5,"requires":["q_pericolo"],"reveals":["pericoli"],"reply":{"calm":"{weapon.text}","panic":"{weapon.text}"}},{"id":"a_resta","type":"reassure","label":"Stiamo arrivando senza sirene. Se non può parlare, lasci il telefono acceso.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Perfetto. Grazie.","panic":"…grazie."}}],"truth":{"event_type":"sicurezza.violenza_domestica","acceptable_event_types":["sicurezza.lite_violenza","sicurezza.aggressione"],"agencies_required":["{injury.agencies}"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["evento","indirizzo","sospetti"],"hint_debrief":"Chi «ordina una pizza» al 112 spesso non può parlare liberamente. Domande chiuse, sì o no, e l''indirizzo chiesto «per la consegna». Dirle che ha sbagliato numero la fa riattaccare."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_037', 'Rapina appena avvenuta', 'sicurezza', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_037","title":"Rapina appena avvenuta","category":"sicurezza","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,0]},"sc":{"choice":[{"w":"Nella tabaccheria, un uomo con un coltello si è fatto dare l''incasso ed è scappato a piedi.","wd":"Rapina in tabaccheria con coltello, fuga a piedi","d":"Alto, giubbotto nero, cappuccio. È corso verso {location.landmark}.","dd":"Uomo alto, giubbotto nero con cappuccio, fuggito a piedi verso {location.landmark}","f":"No, nessuno è ferito, siamo solo spaventati.","fd":"Nessun ferito","ag":["{location.police}"]},{"w":"In farmacia! Aveva una pistola! È scappato su uno scooter!","wd":"Rapina in farmacia con pistola, fuga in scooter","d":"Casco integrale nero, scooter grigio, è andato verso {location.landmark}.","dd":"Casco integrale nero, scooter grigio, verso {location.landmark}","f":"La farmacista trema tutta, dice che le manca l''aria.","fd":"Farmacista in stato di shock","ag":["{location.police}"]},{"w":"Hanno scippato una signora anziana! L''hanno spinta per terra per prenderle la borsa!","wd":"Scippo con anziana spinta a terra","d":"Un ragazzo magro, felpa rossa, scappato di corsa verso {location.landmark}.","dd":"Ragazzo magro, felpa rossa, fuggito verso {location.landmark}","f":"Sanguina dalla testa, è seduta per terra.","fd":"Anziana ferita alla testa","ag":["{location.police}","118"]}]}},"caller":{"gender":"any","phone_type":"any","panic_start":60,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, c''è stata una rapina, adesso!","panic":"Pronto! Una rapina! È appena scappato!","hyst":"Una rapina! Mi ha puntato… è scappato! Aiuto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"evento":{"display":"{sc.wd}"},"descrizione":{"label":"Descrizione e fuga","display":"{sc.dd}"},"feriti":{"display":"{sc.fd}"},"quando":{"label":"Quando","display":"Pochi istanti fa, non è più sul posto"}},"nodes":[{"id":"q_dove","label":"Dov''è il negozio? Via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","In {location.street}, al numero {location.number}."],"panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} {location.number}, {location.zone_name}","reply":{"panic":"In {location.street_wrong}… sì, {location.street_wrong}, il {location.number}!","hyst":"{location.street_wrong}! No… sì! Il {location.number}!"}}},{"id":"q_cosa","label":"Cosa è successo esattamente?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Ho paura!"}},{"id":"q_quando","label":"Quando è successo? È ancora lì?","cost_s":4,"reveals":["quando"],"reply":{"calm":"Un minuto fa. È scappato subito.","panic":"Adesso! Un minuto fa! È scappato!"}},{"id":"q_descr","label":"Mi descriva la persona e da che parte è andata.","cost_s":7,"reveals":["descrizione"],"reply":{"calm":"{sc.d}","panic":"{sc.d} Ho paura!"}},{"id":"q_feriti","label":"C''è qualcuno ferito?","cost_s":4,"reveals":["feriti"],"reply":{"calm":"{sc.f}","panic":"{sc.f} Fate presto, vi prego!"}},{"id":"a_rassicura","type":"reassure","label":"Non lo segua. Chiuda la porta del negozio, non tocchi nulla e resti lì: arrivano le forze dell''ordine.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sicurezza.rapina","acceptable_event_types":["sicurezza.aggressione","sicurezza.furto_in_corso"],"agencies_required":"{sc.ag}","agencies_acceptable":["118"],"severity":{"optimal_s":120,"acceptable_s":300,"limit_s":900},"critical_facts":["indirizzo","descrizione"],"hint_debrief":"Dopo una rapina la descrizione e la direzione di fuga valgono oro: vanno raccolte subito, finché il ricordo è fresco."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_038', 'Persona sospetta', 'sicurezza', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_038","title":"Persona sospetta","category":"sicurezza","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro","colline"],"floor":[0,0]},"sc":{"choice":[{"w":"Un uomo gira nel parcheggio e prova ad aprire le portiere delle auto, una dopo l''altra.","wd":"Uomo che prova le portiere delle auto in sosta","event":"sicurezza.persona_sospetta","sev":{"optimal_s":300,"acceptable_s":600,"limit_s":1800}},{"w":"C''è un furgone bianco fermo da ore davanti alle ville, due uomini fotografano i cancelli.","wd":"Furgone fermo da ore, due uomini fotografano le case","event":"sicurezza.persona_sospetta","sev":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600}},{"w":"Un ragazzo sta forzando il portone del palazzo di fronte con un cacciavite, adesso!","wd":"Ragazzo che forza un portone con un cacciavite","event":"sicurezza.furto_in_corso","sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900}}]}},"caller":{"gender":"any","phone_type":"any","panic_start":30,"ring_patience_s":35,"hold_patience_s":30,"reliability":1,"callback_chance":0.5},"opening":{"calm":"Buonasera, vedo una persona che si comporta in modo strano qui sotto.","panic":"Pronto, c''è uno che sta facendo qualcosa di strano qui fuori!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"comportamento":{"label":"Cosa sta facendo","display":"{sc.wd}"},"descrizione":{"label":"Descrizione","display":"Uomo sui trent''anni, giacca scura, cappello"},"veicoli":{"display":"Nessun veicolo visto, a parte quelli in sosta"}},"nodes":[{"id":"q_dove","label":"Dove si trova? Via e punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, proprio davanti c''è {location.landmark}.","panic":"{location.street}!"}},{"id":"q_cosa","label":"Cosa sta facendo esattamente?","cost_s":6,"reveals":["comportamento"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_descr","label":"Come è vestito? Com''è fatto?","cost_s":6,"reveals":["descrizione"],"reply":{"calm":"Sui trent''anni, giacca scura, un cappello.","panic":"Sui trent''anni, giacca scura, un cappello."}},{"id":"q_veicoli","label":"Ha visto con che mezzo è arrivato?","cost_s":5,"reveals":["veicoli"],"reply":{"calm":"No, non l''ho visto arrivare.","panic":"No, non l''ho visto arrivare."}},{"id":"a_rassicura","type":"reassure","label":"Non intervenga e non si faccia vedere: continui a osservarlo da dove si trova.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["sicurezza.persona_sospetta","sicurezza.furto_in_corso"],"agencies_required":["{location.police}"],"severity":"{sc.sev}","critical_facts":["indirizzo","comportamento"],"hint_debrief":"Una persona sospetta è di competenza delle forze dell''ordine, con urgenza diversa: chi sta forzando un portone adesso è un furto in corso."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_039', 'Rissa', 'sicurezza', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"SIC_039","title":"Rissa","category":"sicurezza","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.5,"max":2,"delay_s":[20,120],"near_twin_chance":0},"witness_opening":{"calm":"Buonasera, in {location.street} c''è gente che si picchia. Lì vicino c''è {location.landmark}.","panic":"Pronto, una rissa in {location.street}, presto!"},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,0]},"sc":{"choice":[{"w":"Davanti al bar si stanno picchiando in sei o sette, volano bottiglie!","wd":"Rissa tra 6-7 persone, lancio di bottiglie","f":"Non lo so, è un caos, uno ha il viso pieno di sangue.","fd":"Almeno un ferito al volto","a":"Bottiglie rotte, non ho visto coltelli.","ad":"Bottiglie, coltelli non visti","ag":["{location.police}","118"],"event":"sicurezza.lite_violenza"},{"w":"C''è stata una rissa, adesso sono scappati quasi tutti… un ragazzo è rimasto a terra.","wd":"Rissa terminata, un ragazzo a terra","f":"Ha una ferita alla testa, risponde ma è confuso.","fd":"Ragazzo con ferita alla testa, confuso","a":"Uno aveva un bastone, credo.","ad":"Possibile bastone","ag":["{location.police}","118"],"event":"sicurezza.aggressione"},{"w":"Due automobilisti litigano dopo un tamponamento, uno ha preso una mazza da baseball dal bagagliaio!","wd":"Lite tra automobilisti, uno armato di mazza","f":"Non ancora, ma sta minacciando l''altro.","fd":"Nessun ferito per ora","a":"Una mazza da baseball.","ad":"Mazza da baseball","ag":["{location.police}"],"event":"sicurezza.lite_violenza"}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":60,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, qui c''è una rissa, stanno litigando pesante.","panic":"Pronto! Si stanno picchiando! Venite!","hyst":"Si stanno ammazzando di botte! Venite, presto!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"evento":{"display":"{sc.wd}"},"feriti":{"display":"{sc.fd}"},"pericoli":{"display":"{sc.ad}"}},"nodes":[{"id":"q_dove","label":"Dove si trova? Via e locale o punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, proprio davanti c''è {location.landmark}.","panic":"{location.street}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicur{g.o}!"}}},{"id":"q_cosa","label":"Quante persone sono coinvolte? Cosa sta succedendo?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Venite, presto!"}},{"id":"q_feriti","label":"Ci sono feriti?","cost_s":5,"reveals":["feriti"],"reply":{"calm":"{sc.f}","panic":"{sc.f} Ho paura!"}},{"id":"q_armi","label":"Ha visto armi, coltelli, oggetti?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{sc.a}","panic":"{sc.a} Venite, presto!"}},{"id":"a_rassicura","type":"reassure","label":"Resti a distanza di sicurezza e non intervenga: le forze dell''ordine stanno arrivando.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["sicurezza.lite_violenza","sicurezza.aggressione"],"agencies_required":"{sc.ag}","agencies_acceptable":["118"],"severity":{"optimal_s":120,"acceptable_s":300,"limit_s":900},"critical_facts":["indirizzo","feriti"],"hint_debrief":"In una rissa i feriti decidono se serve il 118, le armi quanto è pericoloso intervenire. Spesso chiamano più testimoni: vanno accorpati."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_040', 'Persona scomparsa', 'sicurezza', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_040","title":"Persona scomparsa","category":"sicurezza","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro","colline"],"floor":[0,0]},"sc":{"choice":[{"w":"Mio figlio di sei anni! Era qui al parco un attimo fa, mi sono girata e non c''è più!","wd":"Bambino di 6 anni scomparso al parco da pochi minuti","d":"Maglietta gialla, pantaloncini blu, capelli castani corti.","dd":"Maglietta gialla, pantaloncini blu, capelli castani corti","t":"Dieci minuti, forse meno.","td":"Circa 10 minuti fa","sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900}},{"w":"Mio padre ha l''Alzheimer, stanotte è uscito di casa e non lo troviamo!","wd":"Anziano con demenza uscito di casa di notte","d":"Ottant''anni, in pigiama e pantofole, alto, magro.","dd":"80 anni, pigiama e pantofole, alto e magro","t":"L''ho visto a mezzanotte, adesso sono le quattro.","td":"Da circa 4 ore","sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400}},{"w":"Mia figlia di sedici anni non è tornata da scuola e ha il telefono spento.","wd":"Ragazza di 16 anni non rientrata, telefono spento","d":"Zaino viola, giubbotto bianco, capelli lunghi neri.","dd":"Zaino viola, giubbotto bianco, capelli lunghi neri","t":"Doveva essere a casa alle due, sono le sette.","td":"Attesa da 5 ore","sev":{"optimal_s":1200,"acceptable_s":2400,"limit_s":4800}}]}},"caller":{"gender":"any","phone_type":"any","panic_start":70,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.9,"voice":{"age":"adult","style":"crying"}},"opening":{"calm":"Pronto, non trovo più una persona della mia famiglia…","panic":"Pronto! Non lo trovo più! È sparito!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"evento":{"display":"{sc.wd}"},"descrizione":{"label":"Descrizione","display":"{sc.dd}"},"quando":{"label":"Visto l''ultima volta","display":"{sc.td}"}},"nodes":[{"id":"q_dove","label":"Dove l''ha visto per l''ultima volta?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, c''è {location.landmark} lì vicino.","panic":"{location.street}! C''è {location.landmark} lì vicino!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicur{g.o}!"}}},{"id":"q_chi","label":"Chi è la persona scomparsa?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Venite, presto!"}},{"id":"q_descr","label":"Mi descriva com''è vestito e com''è fatto.","cost_s":7,"reveals":["descrizione"],"reply":{"calm":"{sc.d}","panic":"{sc.d} Fate presto, vi prego!"}},{"id":"q_quando","label":"Quando l''ha visto l''ultima volta?","cost_s":4,"reveals":["quando"],"reply":{"calm":"{sc.t}","panic":"{sc.t} Fate presto, vi prego!"}},{"id":"a_rassicura","type":"reassure","label":"Resti dove si trova, nel punto in cui l''ha visto: se torna, deve trovare qualcuno lì.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sicurezza.persona_scomparsa","agencies_required":["{location.police}"],"agencies_acceptable":["115","118"],"severity":"{sc.sev}","critical_facts":["indirizzo","descrizione","quando"],"hint_debrief":"Per una scomparsa contano descrizione, luogo e ora dell''ultimo avvistamento. Bambini piccoli e persone con demenza sono le più urgenti."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_041', 'Truffa agli anziani', 'sicurezza', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_041","title":"Truffa agli anziani","category":"sicurezza","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,4]},"sc":{"choice":[{"w":"(sottovoce) Ci sono due tecnici del gas in casa, vogliono che metta i gioielli nel frigorifero perché dicono che il gas li rovina…","wd":"Due falsi tecnici del gas in casa, in corso","s":"Sono ancora qui, in cucina.","sd":"I truffatori sono in casa ora","sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900}},{"w":"Mi ha chiamato un carabiniere, dice che mio nipote ha fatto un incidente e che serve una cauzione. Sta arrivando un corriere a prendere i soldi.","wd":"Falsa telefonata per un incidente del nipote, corriere in arrivo per i soldi","s":"Il corriere dovrebbe arrivare tra dieci minuti.","sd":"Corriere atteso a minuti","sev":{"optimal_s":300,"acceptable_s":600,"limit_s":1200}},{"w":"Chiamo per mio padre: un''ora fa ha dato cinquemila euro a un finto avvocato che è venuto a casa.","wd":"Truffa già avvenuta un''ora fa, finto avvocato","s":"No, se n''è andato da un pezzo.","sd":"Truffatore già andato via","sev":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600}}]}},"caller":{"gender":"f","phone_type":"any","panic_start":40,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.9,"callback_chance":0.6,"voice":{"age":"elderly"}},"opening":{"calm":"Buongiorno… scusi, forse è una sciocchezza, ma volevo chiedere una cosa.","panic":"Pronto… non so se sto facendo bene a chiamare…"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"evento":{"display":"{sc.wd}"},"stato":{"label":"Situazione attuale","display":"{sc.sd}"}},"nodes":[{"id":"q_dove","label":"Mi dice il suo indirizzo, signora? Via e numero.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} {location.number}, {location.zone_name}","reply":{"panic":"In {location.street_wrong}… sì, {location.street_wrong}, il {location.number}!","hyst":"{location.street_wrong}! No… sì! Il {location.number}!"}}},{"id":"q_cosa","label":"Mi racconti cosa sta succedendo.","cost_s":8,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_ora","label":"Le persone sono ancora lì, o devono arrivare?","cost_s":5,"reveals":["stato"],"reply":{"calm":"{sc.s}","panic":"{sc.s} Ho paura!"}},{"id":"a_avviso","type":"reassure","label":"Nessun tecnico, avvocato o carabiniere chiede soldi o gioielli a casa. Non consegni nulla e non apra: arrivano le forze dell''ordine.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Oh Signore… va bene, non apro.","panic":"Va bene… va bene, non do niente."}}],"truth":{"event_type":"sicurezza.truffa","agencies_required":["{location.police}"],"severity":"{sc.sev}","critical_facts":["indirizzo","stato"],"hint_debrief":"Chi chiama per una truffa spesso esordisce scusandosi: va ascoltato. Se i truffatori sono in casa o in arrivo, è un intervento urgente."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_042', 'Ex compagno sotto casa', 'sicurezza', 1, 5, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_042","title":"Ex compagno sotto casa","category":"sicurezza","phase":1,"difficulty":5,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[1,4]},"sc":{"choice":[{"w":"Il mio ex è sotto casa, suona in continuazione e urla. Ha un divieto di avvicinamento!","wd":"Ex compagno sotto casa nonostante un divieto di avvicinamento","d":"È giù in strada, vicino al portone.","dd":"In strada davanti al portone","tl_c":"Ha smesso di suonare… adesso prende a spallate il portone! Si sente fino a qui!","tl_p":"Sta prendendo a spallate il portone! Lo sfonda! Lo sfonda!","tld":"Sta cercando di forzare il portone","tl_r":"È giù al portone, lo sta prendendo a spallate!"},{"w":"Un uomo mi segue da tre giorni… adesso è qui davanti al portone e mi guarda.","wd":"Uomo che la segue da tre giorni, ora davanti al portone","d":"È fermo davanti al portone.","dd":"Davanti al portone","tl_c":"Adesso è entrato nell''androne… qualcuno gli ha aperto il portone!","tl_p":"È entrato! Qualcuno gli ha aperto, è nell''androne! Sale!","tld":"È entrato nell''androne del palazzo","tl_r":"È dentro il palazzo, sta salendo le scale!"},{"w":"Il mio ex è salito sul pianerottolo e prende a calci la porta! Sto chiusa in bagno!","wd":"Ex compagno sul pianerottolo che prende a calci la porta","d":"È qui fuori! Sulla porta!","dd":"Sul pianerottolo, contro la porta di casa","tl_c":"(silenzio, poi un colpo fortissimo) Ha rotto la porta… è in casa! Sono chiusa in bagno!","tl_p":"(silenzio, poi un colpo e un urlo) È dentro! Ha sfondato la porta! È in casa!","tld":"Ha sfondato la porta: è in casa, lei chiusa in bagno","tl_r":"È dentro casa… è davanti alla porta del bagno!"}]}},"caller":{"gender":"f","phone_type":"mobile","panic_start":72,"ring_patience_s":35,"hold_patience_s":12,"reliability":0.95,"callback_chance":0.9,"voice":{"age":"adult"}},"opening":{"calm":"Pronto… c''è una persona che mi sta perseguitando, adesso è qui.","panic":"Pronto! È qui! È tornato, ho paura!","hyst":"(piange) È qui! È qui sotto! Aiuto!"},"callback_opening":{"calm":"(sottovoce) Sono io, ho chiamato prima… è ancora qui, non se ne va.","panic":"Sono io! È caduta la linea! È ancora qui, vi prego!"},"timeline":[{"id":"cede","at_s":[50,80],"say":{"calm":"{sc.tl_c}","panic":"{sc.tl_p}","hyst":"{sc.tl_p} Aiuto!"},"panic_delta":20,"reveals":["sviluppi"],"sets_flag":"cede","interrupt":true}],"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text}"},"evento":{"display":"{sc.wd}"},"posizione":{"label":"Dove si trova lui","display":"{sc.dd}"},"pericoli":{"display":"Non sa se sia armato"},"sviluppi":{"label":"Cosa è cambiato","display":"{sc.tld}"}},"nodes":[{"id":"q_dove","label":"Mi dica dove si trova: via e numero del portone.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","{location.street}, il numero {location.number}. Al {location.floor_text}."],"panic":"{location.street}… il {location.number}!","hyst":"{location.street}… il… il {location.number}! Venite!"},"error":{"threshold":70,"chance":0.45,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!","hyst":"{location.street}… il {location.number_wrong}! Venite!"}}},{"id":"q_cosa","label":"Cosa sta succedendo?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Ho paura!"}},{"id":"q_dove_lui","label":"Dove si trova lui esattamente?","cost_s":5,"reveals":["posizione"],"reply":{"calm":"{sc.d}","panic":"{sc.d} Venite, presto!"},"reply_flag":{"flag":"cede","calm":"{sc.tl_r}","panic":"{sc.tl_r} Fate presto!"}},{"id":"q_armi","label":"Sa se ha armi con sé?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"Non lo so… una volta mi ha fatto vedere un coltello.","panic":"Non lo so… una volta mi ha fatto vedere un coltello. Fate presto, vi prego!"}},{"id":"a_rassicura","type":"reassure","label":"Chiuda a chiave, non apra per nessun motivo e resti in una stanza lontana dalla porta. Resto in linea con lei.","cost_s":6,"panic_delta":-18,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sicurezza.molestie","acceptable_event_types":["sicurezza.violenza_domestica"],"agencies_required":["{location.police}"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","posizione"],"hint_debrief":"Chi è perseguitato non va messo in attesa. Dove si trova l''aggressore e se è armato decidono come intervengono le forze dell''ordine."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_043', 'Rumori molesti', 'sicurezza', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_043","title":"Rumori molesti","category":"sicurezza","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[1,4]},"sc":{"choice":[{"w":"C''è una festa nell''appartamento sopra, musica altissima alle due di notte, non si dorme.","wd":"Musica ad alto volume da una festa, notte fonda","event":"sicurezza.disturbo","ag":["{location.police}"],"sev":{"optimal_s":1800,"acceptable_s":3600,"limit_s":7200},"acc":[],"wp":"Una festa qui sopra, la musica fa tremare i vetri! Sono le due di notte!","b":"Bambini? No, sono ragazzi, avranno vent''anni.","bd":"Nessun bambino: ragazzi sui vent''anni","k":"Sono studenti, in affitto da poco. Non è la prima festa, ma mai fino a quest''ora.","kd":"Studenti in affitto, feste frequenti","hint":"Una chiamata per «rumori» va sempre fatta descrivere: qui era una festa, un disturbo della quiete da passare alle forze dell''ordine senza urgenza."},{"w":"Sopra di me urlano e si sentono dei colpi da mezz''ora… sembra che spacchino qualcosa.","wd":"Urla e colpi dall''appartamento sopra da mezz''ora","event":"sicurezza.violenza_domestica","ag":["{location.police}"],"sev":{"optimal_s":240,"acceptable_s":600,"limit_s":1200},"acc":["sicurezza.lite_violenza"],"wp":"Urlano da mezz''ora, si sentono dei colpi fortissimi! Adesso è caduto qualcosa!","b":"Sì… c''è una bambina piccola, la sento piangere ogni tanto.","bd":"C''è una bambina piccola in casa","k":"È una coppia… lei la incrocio in ascensore, ogni tanto ha dei lividi. Adesso la sento piangere e chiedere di smettere.","kd":"Coppia; la donna ha avuto lividi in passato, ora piange e chiede di smettere","hint":"«Urla e colpi» possono essere una lite qualsiasi: chiedere chi abita lì e se è già successo ha fatto emergere una violenza domestica, con una bambina in casa. È urgente."},{"w":"Il cane del vicino abbaia da sei ore, i padroni sono via.","wd":"Cane che abbaia da ore, proprietari assenti","event":"sicurezza.disturbo","ag":["{location.police}"],"sev":{"optimal_s":3600,"acceptable_s":7200,"limit_s":14400},"acc":[],"wp":"Il cane del vicino abbaia da sei ore! Sei ore! Non ce la faccio più!","b":"No, in casa non c''è nessuno, solo il cane.","bd":"Casa vuota, solo il cane","k":"Sì, i signori del terzo, sono partiti stamattina. Il cane è da solo sul balcone.","kd":"Proprietari partiti, cane solo sul balcone","hint":"Un cane che abbaia da ore è un disturbo, non un''emergenza: si passa alle forze dell''ordine senza priorità, dopo aver escluso persone in pericolo."}],"weights":[45,25,30]}},"caller":{"gender":"any","phone_type":"any","panic_start":15,"ring_patience_s":35,"hold_patience_s":30,"reliability":1,"callback_chance":0.7},"opening":{"calm":"Buonasera, scusate l''ora, chiamo per dei rumori dall''appartamento vicino.","panic":"Pronto, c''è un rumore terribile qui sopra!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, appartamento vicino a quello del chiamante"},"rumori":{"label":"Cosa si sente","display":"{sc.wd}"},"bambini":{"label":"Bambini","display":"{sc.bd}"},"precedenti":{"label":"Chi abita lì","display":"{sc.kd}"}},"nodes":[{"id":"q_dove","label":"Che indirizzo ha il palazzo? Via e civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["{location.street} {location.number}.","Allora, {location.street} {location.number}. Io sono al {location.floor_text}."],"panic":"{location.street}… il {location.number}!"}},{"id":"q_cosa","label":"Che rumori sente esattamente?","cost_s":6,"reveals":["rumori"],"reply":{"calm":"{sc.w}","panic":"{sc.wp}"}},{"id":"q_bambini","label":"Sa se in quella casa ci sono bambini?","cost_s":5,"reveals":["bambini"],"requires":["q_cosa"],"reply":{"calm":"{sc.b}","panic":"{sc.b}"}},{"id":"q_conosce","label":"Conosce chi abita lì? È già successo altre volte?","cost_s":7,"reveals":["precedenti"],"requires":["q_cosa"],"reply":{"calm":"{sc.k}","panic":"{sc.k}"}},{"id":"a_rassicura","type":"reassure","label":"Ha fatto bene a chiamare. Resti in casa e non intervenga di persona: mandiamo una pattuglia.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Va bene, grazie. Resto qui.","panic":"Va bene… però fate presto."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":"{sc.ag}","severity":"{sc.sev}","critical_facts":["rumori"],"hint_debrief":"{sc.hint}"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_044', 'Pericolo sulla strada', 'sicurezza', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_044","title":"Pericolo sulla strada","category":"sicurezza","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["colline","industriale","residenziale"],"floor":[0,0]},"sc":{"choice":[{"w":"Davanti a me c''è un''auto che zigzaga, finisce sull''altra corsia, secondo me è ubriaco.","wd":"Auto che zigzaga invadendo l''altra corsia","v":"Una Panda rossa, la targa inizia con EF.","vd":"Panda rossa, targa che inizia con EF","event":"sicurezza.pericolo_viabilita","ag":["{location.police}"]},{"w":"C''è una macchina contromano sul viale! Sta andando dritta verso le altre!","wd":"Auto contromano","v":"Una station wagon grigia, non vedo la targa.","vd":"Station wagon grigia","event":"sicurezza.pericolo_viabilita","ag":["{location.police}"]},{"w":"Un camion ha perso il carico, ci sono dei tubi di ferro in mezzo alla carreggiata!","wd":"Tubi di ferro in carreggiata persi da un camion","v":"Il camion non si è fermato, era bianco.","vd":"Camion bianco, non si è fermato","event":"sicurezza.pericolo_viabilita","ag":["{location.police}","115"]}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.3},"opening":{"calm":"Buonasera, sto guidando e c''è una situazione pericolosa sulla strada.","panic":"Pronto! C''è un pericolo sulla strada, qualcuno si farà male!"},"facts":{"indirizzo":{"display":"{location.street}, verso {location.landmark}"},"pericolo":{"label":"Pericolo","display":"{sc.wd}"},"veicoli":{"display":"{sc.vd}"}},"nodes":[{"id":"q_dove","label":"Su che strada si trova e in che direzione sta andando?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Sono in {location.street}, verso {location.landmark}.","panic":"{location.street}! Verso {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_cosa","label":"Cosa vede esattamente?","cost_s":6,"reveals":["pericolo"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Venite, presto!"}},{"id":"q_veicolo","label":"Riesce a descrivermi il veicolo? Colore, modello, targa?","cost_s":6,"reveals":["veicoli"],"reply":{"calm":"{sc.v}","panic":"{sc.v} Ho paura!"}},{"id":"a_accosta","type":"reassure","label":"Se sta guidando si fermi in un punto sicuro prima di continuare a parlare, e non provi a inseguirlo.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Ok, accosto.","panic":"Va bene, mi fermo!"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["incendio_tecnico.danni_maltempo"],"agencies_required":"{sc.ag}","agencies_acceptable":["115"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","veicoli"],"hint_debrief":"Per un pericolo in movimento servono strada, direzione e descrizione del veicolo: le pattuglie devono sapere dove intercettarlo."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_045', 'Aggressione all''autista', 'sicurezza', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_045","title":"Aggressione all''autista","category":"sicurezza","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"sc":{"choice":[{"w":"Un passeggero ha preso a pugni l''autista del bus! Adesso è sceso e sta andando via a piedi.","wd":"Autista del bus aggredito, l''aggressore si allontana a piedi","f":"L''autista perde sangue dal naso, dice che non ci vede bene da un occhio.","fd":"Autista ferito al volto","ag":["{location.police}","118"]},{"w":"Alla fermata un uomo sta molestando una ragazza, la tocca, lei piange… è ancora qui.","wd":"Uomo che molesta una ragazza alla fermata, ancora presente","f":"Lei non è ferita, ma è sconvolta.","fd":"Nessun ferito, vittima sconvolta","ag":["{location.police}"]},{"w":"Un tizio ha minacciato il controllore con un coltello ed è sceso alla fermata.","wd":"Controllore minacciato con un coltello, l''uomo è sceso","f":"No, nessuno è ferito.","fd":"Nessun ferito","ag":["{location.police}"]}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":60,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, sull''autobus c''è stata un''aggressione.","panic":"Pronto! Un''aggressione sull''autobus, presto!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"evento":{"display":"{sc.wd}"},"feriti":{"display":"{sc.fd}"},"descrizione":{"label":"Descrizione","display":"Uomo sui quarant''anni, giubbotto verde, barba"}},"nodes":[{"id":"q_dove","label":"Dove si trova l''autobus? Via o fermata.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Alla fermata di {location.street}, c''è {location.landmark} lì vicino.","panic":"{location.street}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicur{g.o}!"}}},{"id":"q_cosa","label":"Cosa è successo?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Fate presto, vi prego!"}},{"id":"q_feriti","label":"Ci sono feriti?","cost_s":4,"reveals":["feriti"],"reply":{"calm":"{sc.f}","panic":"{sc.f} Fate presto, vi prego!"}},{"id":"q_descr","label":"Com''è fatto l''aggressore e dove è andato?","cost_s":6,"reveals":["descrizione"],"reply":{"calm":"Sui quarant''anni, giubbotto verde, barba. È andato verso {location.landmark}.","panic":"Sui quarant''anni, giubbotto verde, barba. È andato verso {location.landmark}. Fate presto, vi prego!"}},{"id":"a_rassicura","type":"reassure","label":"Restate sull''autobus con le porte chiuse e non inseguitelo.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sicurezza.aggressione","acceptable_event_types":["sicurezza.molestie","sicurezza.lite_violenza"],"agencies_required":"{sc.ag}","agencies_acceptable":["118"],"severity":{"optimal_s":120,"acceptable_s":300,"limit_s":900},"critical_facts":["indirizzo","descrizione"],"hint_debrief":"Chiedere se ci sono feriti decide il 118; la descrizione dell''aggressore aiuta a fermarlo mentre è ancora vicino."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_053', 'Stanno rubando un''auto', 'sicurezza', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_053","title":"Stanno rubando un''auto","category":"sicurezza","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro","industriale"],"floor":[0,0]},"sc":{"choice":[{"w":"Due ragazzi hanno rotto il finestrino di una macchina e stanno smontando la radio.","wd":"Due giovani che rubano l''autoradio da un''auto con finestrino rotto","s":"Sono ancora lì.","sd":"Ancora sul posto"},{"w":"Hanno appena rubato la mia macchina! L''ho vista partire dal parcheggio!","wd":"Furto d''auto appena avvenuto","s":"È andata verso {location.landmark}, una Golf grigia, targa FG 214.","sd":"Golf grigia targa FG 214 verso {location.landmark}"}]}},"caller":{"gender":"any","phone_type":"any","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, stanno rubando una macchina qui sotto.","panic":"Pronto! Mi hanno rubato la macchina!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"evento":{"display":"{sc.wd}"},"fuga":{"label":"Dove sono ora","display":"{sc.sd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, proprio davanti c''è {location.landmark}.","panic":"{location.street}!"}},{"id":"q_cosa","label":"Cosa sta succedendo?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Venite, presto!"}},{"id":"q_ora","label":"Sono ancora lì? Da che parte sono andati?","cost_s":5,"reveals":["fuga"],"reply":{"calm":"{sc.s}","panic":"{sc.s} Ho paura!"}},{"id":"a_rassicura","type":"reassure","label":"Non intervenga: continui a osservare da dove si trova, se è al sicuro.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sicurezza.furto_in_corso","agencies_required":["{location.police}"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","fuga"],"hint_debrief":"Per un furto appena avvenuto contano direzione di fuga e descrizione del veicolo: le pattuglie possono ancora intercettarlo."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_056', 'Persona in crisi', 'sicurezza', 1, 6, 50, 3, 'sera,notte', 0, 0, '{"code":"SIC_056","title":"Persona in crisi","category":"sicurezza","phase":1,"difficulty":6,"weight":50,"min_rank":3,"is_active":0,"time_bands":["sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"open":"Pronto… scusi. Non so neanche perché ho chiamato. È che stasera non ce la faccio più.","open_p":"Pronto… io… scusi, non so cosa fare. Non ce la faccio più.","cosa":"Ho perso il lavoro due mesi fa e non l''ho detto a nessuno. Stasera è arrivata un''altra lettera della banca… e mi sono sentit{g.o} schiacciat{g.o}. Come se non ci fosse più una via d''uscita.","cosa_d":"Ha perso il lavoro, difficoltà economiche, non ne ha parlato con nessuno","rischio":"…Ci ho pensato, sì. Stasera più del solito. Ma non ho fatto niente. Ho chiamato voi.","rischio_d":"Riferisce pensieri di farsi del male; non ha fatto nulla","qualcuno":"Mia sorella abita qui vicino… ma non volevo farla preoccupare. Lei ha già i suoi problemi.","qualcuno_d":"Una sorella che abita vicino"},{"open":"Buonasera… mi scusi se disturbo. Oggi è un anno che sono rimast{g.o} sol{g.o}, e stasera è più difficile del solito.","open_p":"Buonasera… scusi. Non riesco a smettere di piangere… non so a chi altro dirlo.","cosa":"Quarant''anni insieme, e adesso la casa è così silenziosa. I figli sono lontani, li sento la domenica. Stasera ho pensato: a cosa serve andare avanti così?","cosa_d":"Lutto: un anno dalla morte del coniuge; vive da sol{g.o}, figli lontani","rischio":"Non lo so… a volte penso che sarebbe più semplice non svegliarsi più. Ma non ho fatto niente, no.","rischio_d":"Pensieri di morte; nessun gesto compiuto","qualcuno":"Mio figlio è a Torino… La vicina del piano di sotto, forse. È tanto gentile, ha le mie chiavi.","qualcuno_d":"Figli lontani; la vicina del piano di sotto ha le chiavi"}]}},"caller":{"gender":"any","phone_type":"any","panic_start":55,"ring_patience_s":40,"hold_patience_s":10,"reliability":0.9,"callback_chance":0.6,"voice":{"age":"adult"}},"opening":{"calm":"{sc.open}","panic":"{sc.open_p}"},"callback_opening":{"calm":"Pronto… sono io, di prima. È caduta la linea… pensavo che aveste chiuso.","panic":"Pronto… sono di nuovo io. Si è chiusa la chiamata e… non volevo restare da sol{g.o}."},"idle_lines":{"calm":["…È ancora lì?","(silenzio) …Pronto?"],"panic":["Pronto? …C''è ancora qualcuno?"]},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text}"},"nome":{"label":"Nome","display":"{caller_first}"},"evento":{"label":"Cosa sta vivendo","display":"{sc.cosa_d}"},"rischio":{"label":"Sicurezza","display":"{sc.rischio_d}"},"supporto":{"label":"Chi può aiutare","display":"{sc.qualcuno_d}"}},"nodes":[{"id":"q_nome","label":"Come si chiama? Io sono qui e la ascolto.","cost_s":5,"panic_delta":-5,"reveals":["nome"],"reply":{"calm":"{caller_first}.","panic":"…{caller_first}."}},{"id":"q_cosa","label":"Mi racconti cosa sta succedendo stasera. Ho tutto il tempo che serve.","cost_s":12,"panic_delta":-5,"reveals":["evento"],"reply":{"calm":"{sc.cosa}","panic":"(una lunga pausa) {sc.cosa}"}},{"id":"q_sicuro","label":"Glielo chiedo apertamente: sta pensando di farsi del male?","cost_s":8,"reveals":["rischio"],"reply":{"calm":"{sc.rischio}","panic":"(silenzio) …{sc.rischio}"}},{"id":"q_dove","label":"Dove si trova adesso? Mi dice l''indirizzo, così non resta da sol{g.o}?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Sono a casa… {location.street} {location.number}, al {location.floor_text}.","panic":"A casa… {location.street} {location.number}."},"error":{"threshold":65,"chance":0.7,"fact":"indirizzo","display":"Per ora preferisce non dire dove si trova","reply":{"calm":"Preferirei di no… non voglio che venga qualcuno a suonare il campanello.","panic":"No… non voglio che venga nessuno. Voglio solo parlare."}}},{"id":"q_qualcuno","label":"C''è qualcuno che potrebbe stare con lei stasera? Un familiare, un amico, un vicino?","cost_s":8,"reveals":["supporto"],"reply":{"calm":"{sc.qualcuno}","panic":"(una lunga pausa) {sc.qualcuno}"}},{"id":"a_ascolto","type":"reassure","label":"Ha fatto bene a chiamare. Resto in linea con lei: stasera non deve affrontare tutto questo da sol{g.o}.","cost_s":8,"panic_delta":-20,"reply":{"calm":"…Grazie. Non pensavo che qualcuno avesse voglia di ascoltarmi.","panic":"(sottovoce) …Va bene."},"repeat":{"calm":["Va bene… sono ancora qui.","Parlare mi fa bene, credo. Mi sento un po'' meno sol{g.o}."],"panic":["Sono qui… sono ancora qui.","(una lunga pausa) …Grazie di non avermi chiuso il telefono."]}},{"id":"a_aiuto","type":"reassure","label":"Adesso le mando qualcuno che può aiutarla e stare con lei. Intanto restiamo al telefono insieme, d''accordo?","cost_s":7,"panic_delta":-10,"requires":["q_dove"],"reply":{"calm":"…Va bene. Sì. Lascio la porta accostata.","panic":"(una lunga pausa) …Va bene. Ma lei resta al telefono, vero?"}},{"id":"a_sbrigativo","type":"reassure","label":"Guardi, il 112 è per le emergenze: per queste cose può rivolgersi al suo medico di base.","cost_s":5,"panic_delta":20,"reply":{"calm":"…Ecco. Lo sapevo. (silenzio) Scusi se ho disturbato… però non riattacchi, per favore.","panic":"(silenzio) …Allora anche voi. Scusi. Resto ancora un attimo in linea, se posso."}}],"truth":{"event_type":"sicurezza.persona_in_crisi","acceptable_event_types":["sanitaria.malore"],"agencies_required":["118"],"agencies_acceptable":["PS","CC"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","rischio"],"hint_debrief":"Chi chiama in un momento di crisi va ascoltato con calma e senza giudicare: il nome, dove si trova, se è al sicuro e chi può starle vicino. Chiedere apertamente se pensa di farsi del male non aumenta il rischio, e restare in linea fino all''arrivo dei soccorsi è già un aiuto. Liquidare la chiamata come «non urgente» la peggiora. Dopo l''intervento, la persona può essere indirizzata ai servizi di ascolto, come Telefono Amico, e al Centro di salute mentale della propria azienda sanitaria."}}', 1, 0)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_059', 'Spari o petardi?', 'sicurezza', 1, 5, 75, 2, 'pomeriggio,sera,notte', 1, 0, '{"code":"SIC_059","title":"Spari o petardi?","category":"sicurezza","phase":1,"difficulty":5,"weight":75,"min_rank":2,"time_bands":["pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.35,"max":2,"delay_s":[20,120],"near_twin_chance":0.3},"witness_opening":{"calm":"Buonasera, ho sentito dei botti forti in {location.street}, dove c''è {location.landmark}. Non so se erano spari.","panic":"Pronto! Dei colpi in {location.street}! C''è {location.landmark} lì vicino!"},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,3]},"sc":{"choice":[{"colpi":"Una raffica, tanti scoppi di fila, ta-ta-ta-ta… e ho visto delle scintille rosse.","colpi_p":"Una raffica! Tanti botti di fila, e delle scintille!","colpi_d":"Raffica di scoppi ravvicinati, scintille colorate","visto":"In fondo al parcheggio ci sono dei ragazzi… ridono e scappano via di corsa.","visto_d":"Ragazzi che ridono e si allontanano di corsa","feriti":"No, no, nessuno a terra. Solo un gran fumo che puzza di zolfo.","feriti_d":"Nessun ferito","odore":"Puzza di zolfo, come a Capodanno, e c''è un fumo bianco basso.","odore_p":"Zolfo! Puzza di zolfo, e c''è fumo bianco dappertutto!","odore_d":"Odore di zolfo, fumo bianco","event":"sicurezza.disturbo","ag":["{location.police}"],"acc":["sicurezza.persona_sospetta"],"sev":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600},"hint":"Una raffica con scintille, odore di zolfo e ragazzi che ridono sono petardi: un disturbo, non una sparatoria. Le domande giuste (quanti colpi, chi si vede, se c''è qualcuno a terra) evitano di far correre tutti nel posto sbagliato."},{"colpi":"Due botti secchi, forti… e subito dopo una moto che si allontanava sgasando.","colpi_p":"Due botti! Fortissimi! E poi una moto che scappava!","colpi_d":"Due scoppi secchi seguiti da una moto che accelera","visto":"Ho guardato giù: c''era solo uno scooter vecchio che ripartiva, faceva un fumo nero dal tubo.","visto_d":"Uno scooter che riparte facendo fumo nero dallo scarico","feriti":"No… nessuno. La strada adesso è vuota.","feriti_d":"Nessun ferito, strada vuota","odore":"Puzza di benzina bruciata, di marmitta.","odore_p":"Puzza di benzina! Di marmitta bruciata!","odore_d":"Odore di gas di scarico","event":"impropria.informazioni","ag":[],"acc":["sicurezza.disturbo"],"sev":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"hint":"Due botti seguiti da uno scooter che sgasa e fa fumo nero sono ritorni di fiamma della marmitta: dopo aver escluso feriti e persone in fuga, la chiamata si chiude con una rassicurazione."},{"colpi":"Tre colpi secchi, uno dopo l''altro. Non come i petardi… più sordi, più forti.","colpi_p":"Tre colpi! Secchi! Non erano petardi, glielo giuro!","colpi_d":"Tre colpi secchi e sordi, a breve distanza","visto":"C''è un uomo a terra davanti al bar… e un altro che è scappato correndo verso {location.landmark}!","visto_d":"Un uomo a terra davanti al bar, un altro fuggito a piedi verso {location.landmark}","feriti":"Si tiene la gamba… c''è sangue sul marciapiede. Si muove, urla. La gente gli sta intorno.","feriti_d":"Uomo ferito alla gamba, sanguina, cosciente","odore":"Non lo so… non sono uscit{g.o}, ho paura.","odore_p":"Non lo so! Non sono uscit{g.o}, ho paura!","odore_d":"Non verificato: il chiamante resta in casa","event":"sicurezza.aggressione","ag":["{location.police}","118"],"acc":["sicurezza.lite_violenza"],"sev":{"optimal_s":120,"acceptable_s":300,"limit_s":600},"hint":"Tre colpi sordi, un uomo a terra e uno che fugge: sono spari. Servono subito forze dell''ordine e 118, e chi chiama deve restare al riparo. La direzione di fuga è un''informazione preziosa per le pattuglie."}],"weights":[45,30,25]}},"caller":{"gender":"any","phone_type":"any","panic_start":50,"ring_patience_s":35,"hold_patience_s":25,"reliability":0.95,"callback_chance":0.5,"voice":{"age":"adult"}},"opening":{"calm":["Buonasera… ho sentito dei botti qui sotto, forti. Non so se erano spari o petardi.","Pronto, scusi… qui in strada hanno fatto dei botti, ma non sembravano normali."],"panic":"Pronto! Hanno sparato! Cioè… credo! Dei colpi qui sotto!","hyst":"Pronto! Sparano! Sparano qui sotto! Venite!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"rumori":{"label":"Cosa ha sentito","display":"{sc.colpi_d}"},"persone":{"label":"Cosa vede","display":"{sc.visto_d}"},"feriti":{"display":"{sc.feriti_d}"},"indizi":{"label":"Odori e fumo","display":"{sc.odore_d}"}},"nodes":[{"id":"q_dove","label":"Dove ha sentito i colpi? Via e un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["In {location.street}, verso {location.landmark}.","Qui in {location.street}… sotto casa mia. Lì vicino c''è {location.landmark}."],"panic":"{location.street}! C''è {location.landmark} lì vicino!"},"error":{"threshold":70,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… o più in là, non so da dove venivano!"}}},{"id":"q_colpi","label":"Quanti colpi ha sentito? Com''erano: una raffica, colpi secchi, scintille?","cost_s":7,"reveals":["rumori"],"reply":{"calm":"{sc.colpi}","panic":"{sc.colpi_p}"}},{"id":"q_visto","label":"Senza uscire: vede qualcuno? Gente che scappa, qualcuno a terra?","cost_s":7,"reveals":["persone"],"reply":{"calm":"{sc.visto}","panic":"{sc.visto} Oddio…"}},{"id":"q_feriti","label":"C''è qualcuno ferito? Come sta?","cost_s":5,"requires":["q_visto"],"reveals":["feriti"],"reply":{"calm":"{sc.feriti}","panic":"{sc.feriti} Venite!"}},{"id":"q_odore","label":"Sente un odore particolare? Vede del fumo?","cost_s":5,"reveals":["indizi"],"reply":{"calm":"{sc.odore}","panic":"{sc.odore_p}"}},{"id":"a_riparo","type":"reassure","label":"Resti in casa, lontano dalle finestre, e non esca a guardare. Mi dica tutto quello che vede da lì.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene, mi sposto. Guardo solo da dietro la tenda.","panic":"Sì… sì, mi allontano dalla finestra."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":"{sc.ag}","severity":"{sc.sev}","critical_facts":["indirizzo","rumori","persone"],"hint_debrief":"{sc.hint}"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_064', 'Anziano confuso alla fermata', 'sicurezza', 1, 4, 70, 2, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_064","title":"Anziano confuso alla fermata","category":"sicurezza","phase":1,"difficulty":4,"weight":70,"min_rank":2,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"home":{"pool":"stradario","zones":["residenziale","centro","colline"],"floor":[0,3]},"nonno_n":{"pool":"names_m"},"nonno_s":{"pool":"surnames"},"sc":{"choice":[{"stato":"È in pigiama sotto il cappotto, con le pantofole. Trema, ha le mani fredde.","stato_p":"È in pigiama! Con le pantofole! Trema tutto, poveretto!","stato_d":"In pigiama e pantofole, infreddolito","dice":"Dice che deve andare a lavorare in fabbrica, che è in ritardo… e che si chiama «Pierino».","sev":{"optimal_s":420,"acceptable_s":900,"limit_s":1800}},{"stato":"È vestito bene, giacca e cravatta, ma è tutto sudato e dice che ha sete. Qui fa un caldo…","stato_p":"È tutto sudato, dice che ha sete, e qui ci sono trenta gradi!","stato_d":"Vestito, sudato, ha sete","dice":"Dice che aspetta la moglie, che deve arrivare con il treno… ma qui il treno non passa.","sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400}},{"stato":"Sta bene, mi sembra… è solo agitato, continua a chiedere che ore sono.","stato_p":"È agitato, vuole salire su tutti gli autobus, lo sto tenendo per un braccio!","stato_d":"Agitato, tenta di salire sugli autobus","dice":"Dice che deve tornare a casa, «vicino alla chiesa», ma non sa dirmi quale.","sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400}}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":30,"ring_patience_s":40,"hold_patience_s":40,"reliability":0.95,"callback_chance":0.5,"voice":{"age":"adult"}},"opening":{"calm":["Buongiorno, sono alla fermata dell''autobus: c''è un signore anziano che non sa dove si trova. Non so a chi chiamare.","Salve, scusi… c''è un signore qui alla fermata, molto anziano, mi sembra che si sia perso."],"panic":"Pronto? C''è un anziano che si è perso, è confuso, non so cosa fare!"},"facts":{"indirizzo":{"display":"Fermata dell''autobus in {location.street}, presso {location.landmark}"},"risposte":{"label":"Cosa dice lui","display":"{sc.dice}"},"identita":{"label":"Identità","display":"{nonno_n} {nonno_s} (dal braccialetto), numero della figlia"},"casa":{"label":"Abitazione","display":"{home.street} {home.number} (dalla tessera dell''autobus)"},"stato":{"label":"Condizioni","display":"{sc.stato_d}"}},"nodes":[{"id":"q_dove","label":"Dove vi trovate? Quale fermata, in che via?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":["Alla fermata in {location.street}, c''è {location.landmark} lì vicino.","In {location.street}, alla pensilina. Davanti c''è {location.landmark}."],"panic":"{location.street}! Alla fermata! C''è {location.landmark} lì vicino!"}},{"id":"q_chi","label":"Gli chieda come si chiama e dove abita.","cost_s":8,"reveals":["risposte"],"reply":{"calm":"Aspetti che glielo chiedo… {sc.dice}","panic":"Gliel''ho chiesto… {sc.dice}"}},{"id":"q_oggetti","label":"Guardi se ha addosso qualcosa con il nome: un braccialetto, una catenina, un biglietto in tasca.","cost_s":10,"reveals":["identita"],"reply":{"calm":"Aspetti… sì, ha un braccialetto! C''è scritto {nonno_n} {nonno_s}, e sotto un numero di telefono: «figlia».","panic":"Un braccialetto! {nonno_n} {nonno_s}! E un numero, c''è scritto «figlia»!"}},{"id":"q_tessera","label":"Ha un portafoglio? Cerchi una tessera dell''autobus o un documento con l''indirizzo.","cost_s":10,"requires":["q_oggetti"],"reveals":["casa"],"reply":{"calm":"Mi lascia guardare… sì, la tessera del bus. C''è l''indirizzo: {home.street} {home.number}.","panic":"La tessera! {home.street} {home.number}!"}},{"id":"q_stato","label":"Come sta? È vestito in modo adatto, ha freddo, si è fatto male?","cost_s":6,"reveals":["stato"],"reply":{"calm":"{sc.stato}","panic":"{sc.stato_p}"}},{"id":"a_resta","type":"reassure","label":"Resti con lui, gli parli con calma e non lo lasci salire su un autobus: le mando una pattuglia.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene, resto qui. Gli ho dato la mia giacca… adesso è più tranquillo.","panic":"Va bene… lo tengo qui con me."}}],"truth":{"event_type":"sicurezza.persona_scomparsa","acceptable_event_types":["sanitaria.malore"],"agencies_required":["{location.police}"],"agencies_acceptable":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","identita","stato"],"hint_debrief":"Una persona con demenza spesso non sa dire chi è: braccialetti, tessere e documenti valgono più delle sue risposte. Con nome e indirizzo le forze dell''ordine rintracciano i familiari, e intanto chi chiama deve restare con lui."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_005', 'Tamponamento stradale', 'sicurezza', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_005","title":"Tamponamento stradale","category":"sicurezza","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","industriale","colline"],"floor":[0,0]},"injury":{"choice":[{"text":"No, siamo tutti fuori dalle macchine, solo tanto spavento.","display":"Nessun ferito, tutti fuori dai veicoli","agencies":[],"event":"sicurezza.incidente_stradale"},{"text":"La signora dell''altra macchina dice che le fa male il collo, è ancora seduta dentro.","display":"Una donna con dolore al collo, ancora nel veicolo","agencies":["118"],"event":"sanitaria.trauma_stradale"}],"weights":[55,45]},"veh":{"choice":[{"text":"Due macchine. Niente fumo, solo il paraurti distrutto.","display":"Due auto, nessun fumo o perdita","agencies":[]},{"text":"Due macchine… e dalla mia esce del liquido sotto il motore, sento odore di benzina.","display":"Due auto, perdita di liquido e odore di benzina","agencies":["115"]}],"weights":[75,25]},"road":{"choice":[{"text":"Siamo a bordo strada, le macchine passano piano.","display":"Veicoli a bordo strada, traffico lento"},{"text":"Siamo in mezzo alla carreggiata, la gente frena all''ultimo!","display":"Veicoli in mezzo alla carreggiata, rischio di altri urti"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":40,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.8},"opening":{"calm":["Pronto, buonasera. Ho appena avuto un incidente, un tamponamento.","Buonasera, guardi, mi hanno appena tamponato. Siamo fermi in mezzo alla strada."],"panic":"Pronto?! C''è stato un incidente, mi hanno tamponato, qui è un casino!"},"callback_opening":{"calm":"Pronto, ho chiamato prima per il tamponamento in {location.street}, è caduta la linea.","panic":"Ancora io, per l''incidente! Non è arrivato nessuno!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"feriti":{"display":"{injury.display}"},"veicoli":{"display":"{veh.display}"},"pericoli":{"display":"{road.display}"}},"nodes":[{"id":"q_dove","label":"In che strada si trova? C''è un incrocio o un punto di riferimento?","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":["In {location.street}, poco dopo {location.landmark}.","Siamo in {location.street}… abbiamo appena passato {location.landmark}."],"panic":"In {location.street}… c''è {location.landmark} lì vicino, credo!"},"error":{"threshold":65,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… o forse no, non lo so, non sono di qui!"}}},{"id":"q_feriti","label":"Ci sono feriti? Qualcuno è rimasto dentro un''auto?","cost_s":6,"reveals":["feriti"],"reply":{"calm":"{injury.text}","panic":"{injury.text} Fate presto, vi prego!"}},{"id":"q_veicoli","label":"Quanti veicoli sono coinvolti? Esce fumo o perdono liquidi?","cost_s":6,"reveals":["veicoli"],"reply":{"calm":"{veh.text}","panic":"{veh.text} Fate presto, vi prego!"}},{"id":"q_strada","label":"Le auto bloccano la strada? È pericoloso per chi passa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{road.text}","panic":"{road.text} Venite, presto!"}},{"id":"a_sicurezza","type":"reassure","label":"Accendete le quattro frecce e mettetevi al sicuro oltre il guardrail o sul marciapiede.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Sì, va bene, lo dico anche agli altri.","panic":"Ok… ok, ci spostiamo."}}],"truth":{"event_type":"{injury.event}","agencies_required":["{location.police}","{injury.agencies}","{veh.agencies}"],"severity":{"optimal_s":300,"acceptable_s":900,"limit_s":1800},"critical_facts":["indirizzo","feriti","veicoli"],"hint_debrief":"In un incidente la competenza tra Polizia e Carabinieri dipende dalla zona; feriti e perdite di carburante aggiungono 118 e Vigili del fuoco."},"duplicates":{"chance":0.35,"max":1,"delay_s":[30,180],"near_twin_chance":0.1},"witness_opening":{"calm":"Buonasera, in {location.street} c''è stato un tamponamento, ci sono due auto ferme.","panic":"Pronto, un incidente in {location.street}, due macchine!"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_013', 'Auto fuori strada, conducente incastrato', 'sanitaria', 1, 6, 75, 2, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_013","title":"Auto fuori strada, conducente incastrato","category":"sanitaria","phase":1,"difficulty":6,"weight":75,"min_rank":2,"time_bands":["mattina","pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","duplicates":{"chance":0.7,"max":3,"delay_s":[20,160],"near_twin_chance":0},"variables":{"location":{"pool":"stradario","zones":["colline","industriale"],"floor":[0,0]},"veh":{"choice":[{"text":"C''è un odore fortissimo di benzina, sotto la macchina c''è una pozza!","display":"Forte odore di benzina, pozza sotto l''auto"},{"text":"Esce del fumo dal cofano, sempre di più!","display":"Fumo dal cofano in aumento"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":72,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.9,"voice":{"age":"adult","style":"breathless"}},"opening":{"calm":"Pronto, un''auto è finita fuori strada contro un albero, c''è uno dentro che non riesce a uscire!","panic":"Pronto! Incidente! Una macchina contro un albero, c''è uno incastrato dentro!"},"witness_opening":{"calm":"Buonasera, sto passando in {location.street}: c''è un''auto finita contro un albero, si stanno fermando altre persone.","panic":"Pronto, in {location.street} c''è una macchina schiantata contro un albero!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"feriti":{"display":"Conducente incastrato, sanguina dalla testa, risponde a fatica"},"veicoli":{"display":"{veh.display}"},"pericoli":{"display":"Auto ferma di traverso sulla carreggiata"}},"nodes":[{"id":"q_dove","label":"Dove siete esattamente? Via e punto di riferimento.","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, poco dopo {location.landmark}.","panic":"{location.street}! Dopo {location.landmark}!"},"error":{"threshold":70,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo… non lo so!"}}},{"id":"q_feriti","label":"Quante persone sono ferite? Chi è bloccato come sta?","cost_s":7,"reveals":["feriti"],"reply":{"calm":"Solo il conducente. È incastrato, perde sangue dalla testa, risponde a fatica.","panic":"Uno! Incastrato, sangue dalla testa, parla appena!"}},{"id":"q_fuoco","label":"Esce fumo o perde carburante?","cost_s":5,"reveals":["veicoli"],"reply":{"calm":"{veh.text}","panic":"{veh.text}"}},{"id":"q_strada","label":"L''auto blocca la strada? Altri rischi per chi passa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"È di traverso, le macchine devono rallentare.","panic":"È in mezzo alla strada!"}},{"id":"a_sicurezza","type":"reassure","label":"Non spostate il ferito, niente sigarette, mettetevi al sicuro fuori dalla strada.","cost_s":6,"panic_delta":-15,"reply":{"calm":"D''accordo, lo dico agli altri.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sanitaria.trauma_stradale","agencies_required":["118","115","{location.police}"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","feriti"],"hint_debrief":"Una persona incastrata richiede i Vigili del fuoco per l''estricazione, oltre a 118 e forze dell''ordine. I testimoni che chiamano dopo vanno accorpati all''evento."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_049', 'Pedone investito', 'sanitaria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_049","title":"Pedone investito","category":"sanitaria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.45,"max":2,"delay_s":[20,120],"near_twin_chance":0.1},"witness_opening":{"calm":"Buonasera, in {location.street} hanno investito qualcuno. Lì vicino c''è {location.landmark}.","panic":"Pronto! Un investimento in {location.street}!"},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,0]},"sc":{"choice":[{"w":"Una signora anziana è stata investita sulle strisce! La macchina si è fermata, il conducente è sotto shock.","wd":"Anziana investita sulle strisce, conducente fermo sul posto","f":"È a terra, cosciente, si lamenta per la gamba e ha un taglio in testa.","fd":"Cosciente, ferita alla testa e alla gamba","v":"Il conducente è qui, sta seduto sul marciapiede.","vd":"Conducente sul posto"},{"w":"Hanno investito un uomo e sono scappati! Una macchina scura!","wd":"Pedone investito, auto pirata fuggita","f":"Non si muove, respira ma non risponde!","fd":"Non risponde, respira","v":"Una berlina scura, la targa finiva con 7 L, è andata verso {location.landmark}.","vd":"Berlina scura, targa finale «7L», fuggita verso {location.landmark}"},{"w":"Un ciclista è stato urtato da un''auto che girava, è caduto.","wd":"Ciclista urtato da un''auto in svolta","f":"Si è rialzato, sanguina dal gomito e zoppica.","fd":"Si è rialzato, ferita al gomito, zoppica","v":"L''automobilista si è fermato.","vd":"Automobilista sul posto"}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":65,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, hanno investito una persona!","panic":"Pronto! Hanno investito qualcuno, presto!","hyst":"L''hanno preso in pieno! È per terra! Aiuto!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"evento":{"display":"{sc.wd}"},"feriti":{"display":"{sc.fd}"},"veicoli":{"display":"{sc.vd}"}},"nodes":[{"id":"q_dove","label":"Dove è successo? Via e punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, c''è {location.landmark} lì vicino.","panic":"{location.street}! C''è {location.landmark} lì vicino!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicur{g.o}!"}}},{"id":"q_cosa","label":"Cosa è successo?","cost_s":5,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Fate presto!"}},{"id":"q_feriti","label":"Come sta la persona investita? Risponde?","cost_s":6,"reveals":["feriti"],"reply":{"calm":"{sc.f}","panic":"{sc.f} Vi prego, presto!"}},{"id":"q_veicolo","label":"Il veicolo è ancora lì? Com''era?","cost_s":5,"reveals":["veicoli"],"reply":{"calm":"{sc.v}","panic":"{sc.v} Fate presto, per favore!"}},{"id":"a_rassicura","type":"reassure","label":"Non spostate la persona, copritela e deviate il traffico con l''aiuto di altri, restando al sicuro.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sanitaria.trauma_stradale","acceptable_event_types":["sicurezza.incidente_stradale"],"agencies_required":["118","{location.police}"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","feriti"],"hint_debrief":"In un investimento servono sempre 118 e forze dell''ordine. Se il conducente è fuggito, la descrizione dell''auto va presa subito."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_050', 'Motociclista a terra', 'sanitaria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_050","title":"Motociclista a terra","category":"sanitaria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.3,"max":1,"delay_s":[30,150],"near_twin_chance":0},"witness_opening":{"calm":"Buonasera, in {location.street} c''è un motociclista caduto.","panic":"Pronto, un incidente con una moto in {location.street}!"},"variables":{"location":{"pool":"stradario","zones":["colline","industriale"],"floor":[0,0]},"sc":{"choice":[{"w":"Una moto è scivolata in curva, il motociclista è a terra e non si muove.","wd":"Moto scivolata in curva, motociclista immobile","f":"Ha il casco, respira ma non risponde.","fd":"Casco indossato, respira, non risponde","c":"No, niente fumo.","cd":"Nessun fumo o perdita","ag":["118","{location.police}"]},{"w":"È caduto un motociclista, è seduto per terra.","wd":"Motociclista caduto, seduto a terra","f":"Risponde, ma ha la gamba storta e urla dal dolore.","fd":"Cosciente, gamba deformata","c":"No.","cd":"Nessun fumo o perdita","ag":["118","{location.police}"]},{"w":"Una moto si è scontrata con un''auto, il motociclista è volato nel fosso!","wd":"Scontro moto-auto, motociclista nel fosso","f":"È nel fosso, si lamenta, non riesce ad alzarsi.","fd":"Nel fosso, cosciente, non si alza","c":"La moto perde benzina sull''asfalto, c''è una pozza.","cd":"Perdita di benzina dalla moto","ag":["118","115","{location.police}"]}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":60,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, c''è stato un incidente con una moto.","panic":"Pronto! Un motociclista è caduto, presto!"},"facts":{"indirizzo":{"display":"{location.street}, presso {location.landmark} ({location.zone_name})"},"evento":{"display":"{sc.wd}"},"feriti":{"display":"{sc.fd}"},"veicoli":{"display":"{sc.cd}"}},"nodes":[{"id":"q_dove","label":"Dove siete? Strada e punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, poco dopo {location.landmark}.","panic":"{location.street}! Dopo {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicur{g.o}!"}}},{"id":"q_cosa","label":"Cosa è successo?","cost_s":5,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w} Correte!"}},{"id":"q_feriti","label":"Come sta il motociclista? Risponde?","cost_s":6,"reveals":["feriti"],"reply":{"calm":"{sc.f}","panic":"{sc.f} Fate presto, per favore!"}},{"id":"q_perdite","label":"La moto perde carburante o fuma?","cost_s":5,"reveals":["veicoli"],"reply":{"calm":"{sc.c}","panic":"{sc.c} Fate presto, per favore!"}},{"id":"a_casco","type":"reassure","label":"Non togliete il casco e non muovetelo: coprite il ferito e segnalate l''incidente a chi arriva.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene, il casco non lo tocchiamo.","panic":"Ok! Non lo tocchiamo!"}}],"truth":{"event_type":"sanitaria.trauma_stradale","agencies_required":"{sc.ag}","severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","feriti"],"hint_debrief":"Con un motociclista a terra il casco non va tolto: può peggiorare una lesione alla colonna. Una perdita di carburante aggiunge i Vigili del fuoco."}}', 1, 1)
